export default [{"id":"8","jozz":"1","page":"2","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"3","line_end":"3","aya_no":"1","aya_text":"الٓمٓ","aya_text_emlaey":"الم","aya_tafseer":"[1] الٓمٓ هذه الحروف وغيرها من الحروف المقطَّعة في أوائل السور، فيها إشارة إلى إعجاز القرآن؛ فقد وقع به تحدي المشركين، فعجَزوا عن معارضته، وهو مركَّب من هذه الحروف التي تتكون منها لغة العرب. فدَلَّ عجز العرب عن الإتيان بمثله -مع أنهم أفصح الناس- على أن القرآن وحي من الله."},{"id":"9","jozz":"1","page":"2","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"3","line_end":"4","aya_no":"2","aya_text":"ذَٰلِكَ ٱلۡكِتَٰبُ لَا رَيۡبَۛ فِيهِۛ هُدٗى لِّلۡمُتَّقِينَ","aya_text_emlaey":"ذلك الكتاب لا ريب فيه هدى للمتقين","aya_tafseer":"[2] ذلك القرآن هو الكتاب العظيم الذي لا شَكَّ أنه من عند الله، فلا يصحُّ أن يرتاب فيه أحدٌ لوضوحه، ينتفع به المتقون بالعلم النافع والعمل الصالح، وهم الذين يخافون الله، ويتبعون أحكامه."},{"id":"10","jozz":"1","page":"2","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"4","line_end":"5","aya_no":"3","aya_text":"ٱلَّذِينَ يُؤۡمِنُونَ بِٱلۡغَيۡبِ وَيُقِيمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ","aya_text_emlaey":"الذين يؤمنون بالغيب ويقيمون الصلاة ومما رزقناهم ينفقون","aya_tafseer":"[3] وهم الذين يُصَدِّقون بالغيب الذي لا تدركه حواسُّهم ولا عقولهم وحدها؛ لأنه لا يُعْرف إلا بوحي الله إلى رسله، مثل الإيمان بالملائكة، والجنة، والنار، وغير ذلك مما أخبر الله به أو أخبر به رسوله -صلى الله عليه وسلم-، (والإيمان: كلمة جامعة للإقرار بالله، وملائكته، وكتبه، ورسله، واليوم الآخر، والقدر خيره وشره، وتصديق الإقرار بالقول والعمل بالقلب واللسان والجوارح) وهم مع تصديقهم بالغيب يحافظون على أداء الصلاة في مواقيتها أداءً صحيحاً وَفْق ما شرع الله لنبيه محمد -صلى الله عليه وسلم-، ومما أعطيناهم من المال يخرجون صدقة أموالهم الواجبة والمستحبة."},{"id":"11","jozz":"1","page":"2","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"5","line_end":"6","aya_no":"4","aya_text":"وَٱلَّذِينَ يُؤۡمِنُونَ بِمَآ أُنزِلَ إِلَيۡكَ وَمَآ أُنزِلَ مِن قَبۡلِكَ وَبِٱلۡأٓخِرَةِ هُمۡ يُوقِنُونَ","aya_text_emlaey":"والذين يؤمنون بما أنـزل إليك وما أنـزل من قبلك وبالآخرة هم يوقنون","aya_tafseer":"[4] والذين يُصَدِّقون بما أُنزل إليك أيها الرسول من القرآن، وبما أنزل إليك من الحكمة، وهي السنة، وبكل ما أُنزل مِن قبلك على الرسل من كتب، كالتوراة والإنجيل وغيرهما، ويُصَدِّقون بدار الحياة بعد الموت وما فيها من الحساب والجزاء، تصديقاً بقلوبهم يظهر على ألسنتهم وجوارحهم. وخص يوم الآخرة بالذِّكْر؛ لأن الإيمان به من أعظم البواعث على فعل الطاعات، واجتناب المحرمات، ومحاسبة النفس."},{"id":"12","jozz":"1","page":"2","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"7","line_end":"8","aya_no":"5","aya_text":"أُوْلَٰٓئِكَ عَلَىٰ هُدٗى مِّن رَّبِّهِمۡۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ","aya_text_emlaey":"أولئك على هدى من ربهم وأولئك هم المفلحون","aya_tafseer":"[5] أصحاب هذه الصفات على نور من ربهم وبتوفيق مِن خالقهم وهاديهم، وهم الفائزون الذين أدركوا ما طلبوا، ونَجَوا من شرِّ ما منه هربوا."},{"id":"13","jozz":"1","page":"3","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"1","line_end":"2","aya_no":"6","aya_text":"إِنَّ ٱلَّذِينَ كَفَرُواْ سَوَآءٌ عَلَيۡهِمۡ ءَأَنذَرۡتَهُمۡ أَمۡ لَمۡ تُنذِرۡهُمۡ لَا يُؤۡمِنُونَ","aya_text_emlaey":"إن الذين كفروا سواء عليهم أأنذرتهم أم لم تنذرهم لا يؤمنون","aya_tafseer":"[6] إن الذين جحدوا ما أُنزل إليك من ربك استكباراً وطغياناً، لن يقع منهم الإيمان، سواء أخوَّفتهم وحذرتهم -أيها الرسول- من عذاب الله، أم تركت ذلك؛ لإصرارهم على باطلهم."},{"id":"14","jozz":"1","page":"3","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"2","line_end":"3","aya_no":"7","aya_text":"خَتَمَ ٱللَّهُ عَلَىٰ قُلُوبِهِمۡ وَعَلَىٰ سَمۡعِهِمۡۖ وَعَلَىٰٓ أَبۡصَٰرِهِمۡ غِشَٰوَةٞۖ وَلَهُمۡ عَذَابٌ عَظِيمٞ","aya_text_emlaey":"ختم الله على قلوبهم وعلى سمعهم وعلى أبصارهم غشاوة ولهم عذاب عظيم","aya_tafseer":"[7] طبع الله على قلوب هؤلاء وعلى سمعهم، وجعل على أبصارهم غطاء؛ بسبب كفرهم وعنادهم مِن بعد ما تبيَّن لهم الحق، فلم يوفقهم للهدى، ولهم عذاب شديد في نار جهنم."},{"id":"15","jozz":"1","page":"3","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"3","line_end":"4","aya_no":"8","aya_text":"وَمِنَ ٱلنَّاسِ مَن يَقُولُ ءَامَنَّا بِٱللَّهِ وَبِٱلۡيَوۡمِ ٱلۡأٓخِرِ وَمَا هُم بِمُؤۡمِنِينَ","aya_text_emlaey":"ومن الناس من يقول آمنا بالله وباليوم الآخر وما هم بمؤمنين","aya_tafseer":"[8] ومن الناس فريق يتردد متحيِّراً بين المؤمنين والكافرين، وهم المنافقون الذين يقولون بألسنتهم: صَدَّقْنا بالله وباليوم الآخر، وهم في باطنهم كاذبون لم يؤمنوا."},{"id":"16","jozz":"1","page":"3","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"5","line_end":"6","aya_no":"9","aya_text":"يُخَٰدِعُونَ ٱللَّهَ وَٱلَّذِينَ ءَامَنُواْ وَمَا يَخۡدَعُونَ إِلَّآ أَنفُسَهُمۡ وَمَا يَشۡعُرُونَ","aya_text_emlaey":"يخادعون الله والذين آمنوا وما يخدعون إلا أنفسهم وما يشعرون","aya_tafseer":"[9] يعتقدون بجهلهم أنهم يخادعون الله والذين آمنوا بإظهارهم الإيمان وإضمارهم الكفر، وما يخدعون إلا أنفسهم؛ لأن عاقبة خداعهم تعود عليهم. ومِن فرط جهلهم لا يُحِسُّون بذلك؛ لفساد قلوبهم."},{"id":"17","jozz":"1","page":"3","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"6","line_end":"7","aya_no":"10","aya_text":"فِي قُلُوبِهِم مَّرَضٞ فَزَادَهُمُ ٱللَّهُ مَرَضٗاۖ وَلَهُمۡ عَذَابٌ أَلِيمُۢ بِمَا كَانُواْ يَكۡذِبُونَ","aya_text_emlaey":"في قلوبهم مرض فزادهم الله مرضا ولهم عذاب أليم بما كانوا يكذبون","aya_tafseer":"[10] في قلوبهم شكٌّ وفساد فابْتُلوا بالمعاصي الموجبة لعقوبتهم، فزادهم الله شكّاً، ولهم عقوبة موجعة؛ بسبب كذبهم ونفاقهم."},{"id":"18","jozz":"1","page":"3","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"7","line_end":"8","aya_no":"11","aya_text":"وَإِذَا قِيلَ لَهُمۡ لَا تُفۡسِدُواْ فِي ٱلۡأَرۡضِ قَالُوٓاْ إِنَّمَا نَحۡنُ مُصۡلِحُونَ","aya_text_emlaey":"وإذا قيل لهم لا تفسدوا في الأرض قالوا إنما نحن مصلحون","aya_tafseer":"[11] وإذا نُصحوا ليكفُّوا عن الإفساد في الأرض بالكفر والمعاصي، وإفشاء أسرار المؤمنين، وموالاة الكافرين، قالوا -كذباً وجدالاً-: إنما نحن أهل الإصلاح."},{"id":"19","jozz":"1","page":"3","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"8","line_end":"9","aya_no":"12","aya_text":"أَلَآ إِنَّهُمۡ هُمُ ٱلۡمُفۡسِدُونَ وَلَٰكِن لَّا يَشۡعُرُونَ","aya_text_emlaey":"ألا إنهم هم المفسدون ولكن لا يشعرون","aya_tafseer":"[12] إنَّ هذا الذي يفعلونه ويزعمون أنه إصلاح هو عين الفساد، لكنهم بسبب جهلهم وعنادهم لا يُحِسُّون."},{"id":"20","jozz":"1","page":"3","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"9","line_end":"11","aya_no":"13","aya_text":"وَإِذَا قِيلَ لَهُمۡ ءَامِنُواْ كَمَآ ءَامَنَ ٱلنَّاسُ قَالُوٓاْ أَنُؤۡمِنُ كَمَآ ءَامَنَ ٱلسُّفَهَآءُۗ أَلَآ إِنَّهُمۡ هُمُ ٱلسُّفَهَآءُ وَلَٰكِن لَّا يَعۡلَمُونَ","aya_text_emlaey":"وإذا قيل لهم آمنوا كما آمن الناس قالوا أنؤمن كما آمن السفهاء ألا إنهم هم السفهاء ولكن لا يعلمون","aya_tafseer":"[13] وإذا قيل للمنافقين: آمِنوا -مثل إيمان الصحابة، وهو الإيمان بالقلب واللسان والجوارح- جادَلوا وقالوا: أنُصَدِّق مثل تصديق ضعاف العقل والرأي، فنكون نحن وهم في السَّفَهِ سواء؟ فردَّ الله عليهم بأن السَّفَهَ مقصور عليهم، وهم لا يعلمون أنَّ ما هم فيه هو الضلال والخسران."},{"id":"21","jozz":"1","page":"3","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"11","line_end":"13","aya_no":"14","aya_text":"وَإِذَا لَقُواْ ٱلَّذِينَ ءَامَنُواْ قَالُوٓاْ ءَامَنَّا وَإِذَا خَلَوۡاْ إِلَىٰ شَيَٰطِينِهِمۡ قَالُوٓاْ إِنَّا مَعَكُمۡ إِنَّمَا نَحۡنُ مُسۡتَهۡزِءُونَ","aya_text_emlaey":"وإذا لقوا الذين آمنوا قالوا آمنا وإذا خلوا إلى شياطينهم قالوا إنا معكم إنما نحن مستهزئون","aya_tafseer":"[14] هؤلاء المنافقون إذا قابلوا المؤمنين قالوا: صَدَّقنا بالإسلام مثلكم، وإذا انصرفوا وذهبوا إلى زعمائهم الكفرة المتمردين على الله أكَّدوا لهم أنهم على ملة الكفر لم يتركوها، وإنما كانوا يَسْتَخِفُّون بالمؤمنين، ويسخرون منهم."},{"id":"22","jozz":"1","page":"3","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"13","line_end":"14","aya_no":"15","aya_text":"ٱللَّهُ يَسۡتَهۡزِئُ بِهِمۡ وَيَمُدُّهُمۡ فِي طُغۡيَٰنِهِمۡ يَعۡمَهُونَ","aya_text_emlaey":"الله يستهزئ بهم ويمدهم في طغيانهم يعمهون","aya_tafseer":"[15] الله يستهزئ بهم ويُمهلهم؛ ليزدادوا ضلالاً وحَيْرة وترددّاً، ويجازيهم على استهزائهم بالمؤمنين."},{"id":"23","jozz":"1","page":"3","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"14","line_end":"15","aya_no":"16","aya_text":"أُوْلَٰٓئِكَ ٱلَّذِينَ ٱشۡتَرَوُاْ ٱلضَّلَٰلَةَ بِٱلۡهُدَىٰ فَمَا رَبِحَت تِّجَٰرَتُهُمۡ وَمَا كَانُواْ مُهۡتَدِينَ","aya_text_emlaey":"أولئك الذين اشتروا الضلالة بالهدى فما ربحت تجارتهم وما كانوا مهتدين","aya_tafseer":"[16] أولئك المنافقون باعوا أنفسهم في صفقة خاسرة، فأخذوا الكفر، وتركوا الإيمان، فما كسبوا شيئاً، بل خَسِروا الهداية. وهذا هو الخسران المبين."},{"id":"24","jozz":"1","page":"4","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"1","line_end":"2","aya_no":"17","aya_text":"مَثَلُهُمۡ كَمَثَلِ ٱلَّذِي ٱسۡتَوۡقَدَ نَارٗا فَلَمَّآ أَضَآءَتۡ مَا حَوۡلَهُۥ ذَهَبَ ٱللَّهُ بِنُورِهِمۡ وَتَرَكَهُمۡ فِي ظُلُمَٰتٖ لَّا يُبۡصِرُونَ","aya_text_emlaey":"مثلهم كمثل الذي استوقد نارا فلما أضاءت ما حوله ذهب الله بنورهم وتركهم في ظلمات لا يبصرون","aya_tafseer":"[17] حال المنافقين الذين آمنوا -ظاهراً لا باطناً- برسالة محمد -صلى الله عليه وسلم-، ثم كفروا، فصاروا يتخبطون في ظلماتِ ضلالهم وهم لا يشعرون، ولا أمل لهم في الخروج منها، تُشْبه حالَ جماعة في ليلة مظلمة، وأوقد أحدهم ناراً عظيمة للدفء والإضاءة، فلما سطعت النار وأنارت ما حوله، انطفأت وأعتمت، فصار أصحابها في ظلمات لا يرون شيئاً، ولا يهتدون إلى طريق ولا مخرج."},{"id":"25","jozz":"1","page":"4","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"2","line_end":"3","aya_no":"18","aya_text":"صُمُّۢ بُكۡمٌ عُمۡيٞ فَهُمۡ لَا يَرۡجِعُونَ","aya_text_emlaey":"صم بكم عمي فهم لا يرجعون","aya_tafseer":"[18] هم صُمٌّ عن سماع الحق سماع تدبر، بُكْم عن النطق به، عُمْي عن إبصار نور الهداية؛ لذلك لا يستطيعون الرجوع إلى الإيمان الذي تركوه، واستعاضوا عنه بالضلال."},{"id":"26","jozz":"1","page":"4","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"3","line_end":"5","aya_no":"19","aya_text":"أَوۡ كَصَيِّبٖ مِّنَ ٱلسَّمَآءِ فِيهِ ظُلُمَٰتٞ وَرَعۡدٞ وَبَرۡقٞ يَجۡعَلُونَ أَصَٰبِعَهُمۡ فِيٓ ءَاذَانِهِم مِّنَ ٱلصَّوَٰعِقِ حَذَرَ ٱلۡمَوۡتِۚ وَٱللَّهُ مُحِيطُۢ بِٱلۡكَٰفِرِينَ","aya_text_emlaey":"أو كصيب من السماء فيه ظلمات ورعد وبرق يجعلون أصابعهم في آذانهم من الصواعق حذر الموت والله محيط بالكافرين","aya_tafseer":"[19] أو تُشْبه حالُ فريق آخر من المنافقين يظهر لهم الحق تارة، ويشكُّون فيه تارة أخرى، حالَ جماعة يمشون في العراء، فينصبُّ عليهم مطر شديد، تصاحبه ظلمات بعضها فوق بعض، مع قصف الرعد، ولمعان البرق، والصواعق المحرقة، التي تجعلهم من شدة الهول يضعون أصابعهم في آذانهم؛ خوفاً من الهلاك. والله تعالى محيط بالكافرين لا يفوتونه ولا يعجزونه."},{"id":"27","jozz":"1","page":"4","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"5","line_end":"8","aya_no":"20","aya_text":"يَكَادُ ٱلۡبَرۡقُ يَخۡطَفُ أَبۡصَٰرَهُمۡۖ كُلَّمَآ أَضَآءَ لَهُم مَّشَوۡاْ فِيهِ وَإِذَآ أَظۡلَمَ عَلَيۡهِمۡ قَامُواْۚ وَلَوۡ شَآءَ ٱللَّهُ لَذَهَبَ بِسَمۡعِهِمۡ وَأَبۡصَٰرِهِمۡۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ","aya_text_emlaey":"يكاد البرق يخطف أبصارهم كلما أضاء لهم مشوا فيه وإذا أظلم عليهم قاموا ولو شاء الله لذهب بسمعهم وأبصارهم إن الله على كل شيء قدير","aya_tafseer":"[20] يقارب البرق -من شدة لمعانه- أن يَسْلُب أبصارهم، ومع ذلك فكلَّما أضاء لهم مشَوْا في ضوئه، وإذا ذهب أظلم الطريق عليهم فيقفون في أماكنهم. ولولا إمهال الله لهم لَسَلَبَ سمعهم وأبصارهم، وهو قادر على ذلك في كل وقتٍ، إنه على كل شيء قدير."},{"id":"28","jozz":"1","page":"4","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"8","line_end":"9","aya_no":"21","aya_text":"يَٰٓأَيُّهَا ٱلنَّاسُ ٱعۡبُدُواْ رَبَّكُمُ ٱلَّذِي خَلَقَكُمۡ وَٱلَّذِينَ مِن قَبۡلِكُمۡ لَعَلَّكُمۡ تَتَّقُونَ","aya_text_emlaey":"ياأيها الناس اعبدوا ربكم الذي خلقكم والذين من قبلكم لعلكم تتقون","aya_tafseer":"[21] نداء من الله للبشر جميعاً: أن اعبدوا الله الذي ربَّاكم بنعمه، وخافوه ولا تخالفوا دينه؛ فقد أوجدكم من العدم، وأوجد الذين مِن قبلكم؛ لتكونوا من المتقين الذين رضي الله عنهم ورضوا عنه."},{"id":"29","jozz":"1","page":"4","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"9","line_end":"12","aya_no":"22","aya_text":"ٱلَّذِي جَعَلَ لَكُمُ ٱلۡأَرۡضَ فِرَٰشٗا وَٱلسَّمَآءَ بِنَآءٗ وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَأَخۡرَجَ بِهِۦ مِنَ ٱلثَّمَرَٰتِ رِزۡقٗا لَّكُمۡۖ فَلَا تَجۡعَلُواْ لِلَّهِ أَندَادٗا وَأَنتُمۡ تَعۡلَمُونَ","aya_text_emlaey":"الذي جعل لكم الأرض فراشا والسماء بناء وأنزل من السماء ماء فأخرج به من الثمرات رزقا لكم فلا تجعلوا لله أندادا وأنتم تعلمون","aya_tafseer":"[22] ربكم الذي جعل لكم الأرض بساطاً؛ لتسهل حياتكم عليها، والسماء محكمة البناء، وأنزل المطر من السحاب فأخرج لكم به من ألوان الثمرات وأنواع النبات رزقاً لكم، فلا تجعلوا لله نظراء في العبادة، وأنتم تعلمون تفرُّده بالخلق والرزق، واستحقاقَه العبودية."},{"id":"30","jozz":"1","page":"4","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"12","line_end":"14","aya_no":"23","aya_text":"وَإِن كُنتُمۡ فِي رَيۡبٖ مِّمَّا نَزَّلۡنَا عَلَىٰ عَبۡدِنَا فَأۡتُواْ بِسُورَةٖ مِّن مِّثۡلِهِۦ وَٱدۡعُواْ شُهَدَآءَكُم مِّن دُونِ ٱللَّهِ إِن كُنتُمۡ صَٰدِقِينَ","aya_text_emlaey":"وإن كنتم في ريب مما نزلنا على عبدنا فأتوا بسورة من مثله وادعوا شهداءكم من دون الله إن كنتم صادقين","aya_tafseer":"[23] وإن كنتم -أيها الكافرون المعاندون- في شَكٍّ من القرآن الذي نَزَّلناه على عبدنا محمد -صلى الله عليه وسلم-، وتزعمون أنه ليس من عند الله، فهاتوا سورة تماثل سورة من القرآن، واستعينوا بمن تقدرون عليه مِن أعوانكم، إن كنتم صادقين في دعواكم."},{"id":"31","jozz":"1","page":"4","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"14","line_end":"15","aya_no":"24","aya_text":"فَإِن لَّمۡ تَفۡعَلُواْ وَلَن تَفۡعَلُواْ فَٱتَّقُواْ ٱلنَّارَ ٱلَّتِي وَقُودُهَا ٱلنَّاسُ وَٱلۡحِجَارَةُۖ أُعِدَّتۡ لِلۡكَٰفِرِينَ","aya_text_emlaey":"فإن لم تفعلوا ولن تفعلوا فاتقوا النار التي وقودها الناس والحجارة أعدت للكافرين","aya_tafseer":"[24] فإن عجَزتم الآن -وستعجزون مستقبلاً لا محالة- فاتَّقوا النار بالإيمان بالنبي -صلى الله عليه وسلم- وطاعة الله تعالى. هذه النار التي حَطَبُها الناس والحجارة، أُعِدَّتْ للكافرين بالله ورسله."},{"id":"32","jozz":"1","page":"5","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"1","line_end":"4","aya_no":"25","aya_text":"وَبَشِّرِ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ أَنَّ لَهُمۡ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۖ كُلَّمَا رُزِقُواْ مِنۡهَا مِن ثَمَرَةٖ رِّزۡقٗا قَالُواْ هَٰذَا ٱلَّذِي رُزِقۡنَا مِن قَبۡلُۖ وَأُتُواْ بِهِۦ مُتَشَٰبِهٗاۖ وَلَهُمۡ فِيهَآ أَزۡوَٰجٞ مُّطَهَّرَةٞۖ وَهُمۡ فِيهَا خَٰلِدُونَ","aya_text_emlaey":"وبشر الذين آمنوا وعملوا الصالحات أن لهم جنات تجري من تحتها الأنهار كلما رزقوا منها من ثمرة رزقا قالوا هذا الذي رزقنا من قبل وأتوا به متشابها ولهم فيها أزواج مطهرة وهم فيها خالدون","aya_tafseer":"[25] وأخبر -أيها الرسول- أهل الإيمان والعمل الصالح خبراً يملؤهم سروراً، بأن لهم في الآخرة حدائق عجيبة، تجري الأنهار تحت قصورها العالية وأشجارها الظليلة. كلَّما رزقهم الله فيها نوعاً من الفاكهة اللذيذة قالوا: قد رَزَقَنا الله هذا النوع من قبل، فإذا ذاقوه وجدوه شيئاً جديداً في طعمه ولذته، وإن تشابه مع سابقه في اللون والمنظر والاسم. ولهم في الجنَّات زوجات مطهَّرات من كل ألوان الدنس الحسيِّ كالبول والحيض، والمعنوي كالكذب وسوء الخُلُق. وهم في الجنة ونعيمها دائمون، لا يموتون فيها ولا يخرجون منها."},{"id":"33","jozz":"1","page":"5","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"4","line_end":"9","aya_no":"26","aya_text":"۞ إِنَّ ٱللَّهَ لَا يَسۡتَحۡيِۦٓ أَن يَضۡرِبَ مَثَلٗا مَّا بَعُوضَةٗ فَمَا فَوۡقَهَاۚ فَأَمَّا ٱلَّذِينَ ءَامَنُواْ فَيَعۡلَمُونَ أَنَّهُ ٱلۡحَقُّ مِن رَّبِّهِمۡۖ وَأَمَّا ٱلَّذِينَ كَفَرُواْ فَيَقُولُونَ مَاذَآ أَرَادَ ٱللَّهُ بِهَٰذَا مَثَلٗاۘ يُضِلُّ بِهِۦ كَثِيرٗا وَيَهۡدِي بِهِۦ كَثِيرٗاۚ وَمَا يُضِلُّ بِهِۦٓ إِلَّا ٱلۡفَٰسِقِينَ","aya_text_emlaey":"إن الله لا يستحيي أن يضرب مثلا ما بعوضة فما فوقها فأما الذين آمنوا فيعلمون أنه الحق من ربهم وأما الذين كفروا فيقولون ماذا أراد الله بهذا مثلا يضل به كثيرا ويهدي به كثيرا وما يضل به إلا الفاسقين","aya_tafseer":"[26] إن الله تعالى لا يستحيي من الحق أن يذكر شيئاً ما، قلَّ أو كثر، ولو كان تمثيلاً بأصغر شيء، كالبعوضة والذباب ونحو ذلك، مما ضربه الله مثلاً لِعَجْز كل ما يُعْبد من دون الله. فأما المؤمنون فيعلمون حكمة الله في التمثيل بالصغير والكبير من خلقه، وأما الكفار فَيَسْخرون ويقولون: ما مراد الله مِن ضَرْب المثل بهذه الحشرات الحقيرة؟ويجيبهم الله بأن المراد هو الاختبار، وتمييز المؤمن من الكافر؛ لذلك يصرف الله بهذا المثل ناساً كثيرين عن الحق لسخريتهم منه، ويوفق به غيرهم إلى مزيد من الإيمان والهداية. والله تعالى لا يظلم أحداً؛ لأنه لا يَصْرِف عن الحق إلا الخارجين عن طاعته."},{"id":"34","jozz":"1","page":"5","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"9","line_end":"11","aya_no":"27","aya_text":"ٱلَّذِينَ يَنقُضُونَ عَهۡدَ ٱللَّهِ مِنۢ بَعۡدِ مِيثَٰقِهِۦ وَيَقۡطَعُونَ مَآ أَمَرَ ٱللَّهُ بِهِۦٓ أَن يُوصَلَ وَيُفۡسِدُونَ فِي ٱلۡأَرۡضِۚ أُوْلَٰٓئِكَ هُمُ ٱلۡخَٰسِرُونَ","aya_text_emlaey":"الذين ينقضون عهد الله من بعد ميثاقه ويقطعون ما أمر الله به أن يوصل ويفسدون في الأرض أولئك هم الخاسرون","aya_tafseer":"[27] الذين ينكثون عهد الله الذي أخذه عليهم بالتوحيد والطاعة، وقد أكَّده بإرسال الرسل، وإنزال الكتب، ويخالفون دين الله كقطع الأرحام ونشر الفساد في الأرض، أولئك هم الخاسرون في الدنيا والآخرة."},{"id":"35","jozz":"1","page":"5","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"11","line_end":"13","aya_no":"28","aya_text":"كَيۡفَ تَكۡفُرُونَ بِٱللَّهِ وَكُنتُمۡ أَمۡوَٰتٗا فَأَحۡيَٰكُمۡۖ ثُمَّ يُمِيتُكُمۡ ثُمَّ يُحۡيِيكُمۡ ثُمَّ إِلَيۡهِ تُرۡجَعُونَ","aya_text_emlaey":"كيف تكفرون بالله وكنتم أمواتا فأحياكم ثم يميتكم ثم يحييكم ثم إليه ترجعون","aya_tafseer":"[28] كيف تنكرون -أيُّها المشركون- وحدانية الله تعالى، وتشركون به غيره في العبادة مع البرهان القاطع عليها في أنفسكم؟ فلقد كنتم غير مخلوقين فأوجدكم ونفخ فيكم الحياة، ثم يميتكم بعد انقضاء آجالكم التي حددها لكم، ثم يعيدكم أحياء يوم البعث، ثم إليه ترجعون للحساب والجزاء."},{"id":"36","jozz":"1","page":"5","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"13","line_end":"15","aya_no":"29","aya_text":"هُوَ ٱلَّذِي خَلَقَ لَكُم مَّا فِي ٱلۡأَرۡضِ جَمِيعٗا ثُمَّ ٱسۡتَوَىٰٓ إِلَى ٱلسَّمَآءِ فَسَوَّىٰهُنَّ سَبۡعَ سَمَٰوَٰتٖۚ وَهُوَ بِكُلِّ شَيۡءٍ عَلِيمٞ","aya_text_emlaey":"هو الذي خلق لكم ما في الأرض جميعا ثم استوى إلى السماء فسواهن سبع سموات وهو بكل شيء عليم","aya_tafseer":"[29] اللهُ وحده الذي خَلَق لأجلكم كل ما في الأرض من النِّعم التي تنتفعون بها، ثم قصد إلى خلق السموات، فسوَّاهنَّ سبع سموات، وهو بكل شيء عليم. فعِلْمُه -سبحانه- محيط بجميع ما خلق."},{"id":"37","jozz":"1","page":"6","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"1","line_end":"3","aya_no":"30","aya_text":"وَإِذۡ قَالَ رَبُّكَ لِلۡمَلَٰٓئِكَةِ إِنِّي جَاعِلٞ فِي ٱلۡأَرۡضِ خَلِيفَةٗۖ قَالُوٓاْ أَتَجۡعَلُ فِيهَا مَن يُفۡسِدُ فِيهَا وَيَسۡفِكُ ٱلدِّمَآءَ وَنَحۡنُ نُسَبِّحُ بِحَمۡدِكَ وَنُقَدِّسُ لَكَۖ قَالَ إِنِّيٓ أَعۡلَمُ مَا لَا تَعۡلَمُونَ","aya_text_emlaey":"وإذ قال ربك للملائكة إني جاعل في الأرض خليفة قالوا أتجعل فيها من يفسد فيها ويسفك الدماء ونحن نسبح بحمدك ونقدس لك قال إني أعلم ما لا تعلمون","aya_tafseer":"[30] واذكر -أيها الرسول- للناس حين قال ربك للملائكة: إني جاعل في الأرض قوماً يخلف بعضهم بعضاً لعمارتها. قالت: يا ربَّنا علِّمْنا وأَرْشِدْنا ما الحكمة في خلق هؤلاء، مع أنَّ من شأنهم الإفساد في الأرض وإراقة الدماء ظلماً وعدواناً ونحن طوع أمرك، ننزِّهك التنزيه اللائق بحمدك وجلالك، ونمجِّدك بكل صفات الكمال والجلال؟ قال الله لهم: إني أعلم ما لا تعلمون من المصلحة الراجحة في خلقهم."},{"id":"38","jozz":"1","page":"6","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"3","line_end":"5","aya_no":"31","aya_text":"وَعَلَّمَ ءَادَمَ ٱلۡأَسۡمَآءَ كُلَّهَا ثُمَّ عَرَضَهُمۡ عَلَى ٱلۡمَلَٰٓئِكَةِ فَقَالَ أَنۢبِـُٔونِي بِأَسۡمَآءِ هَٰٓؤُلَآءِ إِن كُنتُمۡ صَٰدِقِينَ","aya_text_emlaey":"وعلم آدم الأسماء كلها ثم عرضهم على الملائكة فقال أنبئوني بأسماء هؤلاء إن كنتم صادقين","aya_tafseer":"[31] وبياناً لفضل آدم عليه السلام علَّمه الله أسماء الأشياء كلها، ثم عرض مسمَّياتها على الملائكة قائلاً لهم: أخبروني بأسماء هؤلاء الموجودات، إن كنتم صادقين في أنكم أَوْلى بالاستخلاف في الأرض منهم."},{"id":"39","jozz":"1","page":"6","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"5","line_end":"6","aya_no":"32","aya_text":"قَالُواْ سُبۡحَٰنَكَ لَا عِلۡمَ لَنَآ إِلَّا مَا عَلَّمۡتَنَآۖ إِنَّكَ أَنتَ ٱلۡعَلِيمُ ٱلۡحَكِيمُ","aya_text_emlaey":"قالوا سبحانك لا علم لنا إلا ما علمتنا إنك أنت العليم الحكيم","aya_tafseer":"[32] قالت الملائكة: ننزِّهك يا ربَّنا، ليس لنا علم إلا ما علَّمتنا إياه. إنك أنت وحدك العليم بشؤون خلقك، الحكيم في تدبيرك."},{"id":"40","jozz":"1","page":"6","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"6","line_end":"9","aya_no":"33","aya_text":"قَالَ يَٰٓـَٔادَمُ أَنۢبِئۡهُم بِأَسۡمَآئِهِمۡۖ فَلَمَّآ أَنۢبَأَهُم بِأَسۡمَآئِهِمۡ قَالَ أَلَمۡ أَقُل لَّكُمۡ إِنِّيٓ أَعۡلَمُ غَيۡبَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَأَعۡلَمُ مَا تُبۡدُونَ وَمَا كُنتُمۡ تَكۡتُمُونَ","aya_text_emlaey":"قال ياآدم أنبئهم بأسمائهم فلما أنبأهم بأسمائهم قال ألم أقل لكم إني أعلم غيب السموات والأرض وأعلم ما تبدون وما كنتم تكتمون","aya_tafseer":"[33] قال الله: يا آدم أخبرهم بأسماء هذه الأشياء التي عجَزوا عن معرفتها. فلما أخبرهم آدم بها، قال الله للملائكة: لقد أخبرتكم أني أعلم ما خفي عنكم في السموات والأرض، وأعلم ما تظهرونه وما تخفونه."},{"id":"41","jozz":"1","page":"6","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"9","line_end":"10","aya_no":"34","aya_text":"وَإِذۡ قُلۡنَا لِلۡمَلَٰٓئِكَةِ ٱسۡجُدُواْ لِأٓدَمَ فَسَجَدُوٓاْ إِلَّآ إِبۡلِيسَ أَبَىٰ وَٱسۡتَكۡبَرَ وَكَانَ مِنَ ٱلۡكَٰفِرِينَ","aya_text_emlaey":"وإذ قلنا للملائكة اسجدوا لآدم فسجدوا إلا إبليس أبى واستكبر وكان من الكافرين","aya_tafseer":"[34] واذكر -أيها الرسول- للناس تكريم الله لآدم حين قال سبحانه للملائكة: اسجدوا لآدم إكراماً له وإظهاراً لفضله، فأطاعوا جميعاً إلا إبليس امتنع عن السجود تكبراً وحسداً، فصار من الجاحدين بالله، العاصين لأمره."},{"id":"42","jozz":"1","page":"6","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"10","line_end":"12","aya_no":"35","aya_text":"وَقُلۡنَا يَٰٓـَٔادَمُ ٱسۡكُنۡ أَنتَ وَزَوۡجُكَ ٱلۡجَنَّةَ وَكُلَا مِنۡهَا رَغَدًا حَيۡثُ شِئۡتُمَا وَلَا تَقۡرَبَا هَٰذِهِ ٱلشَّجَرَةَ فَتَكُونَا مِنَ ٱلظَّٰلِمِينَ","aya_text_emlaey":"وقلنا ياآدم اسكن أنت وزوجك الجنة وكلا منها رغدا حيث شئتما ولا تقربا هذه الشجرة فتكونا من الظالمين","aya_tafseer":"[35] وقال الله: يا آدم اسكن أنت وزوجك حواء الجنة، وتمتعا بثمارها تمتعاً هنيئاً واسعاً في أي مكان تشاءان فيها، ولا تقربا هذه الشجرة حتى لا تقعا في المعصية، فتصيرا من المتجاوزين أمر الله."},{"id":"43","jozz":"1","page":"6","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"12","line_end":"14","aya_no":"36","aya_text":"فَأَزَلَّهُمَا ٱلشَّيۡطَٰنُ عَنۡهَا فَأَخۡرَجَهُمَا مِمَّا كَانَا فِيهِۖ وَقُلۡنَا ٱهۡبِطُواْ بَعۡضُكُمۡ لِبَعۡضٍ عَدُوّٞۖ وَلَكُمۡ فِي ٱلۡأَرۡضِ مُسۡتَقَرّٞ وَمَتَٰعٌ إِلَىٰ حِينٖ","aya_text_emlaey":"فأزلهما الشيطان عنها فأخرجهما مما كانا فيه وقلنا اهبطوا بعضكم لبعض عدو ولكم في الأرض مستقر ومتاع إلى حين","aya_tafseer":"[36] فأوقعهما الشيطان في الخطيئة: بأَنْ وسوس لهما حتى أكلا من الشجرة، فتسبب في إخراجهما من الجنة ونعيمها. وقال الله لهم: اهبطوا إلى الأرض، يعادي بعضكم بعضاً -أي آدم وحواء والشيطان- ولكم في الأرض استقرار وإقامة، وانتفاع بما فيها إلى وقت انتهاء آجالكم."},{"id":"44","jozz":"1","page":"6","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"14","line_end":"15","aya_no":"37","aya_text":"فَتَلَقَّىٰٓ ءَادَمُ مِن رَّبِّهِۦ كَلِمَٰتٖ فَتَابَ عَلَيۡهِۚ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ","aya_text_emlaey":"فتلقى آدم من ربه كلمات فتاب عليه إنه هو التواب الرحيم","aya_tafseer":"[37] فتلقى آدمُ بالقبول كلماتٍ، ألهمه الله إياها توبة واستغفاراً، وهي قوله تعالى: رَبَّنَا ظَلَمۡنَآ أَنفُسَنَا وَإِن لَّمۡ تَغۡفِرۡ لَنَا وَتَرۡحَمۡنَا لَنَكُونَنَّ مِنَ ٱلۡخَٰسِرِينَ، فتاب الله عليه، وغفر له ذنبه. إنه تعالى هو التواب لمن تاب مِن عباده، الرحيم بهم."},{"id":"45","jozz":"1","page":"7","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"1","line_end":"2","aya_no":"38","aya_text":"قُلۡنَا ٱهۡبِطُواْ مِنۡهَا جَمِيعٗاۖ فَإِمَّا يَأۡتِيَنَّكُم مِّنِّي هُدٗى فَمَن تَبِعَ هُدَايَ فَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ","aya_text_emlaey":"قلنا اهبطوا منها جميعا فإما يأتينكم مني هدى فمن تبع هداي فلا خوف عليهم ولا هم يحزنون","aya_tafseer":"[38] قال الله لهم: اهبطوا من الجنة جميعاً، وسيأتيكم أنتم وذرياتكم المتعاقبة ما فيه هدايتكم إلى الحق. فمن عمل بها فلا خوف عليهم فيما يستقبلونه من أمر الآخرة، ولاهم يحزنون على ما فاتهم من أمور الدنيا."},{"id":"46","jozz":"1","page":"7","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"2","line_end":"3","aya_no":"39","aya_text":"وَٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَآ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ","aya_text_emlaey":"والذين كفروا وكذبوا بآياتنا أولئك أصحاب النار هم فيها خالدون","aya_tafseer":"[39] والذين جحدوا وكذبوا بآياتنا المتلوة ودلائل توحيدنا، أولئك الذين يلازمون النار، هم فيها خالدون، لا يخرجون منها."},{"id":"47","jozz":"1","page":"7","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"4","line_end":"5","aya_no":"40","aya_text":"يَٰبَنِيٓ إِسۡرَٰٓءِيلَ ٱذۡكُرُواْ نِعۡمَتِيَ ٱلَّتِيٓ أَنۡعَمۡتُ عَلَيۡكُمۡ وَأَوۡفُواْ بِعَهۡدِيٓ أُوفِ بِعَهۡدِكُمۡ وَإِيَّٰيَ فَٱرۡهَبُونِ","aya_text_emlaey":"يابني إسرائيل اذكروا نعمتي التي أنعمت عليكم وأوفوا بعهدي أوف بعهدكم وإياي فارهبون","aya_tafseer":"[40] يا ذرية يعقوب اذكروا نعمي الكثيرة عليكم، واشكروا لي، وأتموا وصيتي لكم: بأن تؤمنوا بكتبي ورسلي جميعاً، وتعملوا بشرائعي. فإن فعلتم ذلك أُتمم لكم ما وعدتكم به من الرحمة في الدنيا، والنجاة في الآخرة. وإيَّايَ -وحدي- فخافوني، واحذروا نقمتي إن نقضتم العهد، وكفرتم بي."},{"id":"48","jozz":"1","page":"7","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"5","line_end":"7","aya_no":"41","aya_text":"وَءَامِنُواْ بِمَآ أَنزَلۡتُ مُصَدِّقٗا لِّمَا مَعَكُمۡ وَلَا تَكُونُوٓاْ أَوَّلَ كَافِرِۭ بِهِۦۖ وَلَا تَشۡتَرُواْ بِـَٔايَٰتِي ثَمَنٗا قَلِيلٗا وَإِيَّٰيَ فَٱتَّقُونِ","aya_text_emlaey":"وآمنوا بما أنـزلت مصدقا لما معكم ولا تكونوا أول كافر به ولا تشتروا بآياتي ثمنا قليلا وإياي فاتقون","aya_tafseer":"[41] وآمنوا -يا بني إسرائيل- بالقرآن الذي أنزَلْتُه على محمد نبي الله ورسوله، موافقاً لما تعلمونه من صحيح التوراة، ولا تكونوا أول فريق من أهل الكتاب يكفر به، ولا تستبدلوا بآياتي ثمناً قليلاً من حطام الدنيا الزائل، وإياي وحدي فاعملوا بطاعتي واتركوا معصيتي."},{"id":"49","jozz":"1","page":"7","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"7","line_end":"8","aya_no":"42","aya_text":"وَلَا تَلۡبِسُواْ ٱلۡحَقَّ بِٱلۡبَٰطِلِ وَتَكۡتُمُواْ ٱلۡحَقَّ وَأَنتُمۡ تَعۡلَمُونَ","aya_text_emlaey":"ولا تلبسوا الحق بالباطل وتكتموا الحق وأنتم تعلمون","aya_tafseer":"[42] ولا تخلِطوا الحق الذي بيَّنته لكم بالباطل الذي افتريتموه، واحذروا كتمان الحق الصريح من صفة نبي الله ورسوله محمد -صلى الله عليه وسلم- التي في كتبكم، وأنتم تجدونها مكتوبة عندكم، فيما تعلمون من الكتب التي بأيديكم."},{"id":"50","jozz":"1","page":"7","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"8","line_end":"9","aya_no":"43","aya_text":"وَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ وَٱرۡكَعُواْ مَعَ ٱلرَّٰكِعِينَ","aya_text_emlaey":"وأقيموا الصلاة وآتوا الزكاة واركعوا مع الراكعين","aya_tafseer":"[43] وادخلوا في دين الإسلام: بأن تقيموا الصلاة على الوجه الصحيح، كما جاء بها نبي الله ورسوله محمد -صلى الله عليه وسلم-، وتؤدوا الزكاة المفروضة على الوجه المشروع، وتكونوا مع الراكعين من أمته -صلى الله عليه وسلم-."},{"id":"51","jozz":"1","page":"7","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"9","line_end":"10","aya_no":"44","aya_text":"۞ أَتَأۡمُرُونَ ٱلنَّاسَ بِٱلۡبِرِّ وَتَنسَوۡنَ أَنفُسَكُمۡ وَأَنتُمۡ تَتۡلُونَ ٱلۡكِتَٰبَۚ أَفَلَا تَعۡقِلُونَ","aya_text_emlaey":"أتأمرون الناس بالبر وتنسون أنفسكم وأنتم تتلون الكتاب أفلا تعقلون","aya_tafseer":"[44] ما أقبح حالَكم وحالَ علمائكم حين تأمرون الناس بعمل الخيرات، وتتركون أنفسكم، فلا تأمرونها بالخير العظيم، وهو الإسلام، وأنتم تقرؤون التوراة، التي فيها صفات محمد -صلى الله عليه وسلم-، ووجوب الإيمان به! أفلا تستعملون عقولكم استعمالاً صحيحاً؟"},{"id":"52","jozz":"1","page":"7","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"11","line_end":"11","aya_no":"45","aya_text":"وَٱسۡتَعِينُواْ بِٱلصَّبۡرِ وَٱلصَّلَوٰةِۚ وَإِنَّهَا لَكَبِيرَةٌ إِلَّا عَلَى ٱلۡخَٰشِعِينَ","aya_text_emlaey":"واستعينوا بالصبر والصلاة وإنها لكبيرة إلا على الخاشعين","aya_tafseer":"[45] واستعينوا في كل أموركم بالصبر بجميع أنواعه، وكذلك الصلاة. وإنها لشاقة إلا على الخاشعين."},{"id":"53","jozz":"1","page":"7","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"12","line_end":"12","aya_no":"46","aya_text":"ٱلَّذِينَ يَظُنُّونَ أَنَّهُم مُّلَٰقُواْ رَبِّهِمۡ وَأَنَّهُمۡ إِلَيۡهِ رَٰجِعُونَ","aya_text_emlaey":"الذين يظنون أنهم ملاقو ربهم وأنهم إليه راجعون","aya_tafseer":"[46] الذين يخشون الله ويرجون ما عنده، ويوقنون أنهم ملاقو ربِّهم جلَّ وعلا بعد الموت، وأنهم إليه راجعون يوم القيامة للحساب والجزاء."},{"id":"54","jozz":"1","page":"7","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"13","line_end":"14","aya_no":"47","aya_text":"يَٰبَنِيٓ إِسۡرَٰٓءِيلَ ٱذۡكُرُواْ نِعۡمَتِيَ ٱلَّتِيٓ أَنۡعَمۡتُ عَلَيۡكُمۡ وَأَنِّي فَضَّلۡتُكُمۡ عَلَى ٱلۡعَٰلَمِينَ","aya_text_emlaey":"يابني إسرائيل اذكروا نعمتي التي أنعمت عليكم وأني فضلتكم على العالمين","aya_tafseer":"[47] يا ذرية يعقوب تذكَّروا نعمي الكثيرة عليكم، واشكروا لي عليها، وتذكروا أني فَضَّلْتكم على عالَمي زمانكم بكثرة الأنبياء، والكتب المنزَّلة كالتوراة والإنجيل."},{"id":"55","jozz":"1","page":"7","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"14","line_end":"15","aya_no":"48","aya_text":"وَٱتَّقُواْ يَوۡمٗا لَّا تَجۡزِي نَفۡسٌ عَن نَّفۡسٖ شَيۡـٔٗا وَلَا يُقۡبَلُ مِنۡهَا شَفَٰعَةٞ وَلَا يُؤۡخَذُ مِنۡهَا عَدۡلٞ وَلَا هُمۡ يُنصَرُونَ","aya_text_emlaey":"واتقوا يوما لا تجزي نفس عن نفس شيئا ولا يقبل منها شفاعة ولا يؤخذ منها عدل ولا هم ينصرون","aya_tafseer":"[48] وخافوا يوم القيامة، يوم لا يغني أحد عن أحد شيئاً، ولا يقبل الله شفاعة في الكافرين، ولا يقبل منهم فدية، ولو كانت أموال الأرض جميعاً، ولا يملك أحد في هذا اليوم أن يتقدم لنصرتهم وإنقاذهم من العذاب."},{"id":"56","jozz":"1","page":"8","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"1","line_end":"3","aya_no":"49","aya_text":"وَإِذۡ نَجَّيۡنَٰكُم مِّنۡ ءَالِ فِرۡعَوۡنَ يَسُومُونَكُمۡ سُوٓءَ ٱلۡعَذَابِ يُذَبِّحُونَ أَبۡنَآءَكُمۡ وَيَسۡتَحۡيُونَ نِسَآءَكُمۡۚ وَفِي ذَٰلِكُم بَلَآءٞ مِّن رَّبِّكُمۡ عَظِيمٞ","aya_text_emlaey":"وإذ نجيناكم من آل فرعون يسومونكم سوء العذاب يذبحون أبناءكم ويستحيون نساءكم وفي ذلكم بلاء من ربكم عظيم","aya_tafseer":"[49] واذكروا نعمتنا عليكم حين أنقذناكم من بطش فرعون وأتباعه، وهم يُذيقونكم أشدَّ العذاب، فيُكثِرون مِن ذَبْح أبنائكم، ويَسْتَبْقون نساءكم للخدمة والامتهان. وفي ذلك اختبار لكم من ربكم، وفي إنجائكم منه نعمة عظيمة، تستوجب شكر الله تعالى في كل عصوركم وأجيالكم."},{"id":"57","jozz":"1","page":"8","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"3","line_end":"4","aya_no":"50","aya_text":"وَإِذۡ فَرَقۡنَا بِكُمُ ٱلۡبَحۡرَ فَأَنجَيۡنَٰكُمۡ وَأَغۡرَقۡنَآ ءَالَ فِرۡعَوۡنَ وَأَنتُمۡ تَنظُرُونَ","aya_text_emlaey":"وإذ فرقنا بكم البحر فأنجيناكم وأغرقنا آل فرعون وأنتم تنظرون","aya_tafseer":"[50] واذكروا نعمتنا عليكم حين فَصَلْنا بسببكم البحر، وجعلنا فيه طرقاً يابسةً، فعبرتم، وأنقذناكم من فرعون وجنوده، ومن الهلاك في الماء. فلما دخل فرعون وجنوده طرقكم أهلكناهم في الماء أمام أعينكم."},{"id":"58","jozz":"1","page":"8","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"4","line_end":"5","aya_no":"51","aya_text":"وَإِذۡ وَٰعَدۡنَا مُوسَىٰٓ أَرۡبَعِينَ لَيۡلَةٗ ثُمَّ ٱتَّخَذۡتُمُ ٱلۡعِجۡلَ مِنۢ بَعۡدِهِۦ وَأَنتُمۡ ظَٰلِمُونَ","aya_text_emlaey":"وإذ واعدنا موسى أربعين ليلة ثم اتخذتم العجل من بعده وأنتم ظالمون","aya_tafseer":"[51] واذكروا نعمتنا عليكم حين واعدنا موسى أربعين ليلة لإنزال التوراة هدايةً ونوراً لكم، فإذا بكم تنتهزون فرصة غيابه هذه المدة القليلة، وتجعلون العجل الذي صنعتموه بأيديكم معبوداً لكم من دون الله -وهذا أشنع الكفر بالله- وأنتم ظالمون باتخاذكم العجل إلهاً."},{"id":"59","jozz":"1","page":"8","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"6","line_end":"6","aya_no":"52","aya_text":"ثُمَّ عَفَوۡنَا عَنكُم مِّنۢ بَعۡدِ ذَٰلِكَ لَعَلَّكُمۡ تَشۡكُرُونَ","aya_text_emlaey":"ثم عفونا عنكم من بعد ذلك لعلكم تشكرون","aya_tafseer":"[52] ثمَّ تجاوزنا عن هذه الفعلة المنكرة، وقَبِلْنا توبتكم بعد عودة موسى؛ رجاءَ أن تشكروا الله على نعمه وأفضاله، ولا تتمادوا في الكفر والطغيان."},{"id":"60","jozz":"1","page":"8","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"7","line_end":"7","aya_no":"53","aya_text":"وَإِذۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ وَٱلۡفُرۡقَانَ لَعَلَّكُمۡ تَهۡتَدُونَ","aya_text_emlaey":"وإذ آتينا موسى الكتاب والفرقان لعلكم تهتدون","aya_tafseer":"[53] واذكروا نعمتنا عليكم حين أعطينا موسى الكتاب الفارق بين الحق والباطل -وهو التوراة-؛ لكي تهتدوا من الضلالة."},{"id":"61","jozz":"1","page":"8","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"8","line_end":"11","aya_no":"54","aya_text":"وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِۦ يَٰقَوۡمِ إِنَّكُمۡ ظَلَمۡتُمۡ أَنفُسَكُم بِٱتِّخَاذِكُمُ ٱلۡعِجۡلَ فَتُوبُوٓاْ إِلَىٰ بَارِئِكُمۡ فَٱقۡتُلُوٓاْ أَنفُسَكُمۡ ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ عِندَ بَارِئِكُمۡ فَتَابَ عَلَيۡكُمۡۚ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ","aya_text_emlaey":"وإذ قال موسى لقومه ياقوم إنكم ظلمتم أنفسكم باتخاذكم العجل فتوبوا إلى بارئكم فاقتلوا أنفسكم ذلكم خير لكم عند بارئكم فتاب عليكم إنه هو التواب الرحيم","aya_tafseer":"[54] واذكروا نعمتنا عليكم حين قال موسى لقومه: إنكم ظلمتم أنفسكم باتخاذكم العجل إلهاً، فتوبوا إلى خالقكم: بأن يَقْتل بعضكم بعضاً، وهذا خير لكم عند خالقكم من الخلود الأبدي في النار، فامتثلتم ذلك، فمنَّ الله عليكم بقَبول توبتكم. إنه تعالى هو التواب لمن تاب مِن عباده، الرحيم بهم."},{"id":"62","jozz":"1","page":"8","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"11","line_end":"12","aya_no":"55","aya_text":"وَإِذۡ قُلۡتُمۡ يَٰمُوسَىٰ لَن نُّؤۡمِنَ لَكَ حَتَّىٰ نَرَى ٱللَّهَ جَهۡرَةٗ فَأَخَذَتۡكُمُ ٱلصَّٰعِقَةُ وَأَنتُمۡ تَنظُرُونَ","aya_text_emlaey":"وإذ قلتم ياموسى لن نؤمن لك حتى نرى الله جهرة فأخذتكم الصاعقة وأنتم تنظرون","aya_tafseer":"[55] واذكروا إذ قلتم: يا موسى لن نصدقك في أن الكلام الذي نسمعه منك هو كلام الله، حتى نرى الله عِياناً، فأخذتكم العقوبة المُهلكة التي رأيتموها بأعينكم، فقتَلَتْكم بسبب ذنوبكم، وجُرْأتكم على الله تعالى."},{"id":"63","jozz":"1","page":"8","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"12","line_end":"13","aya_no":"56","aya_text":"ثُمَّ بَعَثۡنَٰكُم مِّنۢ بَعۡدِ مَوۡتِكُمۡ لَعَلَّكُمۡ تَشۡكُرُونَ","aya_text_emlaey":"ثم بعثناكم من بعد موتكم لعلكم تشكرون","aya_tafseer":"[56] ثم أحييناكم مِن بعد موتكم بالصاعقة؛ لتشكروا نعمة الله عليكم. فهذا الموت عقوبة لهم، ثم بعثهم الله لاستيفاء آجالهم."},{"id":"64","jozz":"1","page":"8","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"13","line_end":"15","aya_no":"57","aya_text":"وَظَلَّلۡنَا عَلَيۡكُمُ ٱلۡغَمَامَ وَأَنزَلۡنَا عَلَيۡكُمُ ٱلۡمَنَّ وَٱلسَّلۡوَىٰۖ كُلُواْ مِن طَيِّبَٰتِ مَا رَزَقۡنَٰكُمۡۚ وَمَا ظَلَمُونَا وَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ","aya_text_emlaey":"وظللنا عليكم الغمام وأنـزلنا عليكم المن والسلوى كلوا من طيبات ما رزقناكم وما ظلمونا ولكن كانوا أنفسهم يظلمون","aya_tafseer":"[57] واذكروا نعمتنا عليكم حين كنتم تتيهون في الأرض؛ إذ جعلنا السحاب مظللاً عليكم مِن حَرِّ الشمس، وأنزلنا عليكم المنَّ، وهو شيء يشبه الصَّمْغ طعمه كالعسل، وأنزلنا عليكم السَّلوى، وهو طير يشبه السُّمانَى، وقلنا لكم: كلوا من طيِّبات ما رزقناكم، ولا تخالفوا دينكم، فلم تمتثلوا. وما ظلمونا بكفران النِّعم، ولكن كانوا أنفسَهم يظلمون؛ لأن عاقبة الظلم عائدة عليهم."},{"id":"65","jozz":"1","page":"9","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"1","line_end":"3","aya_no":"58","aya_text":"وَإِذۡ قُلۡنَا ٱدۡخُلُواْ هَٰذِهِ ٱلۡقَرۡيَةَ فَكُلُواْ مِنۡهَا حَيۡثُ شِئۡتُمۡ رَغَدٗا وَٱدۡخُلُواْ ٱلۡبَابَ سُجَّدٗا وَقُولُواْ حِطَّةٞ نَّغۡفِرۡ لَكُمۡ خَطَٰيَٰكُمۡۚ وَسَنَزِيدُ ٱلۡمُحۡسِنِينَ","aya_text_emlaey":"وإذ قلنا ادخلوا هذه القرية فكلوا منها حيث شئتم رغدا وادخلوا الباب سجدا وقولوا حطة نغفر لكم خطاياكم وسنـزيد المحسنين","aya_tafseer":"[58] واذكروا نعمتنا عليكم حين قلنا: ادخلوا مدينة «بيت المقدس» فكلوا من طيِّباتها في أي مكان منها أكلاً هنيئاً، وكونوا في دخولكم خاضعين لله، ذليلين له، وقولوا: ربَّنا ضَعْ عنَّا ذنوبنا، نستجب لكم ونَعْفُ عنكم ونستُرْها عليكم، وسنزيد المحسنين بأعمالهم خيراً وثواباً."},{"id":"66","jozz":"1","page":"9","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"3","line_end":"5","aya_no":"59","aya_text":"فَبَدَّلَ ٱلَّذِينَ ظَلَمُواْ قَوۡلًا غَيۡرَ ٱلَّذِي قِيلَ لَهُمۡ فَأَنزَلۡنَا عَلَى ٱلَّذِينَ ظَلَمُواْ رِجۡزٗا مِّنَ ٱلسَّمَآءِ بِمَا كَانُواْ يَفۡسُقُونَ","aya_text_emlaey":"فبدل الذين ظلموا قولا غير الذي قيل لهم فأنـزلنا على الذين ظلموا رجزا من السماء بما كانوا يفسقون","aya_tafseer":"[59] فبدَّل الجائرون الضالون من بني إسرائيل قول الله، وحرَّفوا القول والفعل جميعاً، إذ دخلوا يزحفون على أستاههم وقالوا: حبة في شعرة، واستهزؤوا بدين الله. فأنزل الله عليهم عذاباً من السماء؛ بسبب تمردهم وخروجهم عن طاعة الله."},{"id":"67","jozz":"1","page":"9","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"5","line_end":"8","aya_no":"60","aya_text":"۞ وَإِذِ ٱسۡتَسۡقَىٰ مُوسَىٰ لِقَوۡمِهِۦ فَقُلۡنَا ٱضۡرِب بِّعَصَاكَ ٱلۡحَجَرَۖ فَٱنفَجَرَتۡ مِنۡهُ ٱثۡنَتَا عَشۡرَةَ عَيۡنٗاۖ قَدۡ عَلِمَ كُلُّ أُنَاسٖ مَّشۡرَبَهُمۡۖ كُلُواْ وَٱشۡرَبُواْ مِن رِّزۡقِ ٱللَّهِ وَلَا تَعۡثَوۡاْ فِي ٱلۡأَرۡضِ مُفۡسِدِينَ","aya_text_emlaey":"وإذ استسقى موسى لقومه فقلنا اضرب بعصاك الحجر فانفجرت منه اثنتا عشرة عينا قد علم كل أناس مشربهم كلوا واشربوا من رزق الله ولا تعثوا في الأرض مفسدين","aya_tafseer":"[60] واذكروا نعمتنا عليكم -وأنتم عطاش في التِّيْه- حين دعانا موسى -بضراعة- أن نسقي قومه، فقلنا: اضرب بعصاك الحجر، فضرب، فانفجرت منه اثنتا عشرة عيناً، بعدد القبائل، مع إعلام كل قبيلة بالعين الخاصة بها حتى لا يتنازعوا. وقلنا لهم: كلوا واشربوا من رزق الله، ولا تسعوا في الأرض مفسدين."},{"id":"68","jozz":"1","page":"9","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"9","line_end":"15","aya_no":"61","aya_text":"وَإِذۡ قُلۡتُمۡ يَٰمُوسَىٰ لَن نَّصۡبِرَ عَلَىٰ طَعَامٖ وَٰحِدٖ فَٱدۡعُ لَنَا رَبَّكَ يُخۡرِجۡ لَنَا مِمَّا تُنۢبِتُ ٱلۡأَرۡضُ مِنۢ بَقۡلِهَا وَقِثَّآئِهَا وَفُومِهَا وَعَدَسِهَا وَبَصَلِهَاۖ قَالَ أَتَسۡتَبۡدِلُونَ ٱلَّذِي هُوَ أَدۡنَىٰ بِٱلَّذِي هُوَ خَيۡرٌۚ ٱهۡبِطُواْ مِصۡرٗا فَإِنَّ لَكُم مَّا سَأَلۡتُمۡۗ وَضُرِبَتۡ عَلَيۡهِمُ ٱلذِّلَّةُ وَٱلۡمَسۡكَنَةُ وَبَآءُو بِغَضَبٖ مِّنَ ٱللَّهِۚ ذَٰلِكَ بِأَنَّهُمۡ كَانُواْ يَكۡفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَيَقۡتُلُونَ ٱلنَّبِيِّـۧنَ بِغَيۡرِ ٱلۡحَقِّۚ ذَٰلِكَ بِمَا عَصَواْ وَّكَانُواْ يَعۡتَدُونَ","aya_text_emlaey":"وإذ قلتم ياموسى لن نصبر على طعام واحد فادع لنا ربك يخرج لنا مما تنبت الأرض من بقلها وقثائها وفومها وعدسها وبصلها قال أتستبدلون الذي هو أدنى بالذي هو خير اهبطوا مصرا فإن لكم ما سألتم وضربت عليهم الذلة والمسكنة وباءوا بغضب من الله ذلك بأنهم كانوا يكفرون بآيات الله ويقتلون النبيين بغير الحق ذلك بما عصوا وكانوا يعتدون","aya_tafseer":"[61] واذكروا حين أنزلنا عليكم الطعام الحلو، والطير الشهي، فبطِرتم النعمة كعادتكم، وأصابكم الضيق والملل، فقلتم: يا موسى لن نصبر على طعام ثابت لا يتغير مع الأيام، فادع لنا ربك يخرج لنا من نبات الأرض طعاماً من البقول والخُضَر، والقثاء، والحبوب التي تؤكل، والعدس، والبصل. قال موسى -مستنكراً عليهم-: أتطلبون هذه الأطعمة التي هي أقل قَدْراً، وتتركون هذا الرزق النافع الذي اختاره الله لكم؟ اهبطوا من هذه البادية إلى أي مدينة، تجدوا ما اشتهيتم كثيراً في الحقول والأسواق. ولما هبطوا تبيَّن لهم أنهم يُقَدِّمون اختيارهم -في كل موطن- على اختيار الله، ويُؤْثرون شهواتهم على ما اختاره الله لهم؛ لذلك لزمتهم صِفَةُ الذُّل وفقر النفوس، وانصرفوا ورجعوا بغضب من الله؛ لإعراضهم عن دين الله، ولأنهم كانوا يكفرون بآيات الله ويقتلون النبيين ظلماً وعدواناً؛ وذلك بسبب عصيانهم وتجاوزهم حدود ربهم."},{"id":"69","jozz":"1","page":"10","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"1","line_end":"3","aya_no":"62","aya_text":"إِنَّ ٱلَّذِينَ ءَامَنُواْ وَٱلَّذِينَ هَادُواْ وَٱلنَّصَٰرَىٰ وَٱلصَّٰبِـِٔينَ مَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَعَمِلَ صَٰلِحٗا فَلَهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ","aya_text_emlaey":"إن الذين آمنوا والذين هادوا والنصارى والصابئين من آمن بالله واليوم الآخر وعمل صالحا فلهم أجرهم عند ربهم ولا خوف عليهم ولا هم يحزنون","aya_tafseer":"[62] إن المؤمنين من هذه الأمة، الذين صدَّقوا بالله ورسله، وعملوا بشرعه، والذين كانوا قبل بعثة محمد -صلى الله عليه وسلم- من الأمم السالفة من اليهود، والنصارى، والصابئين -وهم قوم باقون على فطرتهم، ولا دين مقرر لهم يتبعونه- هؤلاء جميعاً إذا صدَّقوا بالله تصديقاً صحيحاً خالصاً، وبيوم البعث والجزاء، وعملوا عملاً مرضيّاً عند الله، فثوابهم ثابت لهم عند ربهم، ولا خوف عليهم فيما يستقبلونه من أمر الآخرة، ولا هم يحزنون على ما فاتهم من أمور الدنيا. وأما بعد بعثة محمد -صلى الله عليه وسلم- خاتماً للنبيين والمرسلين إلى الناس كافة، فلا يقبل الله من أحد ديناً غير ما جاء به، وهو الإسلام."},{"id":"70","jozz":"1","page":"10","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"3","line_end":"5","aya_no":"63","aya_text":"وَإِذۡ أَخَذۡنَا مِيثَٰقَكُمۡ وَرَفَعۡنَا فَوۡقَكُمُ ٱلطُّورَ خُذُواْ مَآ ءَاتَيۡنَٰكُم بِقُوَّةٖ وَٱذۡكُرُواْ مَا فِيهِ لَعَلَّكُمۡ تَتَّقُونَ","aya_text_emlaey":"وإذ أخذنا ميثاقكم ورفعنا فوقكم الطور خذوا ما آتيناكم بقوة واذكروا ما فيه لعلكم تتقون","aya_tafseer":"[63] واذكروا -يا بني إسرائيل- حين أَخَذْنا العهد المؤكَّد منكم بالإيمان بالله وإفراده بالعبادة، ورفعنا جبل الطور فوقكم، وقلنا لكم: خذوا الكتاب الذي أعطيناكم بجدٍّ واجتهاد واحفظوه، وإلَّا أطبقنا عليكم الجبل، ولا تنسوا التوراة قولاً وعملاً؛ كي تتقوني وتخافوا عقابي."},{"id":"71","jozz":"1","page":"10","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"5","line_end":"7","aya_no":"64","aya_text":"ثُمَّ تَوَلَّيۡتُم مِّنۢ بَعۡدِ ذَٰلِكَۖ فَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ لَكُنتُم مِّنَ ٱلۡخَٰسِرِينَ","aya_text_emlaey":"ثم توليتم من بعد ذلك فلولا فضل الله عليكم ورحمته لكنتم من الخاسرين","aya_tafseer":"[64] ثم خالفتم وعصيتم مرة أخرى، بعد أَخْذِ الميثاق ورَفْع الجبل كشأنكم دائماً. فلولا فَضْلُ الله عليكم ورحمته بالتوبة، والتجاوز عن خطاياكم، لصرتم من الخاسرين في الدنيا والآخرة."},{"id":"72","jozz":"1","page":"10","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"7","line_end":"8","aya_no":"65","aya_text":"وَلَقَدۡ عَلِمۡتُمُ ٱلَّذِينَ ٱعۡتَدَوۡاْ مِنكُمۡ فِي ٱلسَّبۡتِ فَقُلۡنَا لَهُمۡ كُونُواْ قِرَدَةً خَٰسِـِٔينَ","aya_text_emlaey":"ولقد علمتم الذين اعتدوا منكم في السبت فقلنا لهم كونوا قردة خاسئين","aya_tafseer":"[65] ولقد علمتم -يا معشر اليهود- ما حلَّ من البأس بأسلافكم من أهل القرية التي عصت أمر الله، فيما أخذه عليهم من تعظيم السبت، فاحتالوا لاصطياد السمك في يوم السبت بوضع الشِّباك وحفر البرَك، ثم اصطادوا السمك يوم الأحد؛ حيلة إلى المحرم، فلما فعلوا ذلك، مسخهم الله قردة منبوذين."},{"id":"73","jozz":"1","page":"10","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"8","line_end":"9","aya_no":"66","aya_text":"فَجَعَلۡنَٰهَا نَكَٰلٗا لِّمَا بَيۡنَ يَدَيۡهَا وَمَا خَلۡفَهَا وَمَوۡعِظَةٗ لِّلۡمُتَّقِينَ","aya_text_emlaey":"فجعلناها نكالا لما بين يديها وما خلفها وموعظة للمتقين","aya_tafseer":"[66] فجعلنا هذه القرية عبرة لمن بحضرتها من القرى، يبلغهم خبرها وما حلَّ بها، وعبرة لمن يعمل بعدها مثل تلك الذُّنوب، وجعلناها تذكرة للصالحين؛ ليعلموا أنهم على الحق، فيثبتوا عليه."},{"id":"74","jozz":"1","page":"10","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"9","line_end":"11","aya_no":"67","aya_text":"وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِۦٓ إِنَّ ٱللَّهَ يَأۡمُرُكُمۡ أَن تَذۡبَحُواْ بَقَرَةٗۖ قَالُوٓاْ أَتَتَّخِذُنَا هُزُوٗاۖ قَالَ أَعُوذُ بِٱللَّهِ أَنۡ أَكُونَ مِنَ ٱلۡجَٰهِلِينَ","aya_text_emlaey":"وإذ قال موسى لقومه إن الله يأمركم أن تذبحوا بقرة قالوا أتتخذنا هزوا قال أعوذ بالله أن أكون من الجاهلين","aya_tafseer":"[67] واذكروا –يا بني إسرائيل- جناية أسلافكم، وكثرة تعنتهم وجدالهم لموسى عليه الصلاة والسلام، حين قال لهم: إن الله يأمركم أن تذبحوا بقرة، فقالوا -مستكبرين-: أتجعلنا موضعاً للسخرية والاستخفاف؟ فردَّ عليهم موسى بقوله: أستجير بالله أن أكون من المستهزئين."},{"id":"75","jozz":"1","page":"10","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"12","line_end":"14","aya_no":"68","aya_text":"قَالُواْ ٱدۡعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِيَۚ قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٞ لَّا فَارِضٞ وَلَا بِكۡرٌ عَوَانُۢ بَيۡنَ ذَٰلِكَۖ فَٱفۡعَلُواْ مَا تُؤۡمَرُونَ","aya_text_emlaey":"قالوا ادع لنا ربك يبين لنا ما هي قال إنه يقول إنها بقرة لا فارض ولا بكر عوان بين ذلك فافعلوا ما تؤمرون","aya_tafseer":"[68] قالوا: ادع لنا ربَّك يوضح لنا صفة هذه البقرة، فأجابهم: إن الله يقول لكم: صفتها ألا تكون مسنَّة هَرِمة، ولا صغيرة فَتِيَّة، وإنما هي متوسطة بينهما، فسارِعوا إلى امتثال أمر ربكم."},{"id":"76","jozz":"1","page":"10","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"14","line_end":"15","aya_no":"69","aya_text":"قَالُواْ ٱدۡعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا لَوۡنُهَاۚ قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٞ صَفۡرَآءُ فَاقِعٞ لَّوۡنُهَا تَسُرُّ ٱلنَّٰظِرِينَ","aya_text_emlaey":"قالوا ادع لنا ربك يبين لنا ما لونها قال إنه يقول إنها بقرة صفراء فاقع لونها تسر الناظرين","aya_tafseer":"[69] فعادوا إلى جدالهم قائلين: ادع لنا ربك يوضح لنا لونها. قال: إنه يقول: إنها بقرة صفراء شديدة الصُّفْرة، تَسُرُّ مَن ينظر إليها."},{"id":"77","jozz":"1","page":"11","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"1","line_end":"2","aya_no":"70","aya_text":"قَالُواْ ٱدۡعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِيَ إِنَّ ٱلۡبَقَرَ تَشَٰبَهَ عَلَيۡنَا وَإِنَّآ إِن شَآءَ ٱللَّهُ لَمُهۡتَدُونَ","aya_text_emlaey":"قالوا ادع لنا ربك يبين لنا ما هي إن البقر تشابه علينا وإنا إن شاء الله لمهتدون","aya_tafseer":"[70] قال بنو إسرائيل لموسى: ادع لنا ربك يوضح لنا صفات أخرى غير ما سبق؛ لأن البقر -بهذه الصفات- كثير فاشْتَبَهَ علينا ماذا نختار؟ وإننا -إن شاء الله- لمهتدون إلى البقرة المأمور بذبحها."},{"id":"78","jozz":"1","page":"11","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"2","line_end":"4","aya_no":"71","aya_text":"قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٞ لَّا ذَلُولٞ تُثِيرُ ٱلۡأَرۡضَ وَلَا تَسۡقِي ٱلۡحَرۡثَ مُسَلَّمَةٞ لَّا شِيَةَ فِيهَاۚ قَالُواْ ٱلۡـَٰٔنَ جِئۡتَ بِٱلۡحَقِّۚ فَذَبَحُوهَا وَمَا كَادُواْ يَفۡعَلُونَ","aya_text_emlaey":"قال إنه يقول إنها بقرة لا ذلول تثير الأرض ولا تسقي الحرث مسلمة لا شية فيها قالوا الآن جئت بالحق فذبحوها وما كادوا يفعلون","aya_tafseer":"[71] قال لهم موسى: إن الله يقول: إنها بقرة غير مذللة للعمل في حراثة الأرض للزراعة، وغير معدة للسقي من الساقية، وخالية من العيوب جميعها، وليس فيها علامة من لون غير لون جلدها. قالوا: الآن جئت بحقيقة وصف البقرة، فاضطروا إلى ذبحها بعد طول المراوغة، وقد قاربوا ألا يفعلوا ذلك لعنادهم. وهكذا شددوا فشدَّد الله عليهم."},{"id":"79","jozz":"1","page":"11","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"4","line_end":"5","aya_no":"72","aya_text":"وَإِذۡ قَتَلۡتُمۡ نَفۡسٗا فَٱدَّٰرَٰءۡتُمۡ فِيهَاۖ وَٱللَّهُ مُخۡرِجٞ مَّا كُنتُمۡ تَكۡتُمُونَ","aya_text_emlaey":"وإذ قتلتم نفسا فادارأتم فيها والله مخرج ما كنتم تكتمون","aya_tafseer":"[72] واذكروا إذ قتلتم نفساً فتنازعتم بشأنها، كلٌّ يدفع عن نفسه تهمة القتل، والله مخرج ما كنتم تخفون مِن قَتْل القتيل."},{"id":"80","jozz":"1","page":"11","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"6","line_end":"7","aya_no":"73","aya_text":"فَقُلۡنَا ٱضۡرِبُوهُ بِبَعۡضِهَاۚ كَذَٰلِكَ يُحۡيِ ٱللَّهُ ٱلۡمَوۡتَىٰ وَيُرِيكُمۡ ءَايَٰتِهِۦ لَعَلَّكُمۡ تَعۡقِلُونَ","aya_text_emlaey":"فقلنا اضربوه ببعضها كذلك يحي الله الموتى ويريكم آياته لعلكم تعقلون","aya_tafseer":"[73] فقلنا: اضربوا القتيل بجزء من هذه البقرة المذبوحة، فإن الله سيبعثه حيّاً، ويخبركم عن قاتله. فضربوه ببعضها فأحياه الله وأخبر بقاتله. كذلك يُحيي الله الموتى يوم القيامة، ويريكم –يا بني إسرائيل- معجزاتِه الدالَّةَ على كمال قدرته تعالى؛ لكي تتفكروا بعقولكم، فتمتنعوا عن معاصيه."},{"id":"81","jozz":"1","page":"11","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"7","line_end":"10","aya_no":"74","aya_text":"ثُمَّ قَسَتۡ قُلُوبُكُم مِّنۢ بَعۡدِ ذَٰلِكَ فَهِيَ كَٱلۡحِجَارَةِ أَوۡ أَشَدُّ قَسۡوَةٗۚ وَإِنَّ مِنَ ٱلۡحِجَارَةِ لَمَا يَتَفَجَّرُ مِنۡهُ ٱلۡأَنۡهَٰرُۚ وَإِنَّ مِنۡهَا لَمَا يَشَّقَّقُ فَيَخۡرُجُ مِنۡهُ ٱلۡمَآءُۚ وَإِنَّ مِنۡهَا لَمَا يَهۡبِطُ مِنۡ خَشۡيَةِ ٱللَّهِۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعۡمَلُونَ","aya_text_emlaey":"ثم قست قلوبكم من بعد ذلك فهي كالحجارة أو أشد قسوة وإن من الحجارة لما يتفجر منه الأنهار وإن منها لما يشقق فيخرج منه الماء وإن منها لما يهبط من خشية الله وما الله بغافل عما تعملون ","aya_tafseer":"[74] ولكنكم لم تنتفعوا بذلك؛ إذ بعد كل هذه المعجزات الخارقة اشتدت قلوبكم وغَلُظت، فلم يَنْفُذ إليها خير، ولم تَلِنْ أمام الآيات الباهرة التي أريتكموها، حتى صارت قلوبكم مثل الحجارة الصمَّاء، بل هي أشد منها غلظة؛ لأن من الحجارة ما يتسع وينفرج حتى تنصبَّ منه المياه صبّاً، فتصير أنهاراً جاريةً، ومن الحجارة ما يتصدع فينشق، فتخرج منه العيون والينابيع، ومن الحجارة ما يسقط من أعالي الجبال مِن خشية الله تعالى وتعظيمه. وما الله بغافل عما تعملون."},{"id":"82","jozz":"1","page":"11","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"11","line_end":"13","aya_no":"75","aya_text":"۞ أَفَتَطۡمَعُونَ أَن يُؤۡمِنُواْ لَكُمۡ وَقَدۡ كَانَ فَرِيقٞ مِّنۡهُمۡ يَسۡمَعُونَ كَلَٰمَ ٱللَّهِ ثُمَّ يُحَرِّفُونَهُۥ مِنۢ بَعۡدِ مَا عَقَلُوهُ وَهُمۡ يَعۡلَمُونَ","aya_text_emlaey":"أفتطمعون أن يؤمنوا لكم وقد كان فريق منهم يسمعون كلام الله ثم يحرفونه من بعد ما عقلوه وهم يعلمون","aya_tafseer":"[75] أيها المسلمون أنسيتم أفعال بني إسرائيل، فطمعت نفوسكم أن يصدِّق اليهودُ بدينكم؟ وقد كان علماؤهم يسمعون كلام الله من التوراة، ثم يحرفونه بِصَرْفِه إلى غير معناه الصحيح بعد ما عقلوا حقيقته، أو بتحريف ألفاظه، وهم يعلمون أنهم يحرِّفون كلام رب العالمين عمداً وكذباً."},{"id":"83","jozz":"1","page":"11","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"13","line_end":"15","aya_no":"76","aya_text":"وَإِذَا لَقُواْ ٱلَّذِينَ ءَامَنُواْ قَالُوٓاْ ءَامَنَّا وَإِذَا خَلَا بَعۡضُهُمۡ إِلَىٰ بَعۡضٖ قَالُوٓاْ أَتُحَدِّثُونَهُم بِمَا فَتَحَ ٱللَّهُ عَلَيۡكُمۡ لِيُحَآجُّوكُم بِهِۦ عِندَ رَبِّكُمۡۚ أَفَلَا تَعۡقِلُونَ","aya_text_emlaey":"وإذا لقوا الذين آمنوا قالوا آمنا وإذا خلا بعضهم إلى بعض قالوا أتحدثونهم بما فتح الله عليكم ليحاجوكم به عند ربكم أفلا تعقلون","aya_tafseer":"[76] هؤلاء اليهود إذا لقوا الذين آمنوا قالوا بلسانهم: آمنَّا بدينكم ورسولكم المبشَّر به في التوراة، وإذا خلا بعض هؤلاء المنافقين من اليهود إلى بعض قالوا في إنكار: أتحدِّثون المؤمنين بما بيَّن الله لكم في التوراة من أمر محمد؛ لتكون لهم الحجة عليكم عند ربكم يوم القيامة؟ أفلا تفقهون فتحذروا؟"},{"id":"84","jozz":"1","page":"12","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"1","line_end":"1","aya_no":"77","aya_text":"أَوَلَا يَعۡلَمُونَ أَنَّ ٱللَّهَ يَعۡلَمُ مَا يُسِرُّونَ وَمَا يُعۡلِنُونَ","aya_text_emlaey":"أو لا يعلمون أن الله يعلم ما يسرون وما يعلنون","aya_tafseer":"[77] أيفعلون كلَّ هذه الجرائم، ولا يعلمون أن الله يعلم جميع ما يخفونه وما يظهرونه؟"},{"id":"85","jozz":"1","page":"12","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"2","line_end":"3","aya_no":"78","aya_text":"وَمِنۡهُمۡ أُمِّيُّونَ لَا يَعۡلَمُونَ ٱلۡكِتَٰبَ إِلَّآ أَمَانِيَّ وَإِنۡ هُمۡ إِلَّا يَظُنُّونَ","aya_text_emlaey":"ومنهم أميون لا يعلمون الكتاب إلا أماني وإن هم إلا يظنون","aya_tafseer":"[78] ومن اليهود جماعة يجهلون القراءة والكتابة، ولا يعلمون التوراة وما فيها من صفات نبي الله ورسوله محمد -صلى الله عليه وسلم-، وما عندهم من ذلك إلا أكاذيبُ وظنون فاسدة."},{"id":"86","jozz":"1","page":"12","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"3","line_end":"5","aya_no":"79","aya_text":"فَوَيۡلٞ لِّلَّذِينَ يَكۡتُبُونَ ٱلۡكِتَٰبَ بِأَيۡدِيهِمۡ ثُمَّ يَقُولُونَ هَٰذَا مِنۡ عِندِ ٱللَّهِ لِيَشۡتَرُواْ بِهِۦ ثَمَنٗا قَلِيلٗاۖ فَوَيۡلٞ لَّهُم مِّمَّا كَتَبَتۡ أَيۡدِيهِمۡ وَوَيۡلٞ لَّهُم مِّمَّا يَكۡسِبُونَ","aya_text_emlaey":"فويل للذين يكتبون الكتاب بأيديهم ثم يقولون هذا من عند الله ليشتروا به ثمنا قليلا فويل لهم مما كتبت أيديهم وويل لهم مما يكسبون","aya_tafseer":"[79] فهلاك ووعيد شديد لأحبار السوء من اليهود الذين يكتبون الكتاب بأيديهم، ثم يقولون: هذا من عند الله، وهو مخالف لما أنزل الله على نبيِّه موسى عليه الصلاة والسلام؛ ليأخذوا في مقابل هذا عرض الدنيا. فلهم عقوبة مهلكة بسبب كتابتهم هذا الباطل بأيديهم، ولهم عقوبة مهلكة بسبب ما يأخذونه في المقابل من المال الحرام، كالرِّشوة وغيرها."},{"id":"87","jozz":"1","page":"12","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"6","line_end":"8","aya_no":"80","aya_text":"وَقَالُواْ لَن تَمَسَّنَا ٱلنَّارُ إِلَّآ أَيَّامٗا مَّعۡدُودَةٗۚ قُلۡ أَتَّخَذۡتُمۡ عِندَ ٱللَّهِ عَهۡدٗا فَلَن يُخۡلِفَ ٱللَّهُ عَهۡدَهُۥٓۖ أَمۡ تَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعۡلَمُونَ","aya_text_emlaey":"وقالوا لن تمسنا النار إلا أياما معدودة قل أتخذتم عند الله عهدا فلن يخلف الله عهده أم تقولون على الله ما لا تعلمون","aya_tafseer":"[80] وقال بنو إسرائيل: لن تصيبنا النار في الآخرة إلَّا أياماً قليلة العدد. قل لهم -أيها الرسول مبطلاً دعواهم-: أعندكم عهد من الله بهذا، فإن الله لا يخلف عهده؟ بل إنكم تقولون على الله ما لا تعلمون بافترائكم الكذب."},{"id":"88","jozz":"1","page":"12","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"8","line_end":"10","aya_no":"81","aya_text":"بَلَىٰۚ مَن كَسَبَ سَيِّئَةٗ وَأَحَٰطَتۡ بِهِۦ خَطِيٓـَٔتُهُۥ فَأُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ","aya_text_emlaey":"بلى من كسب سيئة وأحاطت به خطيئته فأولئك أصحاب النار هم فيها خالدون","aya_tafseer":"[81] فحُكْمُ الله ثابت: أن من ارتكب الآثام حتى جَرَّته إلى الكفر، واستولت عليه ذنوبه مِن جميع جوانبه -وهذا لا يكون إلَّا فيمن أشرك بالله- فأولئك هم المشركون والكفار الذين يلازمون نار جهنم ملازمة دائمةً لا تنقطع."},{"id":"89","jozz":"1","page":"12","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"10","line_end":"11","aya_no":"82","aya_text":"وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلۡجَنَّةِۖ هُمۡ فِيهَا خَٰلِدُونَ","aya_text_emlaey":"والذين آمنوا وعملوا الصالحات أولئك أصحاب الجنة هم فيها خالدون","aya_tafseer":"[82] وحكم الله الثابتُ في مقابل هذا: أنَّ الذين صدَّقوا بالله ورسله تصديقاً خالصاً، وعملوا الأعمال المتفقة مع شريعة الله التي أوحاها إلى رسله، هؤلاء يلازمون الجنة في الآخرة ملازمةً دائمةً لا تنقطع."},{"id":"90","jozz":"1","page":"12","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"11","line_end":"15","aya_no":"83","aya_text":"وَإِذۡ أَخَذۡنَا مِيثَٰقَ بَنِيٓ إِسۡرَٰٓءِيلَ لَا تَعۡبُدُونَ إِلَّا ٱللَّهَ وَبِٱلۡوَٰلِدَيۡنِ إِحۡسَانٗا وَذِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينِ وَقُولُواْ لِلنَّاسِ حُسۡنٗا وَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ ثُمَّ تَوَلَّيۡتُمۡ إِلَّا قَلِيلٗا مِّنكُمۡ وَأَنتُم مُّعۡرِضُونَ","aya_text_emlaey":"وإذ أخذنا ميثاق بني إسرائيل لا تعبدون إلا الله وبالوالدين إحسانا وذي القربى واليتامى والمساكين وقولوا للناس حسنا وأقيموا الصلاة وآتوا الزكاة ثم توليتم إلا قليلا منكم وأنتم معرضون","aya_tafseer":"[83] واذكروا يا بني إسرائيل حين أخَذْنا عليكم عهداً مؤكداً: بأن تعبدوا الله وحده لا شريك له، وأن تحسنوا للوالدين، وللأقربين، وللأولاد الذين مات آباؤهم وهم دون بلوغ الحُلُم، وللمحتاجين الذين لا يملكون ما يكفيهم ويسدُّ حاجتهم، وأن تقولوا للناس أطيب الكلام، مع أداء الصلاة وإيتاء الزَّكاة، ثم أَعْرَضْتم ونقضتم العهد -إلا قليلاً منكم ثبت عليه- وأنتم مستمرون في إعراضكم."},{"id":"91","jozz":"1","page":"13","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"1","line_end":"2","aya_no":"84","aya_text":"وَإِذۡ أَخَذۡنَا مِيثَٰقَكُمۡ لَا تَسۡفِكُونَ دِمَآءَكُمۡ وَلَا تُخۡرِجُونَ أَنفُسَكُم مِّن دِيَٰرِكُمۡ ثُمَّ أَقۡرَرۡتُمۡ وَأَنتُمۡ تَشۡهَدُونَ","aya_text_emlaey":"وإذ أخذنا ميثاقكم لا تسفكون دماءكم ولا تخرجون أنفسكم من دياركم ثم أقررتم وأنتم تشهدون","aya_tafseer":"[84] واذكروا -يا بني إسرائيل- حين أَخَذْنا عليكم عهداً مؤكداً في التوراة: يحرِّم سفكَ بعضكم دم بعض، وإخراجَ بعضكم بعضاً من دياركم، ثم اعترفتم بذلك، وأنتم تشهدون على صحته."},{"id":"92","jozz":"1","page":"13","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"3","line_end":"9","aya_no":"85","aya_text":"ثُمَّ أَنتُمۡ هَٰٓؤُلَآءِ تَقۡتُلُونَ أَنفُسَكُمۡ وَتُخۡرِجُونَ فَرِيقٗا مِّنكُم مِّن دِيَٰرِهِمۡ تَظَٰهَرُونَ عَلَيۡهِم بِٱلۡإِثۡمِ وَٱلۡعُدۡوَٰنِ وَإِن يَأۡتُوكُمۡ أُسَٰرَىٰ تُفَٰدُوهُمۡ وَهُوَ مُحَرَّمٌ عَلَيۡكُمۡ إِخۡرَاجُهُمۡۚ أَفَتُؤۡمِنُونَ بِبَعۡضِ ٱلۡكِتَٰبِ وَتَكۡفُرُونَ بِبَعۡضٖۚ فَمَا جَزَآءُ مَن يَفۡعَلُ ذَٰلِكَ مِنكُمۡ إِلَّا خِزۡيٞ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ وَيَوۡمَ ٱلۡقِيَٰمَةِ يُرَدُّونَ إِلَىٰٓ أَشَدِّ ٱلۡعَذَابِۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعۡمَلُونَ","aya_text_emlaey":"ثم أنتم هؤلاء تقتلون أنفسكم وتخرجون فريقا منكم من ديارهم تظاهرون عليهم بالإثم والعدوان وإن يأتوكم أسارى تفادوهم وهو محرم عليكم إخراجهم أفتؤمنون ببعض الكتاب وتكفرون ببعض فما جزاء من يفعل ذلك منكم إلا خزي في الحياة الدنيا ويوم القيامة يردون إلى أشد العذاب وما الله بغافل عما تعملون","aya_tafseer":"[85] ثم أنتم يا هؤلاء يقتل بعضكم بعضاً، ويُخرج بعضكم بعضاً من ديارهم، ويَتَقَوَّى كل فريق منكم على إخوانه بالأعداء بغياً وعدواناً. وإن يأتوكم أسارى في يد الأعداء سعيتم في تحريرهم من الأسر، بدفع الفدية، مع أنه محرم عليكم إخراجهم من ديارهم. ما أقبح ما تفعلون حين تؤمنون ببعض أحكام التوراة وتكفرون ببعضها! فليس جزاء مَن يفعل ذلك منكم إلا ذُلاًّ وفضيحة في الدنيا. ويوم القيامة يردُّهم الله إلى أفظع العذاب في النار. وما الله بغافل عما تعملون."},{"id":"93","jozz":"1","page":"13","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"9","line_end":"10","aya_no":"86","aya_text":"أُوْلَٰٓئِكَ ٱلَّذِينَ ٱشۡتَرَوُاْ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا بِٱلۡأٓخِرَةِۖ فَلَا يُخَفَّفُ عَنۡهُمُ ٱلۡعَذَابُ وَلَا هُمۡ يُنصَرُونَ","aya_text_emlaey":"أولئك الذين اشتروا الحياة الدنيا بالآخرة فلا يخفف عنهم العذاب ولا هم ينصرون","aya_tafseer":"[86] أولئك هم الذين آثروا الحياة الدنيا على الآخرة، فلا يخفف عنهم العذاب، وليس لهم ناصر ينصرهم مِن عذاب الله."},{"id":"94","jozz":"1","page":"13","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"11","line_end":"14","aya_no":"87","aya_text":"وَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ وَقَفَّيۡنَا مِنۢ بَعۡدِهِۦ بِٱلرُّسُلِۖ وَءَاتَيۡنَا عِيسَى ٱبۡنَ مَرۡيَمَ ٱلۡبَيِّنَٰتِ وَأَيَّدۡنَٰهُ بِرُوحِ ٱلۡقُدُسِۗ أَفَكُلَّمَا جَآءَكُمۡ رَسُولُۢ بِمَا لَا تَهۡوَىٰٓ أَنفُسُكُمُ ٱسۡتَكۡبَرۡتُمۡ فَفَرِيقٗا كَذَّبۡتُمۡ وَفَرِيقٗا تَقۡتُلُونَ","aya_text_emlaey":"ولقد آتينا موسى الكتاب وقفينا من بعده بالرسل وآتينا عيسى ابن مريم البينات وأيدناه بروح القدس أفكلما جاءكم رسول بما لا تهوى أنفسكم استكبرتم ففريقا كذبتم وفريقا تقتلون","aya_tafseer":"[87] ولقد أعطينا موسى التوراة، وأتبعناه برسل من بني إسرائيل، وأعطينا عيسى بن مريم المعجزات الواضحات، وقوَّيناه بجبريل عليه السلام. أفكلما جاءكم رسول بوحي من عند الله لا يوافق أهواءكم، استعليتم عليه، فكذَّبتم فريقاً وتقتلون فريقاً؟"},{"id":"95","jozz":"1","page":"13","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"14","line_end":"15","aya_no":"88","aya_text":"وَقَالُواْ قُلُوبُنَا غُلۡفُۢۚ بَل لَّعَنَهُمُ ٱللَّهُ بِكُفۡرِهِمۡ فَقَلِيلٗا مَّا يُؤۡمِنُونَ","aya_text_emlaey":"وقالوا قلوبنا غلف بل لعنهم الله بكفرهم فقليلا ما يؤمنون","aya_tafseer":"[88] وقال بنو إسرائيل لنبي الله ورسوله محمد -صلى الله عليه وسلم-: قلوبنا مغطاة، لا يَنْفُذ إليها قولك. وليس الأمر كما ادَّعَوْا، بل قلوبهم ملعونة، مطبوع عليها، وهم مطرودون من رحمة الله بسبب جحودهم، فلا يؤمنون إلا إيماناً قليلاً لا ينفعهم."},{"id":"96","jozz":"1","page":"14","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"1","line_end":"3","aya_no":"89","aya_text":"وَلَمَّا جَآءَهُمۡ كِتَٰبٞ مِّنۡ عِندِ ٱللَّهِ مُصَدِّقٞ لِّمَا مَعَهُمۡ وَكَانُواْ مِن قَبۡلُ يَسۡتَفۡتِحُونَ عَلَى ٱلَّذِينَ كَفَرُواْ فَلَمَّا جَآءَهُم مَّا عَرَفُواْ كَفَرُواْ بِهِۦۚ فَلَعۡنَةُ ٱللَّهِ عَلَى ٱلۡكَٰفِرِينَ","aya_text_emlaey":"ولما جاءهم كتاب من عند الله مصدق لما معهم وكانوا من قبل يستفتحون على الذين كفروا فلما جاءهم ما عرفوا كفروا به فلعنة الله على الكافرين","aya_tafseer":"[89] وحين جاءهم القرآن مِن عند الله مصدِّقاً لما معهم من التوراة جحدوه، وأنكروا نبوة محمد -صلى الله عليه وسلم-، وكانوا قبل بعثته يستنصرون به على مشركي العرب، ويقولون: قَرُبَ مبعث نبيِّ آخرِ الزمان، وسنتبعه ونقاتلكم معه. فلمَّا جاءهم الرسول الذي عرفوا صفاتِه وصِدْقَه كفروا به وكذبوه. فلعنةُ الله على كل مَن كفر بنبي الله ورسوله محمد -صلى الله عليه وسلم-، وكتابه الذي أوحاه الله إليه."},{"id":"97","jozz":"1","page":"14","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"4","line_end":"6","aya_no":"90","aya_text":"بِئۡسَمَا ٱشۡتَرَوۡاْ بِهِۦٓ أَنفُسَهُمۡ أَن يَكۡفُرُواْ بِمَآ أَنزَلَ ٱللَّهُ بَغۡيًا أَن يُنَزِّلَ ٱللَّهُ مِن فَضۡلِهِۦ عَلَىٰ مَن يَشَآءُ مِنۡ عِبَادِهِۦۖ فَبَآءُو بِغَضَبٍ عَلَىٰ غَضَبٖۚ وَلِلۡكَٰفِرِينَ عَذَابٞ مُّهِينٞ","aya_text_emlaey":"بئسما اشتروا به أنفسهم أن يكفروا بما أنـزل الله بغيا أن ينـزل الله من فضله على من يشاء من عباده فباءوا بغضب على غضب وللكافرين عذاب مهين","aya_tafseer":"[90] قَبُحَ ما اختاره بنو إسرائيل لأنفسهم؛ إذ استبدلوا الكفر بالإيمان ظلماً وحسداً لإنزال الله -من فضله- القرآن على نبي الله ورسوله محمد -صلى الله عليه وسلم-، فرجعوا بغضب من الله عليهم بسبب جحودهم بالنبي محمد -صلى الله عليه وسلم-، بعد غضب الله كذلك عليهم بسبب تحريفهم التوراة. وللجاحدين نبوَّة محمد -صلى الله عليه وسلم- عذابٌ يذلُّهم ويخزيهم."},{"id":"98","jozz":"1","page":"14","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"7","line_end":"10","aya_no":"91","aya_text":"وَإِذَا قِيلَ لَهُمۡ ءَامِنُواْ بِمَآ أَنزَلَ ٱللَّهُ قَالُواْ نُؤۡمِنُ بِمَآ أُنزِلَ عَلَيۡنَا وَيَكۡفُرُونَ بِمَا وَرَآءَهُۥ وَهُوَ ٱلۡحَقُّ مُصَدِّقٗا لِّمَا مَعَهُمۡۗ قُلۡ فَلِمَ تَقۡتُلُونَ أَنۢبِيَآءَ ٱللَّهِ مِن قَبۡلُ إِن كُنتُم مُّؤۡمِنِينَ","aya_text_emlaey":"وإذا قيل لهم آمنوا بما أنـزل الله قالوا نؤمن بما أنـزل علينا ويكفرون بما وراءه وهو الحق مصدقا لما معهم قل فلم تقتلون أنبياء الله من قبل إن كنتم مؤمنين","aya_tafseer":"[91] وإذا قال بعض المسلمين لليهود: صدِّقوا بما أنزل الله من القرآن، قالوا: نحن نصدِّق بما أنزل الله على أنبيائنا، ويجحدون ما أنزل الله بعد ذلك، وهو الحق مصدقاً لما معهم. فلو كانوا يؤمنون بكتبهم حقّاً لآمنوا بالقرآن الذي صدَّقها. قل لهم -أيها الرسول-: إن كنتم مؤمنين بما أنزل الله عليكم، فلماذا قتلتم أنبياء الله مِن قبل؟"},{"id":"99","jozz":"1","page":"14","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"10","line_end":"11","aya_no":"92","aya_text":"۞ وَلَقَدۡ جَآءَكُم مُّوسَىٰ بِٱلۡبَيِّنَٰتِ ثُمَّ ٱتَّخَذۡتُمُ ٱلۡعِجۡلَ مِنۢ بَعۡدِهِۦ وَأَنتُمۡ ظَٰلِمُونَ","aya_text_emlaey":"ولقد جاءكم موسى بالبينات ثم اتخذتم العجل من بعده وأنتم ظالمون","aya_tafseer":"[92] ولقد جاءكم نبي الله موسى بالمعجزات الواضحات الدالة على صدقه، كالطوفان والجراد والقُمَّل والضفادع، وغير ذلك مما ذكره الله في القرآن العظيم، ومع ذلك اتخذتم العجل معبوداً، بعد ذهاب موسى إلى ميقات ربه، وأنتم متجاوزون حدود الله."},{"id":"100","jozz":"1","page":"14","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"11","line_end":"15","aya_no":"93","aya_text":"وَإِذۡ أَخَذۡنَا مِيثَٰقَكُمۡ وَرَفَعۡنَا فَوۡقَكُمُ ٱلطُّورَ خُذُواْ مَآ ءَاتَيۡنَٰكُم بِقُوَّةٖ وَٱسۡمَعُواْۖ قَالُواْ سَمِعۡنَا وَعَصَيۡنَا وَأُشۡرِبُواْ فِي قُلُوبِهِمُ ٱلۡعِجۡلَ بِكُفۡرِهِمۡۚ قُلۡ بِئۡسَمَا يَأۡمُرُكُم بِهِۦٓ إِيمَٰنُكُمۡ إِن كُنتُم مُّؤۡمِنِينَ","aya_text_emlaey":"وإذ أخذنا ميثاقكم ورفعنا فوقكم الطور خذوا ما آتيناكم بقوة واسمعوا قالوا سمعنا وعصينا وأشربوا في قلوبهم العجل بكفرهم قل بئسما يأمركم به إيمانكم إن كنتم مؤمنين","aya_tafseer":"[93] واذكروا حين أَخَذْنا عليكم عهداً مؤكداً بقَبول ما جاءكم به موسى من التوراة، فنقضتم العهد، فرفعنا جبل الطور فوق رؤوسكم، وقلنا لكم: خذوا ما آتيناكم بجدٍّ، واسمعوا وأطيعوا، وإلا أسقطنا الجبل عليكم، فقلتم: سمعنا قولك وعصينا أمرك؛ لأن عبادة العجل قد امتزجت بقلوبكم بسبب تماديكم في الكفر. قل لهم -أيها الرسول-: قَبُحَ ما يأمركم به إيمانكم من الكفر والضلال، إن كنتم مصدِّقين بما أنزل الله عليكم."},{"id":"101","jozz":"1","page":"15","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"1","line_end":"2","aya_no":"94","aya_text":"قُلۡ إِن كَانَتۡ لَكُمُ ٱلدَّارُ ٱلۡأٓخِرَةُ عِندَ ٱللَّهِ خَالِصَةٗ مِّن دُونِ ٱلنَّاسِ فَتَمَنَّوُاْ ٱلۡمَوۡتَ إِن كُنتُمۡ صَٰدِقِينَ","aya_text_emlaey":"قل إن كانت لكم الدار الآخرة عند الله خالصة من دون الناس فتمنوا الموت إن كنتم صادقين","aya_tafseer":"[94] قل -أيها الرسول- لليهود الذين يدَّعون أن الجنة خاصة بهم؛ لزعمهم أنهم أولياء الله من دون الناس، وأنهم أبناؤه وأحباؤه: إن كان الأمر كذلك فادْعُوا على الكاذبين منكم أو من غيركم بالموت، إن كنتم صادقين في دعواكم هذه."},{"id":"102","jozz":"1","page":"15","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"2","line_end":"3","aya_no":"95","aya_text":"وَلَن يَتَمَنَّوۡهُ أَبَدَۢا بِمَا قَدَّمَتۡ أَيۡدِيهِمۡۚ وَٱللَّهُ عَلِيمُۢ بِٱلظَّٰلِمِينَ","aya_text_emlaey":"ولن يتمنوه أبدا بما قدمت أيديهم والله عليم بالظالمين","aya_tafseer":"[95] ولن يفعلوا ذلك أبداً؛ لما يعرفونه من صدق النبي محمد -صلى الله عليه وسلم- ومن كذبهم وافترائهم، وبسبب ما ارتكبوه من الكفر والعصيان، المؤَدِّيَيْن إلى حرمانهم من الجنة ودخول النار. والله تعالى عليم بالظالمين من عباده، وسيجازيهم على ذلك."},{"id":"103","jozz":"1","page":"15","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"4","line_end":"6","aya_no":"96","aya_text":"وَلَتَجِدَنَّهُمۡ أَحۡرَصَ ٱلنَّاسِ عَلَىٰ حَيَوٰةٖ وَمِنَ ٱلَّذِينَ أَشۡرَكُواْۚ يَوَدُّ أَحَدُهُمۡ لَوۡ يُعَمَّرُ أَلۡفَ سَنَةٖ وَمَا هُوَ بِمُزَحۡزِحِهِۦ مِنَ ٱلۡعَذَابِ أَن يُعَمَّرَۗ وَٱللَّهُ بَصِيرُۢ بِمَا يَعۡمَلُونَ","aya_text_emlaey":"ولتجدنهم أحرص الناس على حياة ومن الذين أشركوا يود أحدهم لو يعمر ألف سنة وما هو بمزحزحه من العذاب أن يعمر والله بصير بما يعملون","aya_tafseer":"[96] ولتعلمَنَّ -أيها الرسول- أن اليهود أشد الناس رغبة في طول الحياة أيّاً كانت هذه الحياة من الذلَّة والمهانة، بل تزيد رغبتهم في طول الحياة على رغبات المشركين. يتمنى اليهودي أن يعيش ألف سنة، ولا يُبْعده هذا العمر الطويل -إن حصل- من عذاب الله. والله تعالى لا يخفى عليه شيء من أعمالهم، وسيجازيهم عليها بما يستحقونه من العذاب."},{"id":"104","jozz":"1","page":"15","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"6","line_end":"8","aya_no":"97","aya_text":"قُلۡ مَن كَانَ عَدُوّٗا لِّـجِبۡرِيلَ فَإِنَّهُۥ نَزَّلَهُۥ عَلَىٰ قَلۡبِكَ بِإِذۡنِ ٱللَّهِ مُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِ وَهُدٗى وَبُشۡرَىٰ لِلۡمُؤۡمِنِينَ","aya_text_emlaey":"قل من كان عدوا لجبريل فإنه نـزله على قلبك بإذن الله مصدقا لما بين يديه وهدى وبشرى للمؤمنين","aya_tafseer":"[97] قل -أيها الرسول- لليهود حين قالوا: إن جبريل هو عدونا من الملائكة: من كان عدوّاً لجبريل فإنه نزَّل القرآن على قلبك بإذن الله تعالى مصدِّقاً لِمَا سبقه من كتب الله، وهادياً إلى الحق، ومبشراً للمصدِّقين به بكل خير في الدنيا والآخرة."},{"id":"105","jozz":"1","page":"15","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"9","line_end":"10","aya_no":"98","aya_text":"مَن كَانَ عَدُوّٗا لِّلَّهِ وَمَلَٰٓئِكَتِهِۦ وَرُسُلِهِۦ وَجِبۡرِيلَ وَمِيكَىٰلَ فَإِنَّ ٱللَّهَ عَدُوّٞ لِّلۡكَٰفِرِينَ","aya_text_emlaey":"من كان عدوا لله وملائكته ورسله وجبريل وميكال فإن الله عدو للكافرين","aya_tafseer":"[98] من عادى الله وملائكته، ورسله من الملائكة أو البشر، وبخاصة المَلَكان جبريلُ وميكالُ؛ لأن اليهود زعموا أن جبريل عدوهم، وميكال وليُّهم، فأعلمهم الله أنه من عادى واحداً منهما فقد عادى الآخر، وعادى الله أيضاً، فإن الله عدو للجاحدين ما أنزل على رسوله محمد -صلى الله عليه وسلم-."},{"id":"106","jozz":"1","page":"15","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"10","line_end":"11","aya_no":"99","aya_text":"وَلَقَدۡ أَنزَلۡنَآ إِلَيۡكَ ءَايَٰتِۭ بَيِّنَٰتٖۖ وَمَا يَكۡفُرُ بِهَآ إِلَّا ٱلۡفَٰسِقُونَ","aya_text_emlaey":"ولقد أنـزلنا إليك آيات بينات وما يكفر بها إلا الفاسقون","aya_tafseer":"[99] ولقد أنزلنا إليك -أيها الرسول- آيات بينات واضحات، تدلُّ على أنك رسول من الله صدقاً وحقّاً، وما ينكر تلك الآيات إلا الخارجون عن دين الله."},{"id":"107","jozz":"1","page":"15","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"12","line_end":"13","aya_no":"100","aya_text":"أَوَكُلَّمَا عَٰهَدُواْ عَهۡدٗا نَّبَذَهُۥ فَرِيقٞ مِّنۡهُمۚ بَلۡ أَكۡثَرُهُمۡ لَا يُؤۡمِنُونَ","aya_text_emlaey":"أو كلما عاهدوا عهدا نبذه فريق منهم بل أكثرهم لا يؤمنون","aya_tafseer":"[100] ما أقبح حال بني إسرائيل في نقضهم للعهود ! فكلما عاهدوا عهداً طرح ذلك العهد فريق منهم، ونقضوه، فتراهم يُبْرِمون العهد اليوم وينقضونه غداً، بل أكثرهم لا يصدِّقون بما جاء به نبي الله ورسوله محمد -صلى الله عليه وسلم-."},{"id":"108","jozz":"1","page":"15","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"13","line_end":"15","aya_no":"101","aya_text":"وَلَمَّا جَآءَهُمۡ رَسُولٞ مِّنۡ عِندِ ٱللَّهِ مُصَدِّقٞ لِّمَا مَعَهُمۡ نَبَذَ فَرِيقٞ مِّنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ كِتَٰبَ ٱللَّهِ وَرَآءَ ظُهُورِهِمۡ كَأَنَّهُمۡ لَا يَعۡلَمُونَ","aya_text_emlaey":"ولما جاءهم رسول من عند الله مصدق لما معهم نبذ فريق من الذين أوتوا الكتاب كتاب الله وراء ظهورهم كأنهم لا يعلمون","aya_tafseer":"[101] ولما جاءهم محمد رسول الله -صلى الله عليه وسلم- بالقرآن الموافق لما معهم من التوراة طرح فريق منهم كتاب الله، وجعلوه وراء ظهورهم، شأنهم شأن الجهال الذين لا يعلمون حقيقته."},{"id":"109","jozz":"1","page":"16","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"1","line_end":"9","aya_no":"102","aya_text":"وَٱتَّبَعُواْ مَا تَتۡلُواْ ٱلشَّيَٰطِينُ عَلَىٰ مُلۡكِ سُلَيۡمَٰنَۖ وَمَا كَفَرَ سُلَيۡمَٰنُ وَلَٰكِنَّ ٱلشَّيَٰطِينَ كَفَرُواْ يُعَلِّمُونَ ٱلنَّاسَ ٱلسِّحۡرَ وَمَآ أُنزِلَ عَلَى ٱلۡمَلَكَيۡنِ بِبَابِلَ هَٰرُوتَ وَمَٰرُوتَۚ وَمَا يُعَلِّمَانِ مِنۡ أَحَدٍ حَتَّىٰ يَقُولَآ إِنَّمَا نَحۡنُ فِتۡنَةٞ فَلَا تَكۡفُرۡۖ فَيَتَعَلَّمُونَ مِنۡهُمَا مَا يُفَرِّقُونَ بِهِۦ بَيۡنَ ٱلۡمَرۡءِ وَزَوۡجِهِۦۚ وَمَا هُم بِضَآرِّينَ بِهِۦ مِنۡ أَحَدٍ إِلَّا بِإِذۡنِ ٱللَّهِۚ وَيَتَعَلَّمُونَ مَا يَضُرُّهُمۡ وَلَا يَنفَعُهُمۡۚ وَلَقَدۡ عَلِمُواْ لَمَنِ ٱشۡتَرَىٰهُ مَا لَهُۥ فِي ٱلۡأٓخِرَةِ مِنۡ خَلَٰقٖۚ وَلَبِئۡسَ مَا شَرَوۡاْ بِهِۦٓ أَنفُسَهُمۡۚ لَوۡ كَانُواْ يَعۡلَمُونَ","aya_text_emlaey":"واتبعوا ما تتلوا الشياطين على ملك سليمان وما كفر سليمان ولكن الشياطين كفروا يعلمون الناس السحر وما أنـزل على الملكين ببابل هاروت وماروت وما يعلمان من أحد حتى يقولا إنما نحن فتنة فلا تكفر فيتعلمون منهما ما يفرقون به بين المرء وزوجه وما هم بضارين به من أحد إلا بإذن الله ويتعلمون ما يضرهم ولا ينفعهم ولقد علموا لمن اشتراه ما له في الآخرة من خلاق ولبئس ما شروا به أنفسهم لو كانوا يعلمون","aya_tafseer":"[102] واتبع اليهود ما تُحَدِّث الشياطينُ به السحرةَ على عهد ملك سليمان بن داود. وما كفر سليمان وما تَعلَّم السِّحر، ولكنَّ الشياطين هم الذين كفروا بالله حين علَّموا الناس السحر؛ إفساداً لدينهم. وكذلك اتبع اليهود السِّحر الذي أُنزل على الملَكَين هاروت وماروت، بأرض «بابل» في «العراق»؛ امتحاناً وابتلاء من الله لعباده، وما يعلِّمُ الملكان من أحد حتى ينصحاه ويحذِّراه مِن تعلُّم السِّحر، ويقولا له: لا تكفر بتعلم السِّحر وطاعة الشياطين. فيتعلم الناس من الملكين ما يُحْدِثون به الكراهية بين الزوجين حتى يتفرقا. ولا يستطيع السحرة أن يضرُّوا به أحداً إلا بإذن الله وقضائه. وما يتعلم السحرة إلا شرّاً يضرهم ولا ينفعهم، وقد نقلته الشياطين إلى اليهود، فشاع فيهم حتى فَضَّلوه على كتاب الله. ولقد علم اليهود أن من اختار السِّحر وترك الحق ما له في الآخرة مِن نصيب في الخير. ولبئس ما باعوا به أنفسهم من السحر والكفر عوضاً عن الإيمان ومتابعة الرسول، لو كان لهم عِلْمٌ يثمر العملَ بما وُعِظوا به."},{"id":"110","jozz":"1","page":"16","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"9","line_end":"10","aya_no":"103","aya_text":"وَلَوۡ أَنَّهُمۡ ءَامَنُواْ وَٱتَّقَوۡاْ لَمَثُوبَةٞ مِّنۡ عِندِ ٱللَّهِ خَيۡرٞۚ لَّوۡ كَانُواْ يَعۡلَمُونَ","aya_text_emlaey":"ولو أنهم آمنوا واتقوا لمثوبة من عند الله خير لو كانوا يعلمون","aya_tafseer":"[103] ولو أن اليهود آمنوا وخافوا الله لأيقنوا أن ثواب الله خير لهم من السِّحر ومما اكتسبوه به، لو كانوا يعلمون ما يحصل بالإيمان والتقوى من الثواب والجزاء علماً حقيقيّاً لآمنوا."},{"id":"111","jozz":"1","page":"16","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"11","line_end":"12","aya_no":"104","aya_text":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَقُولُواْ رَٰعِنَا وَقُولُواْ ٱنظُرۡنَا وَٱسۡمَعُواْۗ وَلِلۡكَٰفِرِينَ عَذَابٌ أَلِيمٞ","aya_text_emlaey":"ياأيها الذين آمنوا لا تقولوا راعنا وقولوا انظرنا واسمعوا وللكافرين عذاب أليم","aya_tafseer":"[104] يا أيها الذين آمنوا لا تقولوا للرسول محمد -صلى الله عليه وسلم-: راعنا، أي: راعنا سمعك، فافهم عنا وأفهمنا؛ لأن اليهود كانوا يقولونها للنبي -صلى الله عليه وسلم-، يلوون ألسنتهم بها، يقصدون سَبَّه ونسبته إلى الرعونة، وقولوا -أيها المؤمنون- بدلاً منها: انظرنا، أي انظر إلينا وتعهَّدْنا، وهي تؤدي المعنى المطلوب نفسه، واسمعوا ما يتلى عليكم من كتاب ربكم وافهموه. وللجاحدين عذاب موجع."},{"id":"112","jozz":"1","page":"16","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"12","line_end":"15","aya_no":"105","aya_text":"مَّا يَوَدُّ ٱلَّذِينَ كَفَرُواْ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ وَلَا ٱلۡمُشۡرِكِينَ أَن يُنَزَّلَ عَلَيۡكُم مِّنۡ خَيۡرٖ مِّن رَّبِّكُمۡۚ وَٱللَّهُ يَخۡتَصُّ بِرَحۡمَتِهِۦ مَن يَشَآءُۚ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِيمِ","aya_text_emlaey":"ما يود الذين كفروا من أهل الكتاب ولا المشركين أن ينـزل عليكم من خير من ربكم والله يختص برحمته من يشاء والله ذو الفضل العظيم","aya_tafseer":"[105] ما يحب الكفار من أهل الكتاب والمشركين أن يُنزَّل عليكم أدنى خير من ربكم قرآناً أو علماً، أو نصراً أو بشارة. والله يختص برحمته مَن يشاء مِن عباده بالنبوَّة والرسالة. والله ذو الإحسان والعطاء الكثير الواسع."},{"id":"113","jozz":"1","page":"17","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"1","line_end":"2","aya_no":"106","aya_text":"۞ مَا نَنسَخۡ مِنۡ ءَايَةٍ أَوۡ نُنسِهَا نَأۡتِ بِخَيۡرٖ مِّنۡهَآ أَوۡ مِثۡلِهَآۗ أَلَمۡ تَعۡلَمۡ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ","aya_text_emlaey":"ما ننسخ من آية أو ننسها نأت بخير منها أو مثلها ألم تعلم أن الله على كل شيء قدير","aya_tafseer":"[106] ما نبدِّل من آية أو نُزِلْها من القلوب والأذهان نأت بأنفع لكم منها، أو نأت بمثلها في التكليف والثواب، ولكلٍّ حكمة. ألم تعلم -أيها النبي- أنت وأمتك أن الله قادر لا يعجزه شيء؟"},{"id":"114","jozz":"1","page":"17","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"2","line_end":"4","aya_no":"107","aya_text":"أَلَمۡ تَعۡلَمۡ أَنَّ ٱللَّهَ لَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِيّٖ وَلَا نَصِيرٍ","aya_text_emlaey":"ألم تعلم أن الله له ملك السموات والأرض وما لكم من دون الله من ولي ولا نصير","aya_tafseer":"[107] أما علمتَ -أيها النبي- أنت وأمتك أن الله تعالى هو المالك المتصرف في السموات والأرض؟ يفعل ما يشاء، ويحكم ما يريد، ويأمر عباده وينهاهم كيفما شاء، وعليهم الطاعة والقَبول. وليعلم من عصى أن ليس لأحد من دون الله مِن وليٍّ يتولاهم، ولا نصير يمنعهم من عذاب الله."},{"id":"115","jozz":"1","page":"17","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"4","line_end":"6","aya_no":"108","aya_text":"أَمۡ تُرِيدُونَ أَن تَسۡـَٔلُواْ رَسُولَكُمۡ كَمَا سُئِلَ مُوسَىٰ مِن قَبۡلُۗ وَمَن يَتَبَدَّلِ ٱلۡكُفۡرَ بِٱلۡإِيمَٰنِ فَقَدۡ ضَلَّ سَوَآءَ ٱلسَّبِيلِ","aya_text_emlaey":"أم تريدون أن تسألوا رسولكم كما سئل موسى من قبل ومن يتبدل الكفر بالإيمان فقد ضل سواء السبيل","aya_tafseer":"[108] بل أتريدون -أيها الناس- أن تطلبوا من رسولكم محمد -صلى الله عليه وسلم- أشياء بقصد العناد والمكابرة، كما طُلِب مثل ذلك من موسى. واعلموا أن من يختر الكفر ويترك الإيمان فقد خرج عن صراط الله المستقيم إلى الجهل والضَّلال."},{"id":"116","jozz":"1","page":"17","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"6","line_end":"10","aya_no":"109","aya_text":"وَدَّ كَثِيرٞ مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ لَوۡ يَرُدُّونَكُم مِّنۢ بَعۡدِ إِيمَٰنِكُمۡ كُفَّارًا حَسَدٗا مِّنۡ عِندِ أَنفُسِهِم مِّنۢ بَعۡدِ مَا تَبَيَّنَ لَهُمُ ٱلۡحَقُّۖ فَٱعۡفُواْ وَٱصۡفَحُواْ حَتَّىٰ يَأۡتِيَ ٱللَّهُ بِأَمۡرِهِۦٓۗ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ","aya_text_emlaey":"ود كثير من أهل الكتاب لو يردونكم من بعد إيمانكم كفارا حسدا من عند أنفسهم من بعد ما تبين لهم الحق فاعفوا واصفحوا حتى يأتي الله بأمره إن الله على كل شيء قدير","aya_tafseer":"[109] تمنى كثير من أهل الكتاب أن يرجعوكم بعد إيمانكم كفاراً كما كنتم من قبلُ تعبدون الأصنام؛ بسبب الحقد الذي امتلأت به نفوسهم من بعد ما تبيَّن لهم صدق نبي الله ورسوله محمد -صلى الله عليه وسلم- فيما جاء به، فتجاوزوا عمَّا كان منهم من إساءة وخطأ، واصفحوا عن جهلهم، حتى يأتي الله بحكمه فيهم بقتالهم (وقد جاء ووقع)، وسيعاقبهم لسوء أفعالهم. إن الله على كل شيء قدير لا يعجزه شيء."},{"id":"117","jozz":"1","page":"17","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"10","line_end":"12","aya_no":"110","aya_text":"وَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَۚ وَمَا تُقَدِّمُواْ لِأَنفُسِكُم مِّنۡ خَيۡرٖ تَجِدُوهُ عِندَ ٱللَّهِۗ إِنَّ ٱللَّهَ بِمَا تَعۡمَلُونَ بَصِيرٞ","aya_text_emlaey":"وأقيموا الصلاة وآتوا الزكاة وما تقدموا لأنفسكم من خير تجدوه عند الله إن الله بما تعملون بصير","aya_tafseer":"[110] واشتغلوا -أيها المؤمنون- بأداء الصلاة على وجهها الصحيح، وإعطاء الزكاة المفروضة. واعلموا أنَّ كل خير تقدمونه لأنفسكم تجدون ثوابه عند الله في الآخرة. إنه تعالى بصير بكل أعمالكم، وسيجازيكم عليها."},{"id":"118","jozz":"1","page":"17","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"12","line_end":"14","aya_no":"111","aya_text":"وَقَالُواْ لَن يَدۡخُلَ ٱلۡجَنَّةَ إِلَّا مَن كَانَ هُودًا أَوۡ نَصَٰرَىٰۗ تِلۡكَ أَمَانِيُّهُمۡۗ قُلۡ هَاتُواْ بُرۡهَٰنَكُمۡ إِن كُنتُمۡ صَٰدِقِينَ","aya_text_emlaey":"وقالوا لن يدخل الجنة إلا من كان هودا أو نصارى تلك أمانيهم قل هاتوا برهانكم إن كنتم صادقين","aya_tafseer":"[111] ادَّعى كلٌّ من اليهود والنصارى أن الجنة خاصة بطائفته لا يدخلها غيرهم، تلك أوهامهم الفاسدة. قل لهم -أيها الرسول-: أحضروا دليلكم على صحة ما تدَّعون إن كنتم صادقين في دعواكم."},{"id":"119","jozz":"1","page":"17","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"14","line_end":"15","aya_no":"112","aya_text":"بَلَىٰۚ مَنۡ أَسۡلَمَ وَجۡهَهُۥ لِلَّهِ وَهُوَ مُحۡسِنٞ فَلَهُۥٓ أَجۡرُهُۥ عِندَ رَبِّهِۦ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ","aya_text_emlaey":"بلى من أسلم وجهه لله وهو محسن فله أجره عند ربه ولا خوف عليهم ولا هم يحزنون","aya_tafseer":"[112] ليس الأمر كما زعموا أنَّ الجنة تختص بطائفة دون غيرها، وإنما يدخل الجنَّة مَن أخلص لله وحده لا شريك له، وهو متبع للرسول محمد -صلى الله عليه وسلم- في كل أقواله وأعماله. فمن فعل ذلك فله ثواب عمله عند ربه في الآخرة، وهو دخول الجنة، وهم لا يخافون فيما يستقبلونه من أمر الآخرة، ولا هم يحزنون على ما فاتهم من حظوظ الدنيا."},{"id":"120","jozz":"1","page":"18","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"1","line_end":"4","aya_no":"113","aya_text":"وَقَالَتِ ٱلۡيَهُودُ لَيۡسَتِ ٱلنَّصَٰرَىٰ عَلَىٰ شَيۡءٖ وَقَالَتِ ٱلنَّصَٰرَىٰ لَيۡسَتِ ٱلۡيَهُودُ عَلَىٰ شَيۡءٖ وَهُمۡ يَتۡلُونَ ٱلۡكِتَٰبَۗ كَذَٰلِكَ قَالَ ٱلَّذِينَ لَا يَعۡلَمُونَ مِثۡلَ قَوۡلِهِمۡۚ فَٱللَّهُ يَحۡكُمُ بَيۡنَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ فِيمَا كَانُواْ فِيهِ يَخۡتَلِفُونَ","aya_text_emlaey":"وقالت اليهود ليست النصارى على شيء وقالت النصارى ليست اليهود على شيء وهم يتلون الكتاب كذلك قال الذين لا يعلمون مثل قولهم فالله يحكم بينهم يوم القيامة فيما كانوا فيه يختلفون","aya_tafseer":"[113] وقالت اليهود: ليست النصارى على شيء من الدين الصحيح، وكذلك قالت النصارى في اليهود وهم يقرؤون التوراة والإنجيل، وفيهما وجوب الإيمان بالأنبياء جميعاً. كذلك قال الذين لا يعلمون من مشركي العرب وغيرهم مثلَ قولهم، أي قالوا لكل ذي دين: لست على شيء، فالله يفصل بينهم يوم القيامة فيما اختلفوا فيه مِن أمر الدين، ويجازي كُلّاً بعمله."},{"id":"121","jozz":"1","page":"18","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"4","line_end":"7","aya_no":"114","aya_text":"وَمَنۡ أَظۡلَمُ مِمَّن مَّنَعَ مَسَٰجِدَ ٱللَّهِ أَن يُذۡكَرَ فِيهَا ٱسۡمُهُۥ وَسَعَىٰ فِي خَرَابِهَآۚ أُوْلَٰٓئِكَ مَا كَانَ لَهُمۡ أَن يَدۡخُلُوهَآ إِلَّا خَآئِفِينَۚ لَهُمۡ فِي ٱلدُّنۡيَا خِزۡيٞ وَلَهُمۡ فِي ٱلۡأٓخِرَةِ عَذَابٌ عَظِيمٞ","aya_text_emlaey":"ومن أظلم ممن منع مساجد الله أن يذكر فيها اسمه وسعى في خرابها أولئك ما كان لهم أن يدخلوها إلا خائفين لهم في الدنيا خزي ولهم في الآخرة عذاب عظيم","aya_tafseer":"[114] لا أحد أظلم من الذين منعوا ذِكْرَ الله في المساجد من إقام الصلاة، وتلاوة القرآن، ونحو ذلك، وجدُّوا في تخريبها بالهدم، أو الإغلاق، أو بمنع المؤمنين منها. أولئك الظالمون ما كان ينبغي لهم أن يدخلوا المساجد إلا على خوف ووجل من العقوبة. لهم بذلك ذُلٌّ وفضيحة في الدنيا، ولهم في الآخرة عذاب شديد."},{"id":"122","jozz":"1","page":"18","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"7","line_end":"8","aya_no":"115","aya_text":"وَلِلَّهِ ٱلۡمَشۡرِقُ وَٱلۡمَغۡرِبُۚ فَأَيۡنَمَا تُوَلُّواْ فَثَمَّ وَجۡهُ ٱللَّهِۚ إِنَّ ٱللَّهَ وَٰسِعٌ عَلِيمٞ","aya_text_emlaey":"ولله المشرق والمغرب فأينما تولوا فثم وجه الله إن الله واسع عليم","aya_tafseer":"[115] ولله جهتا شروق الشمس وغروبها وما بينهما، فهو مالك الأرض كلِّها. فأي جهة توجهتم إليها في الصلاة بأمر الله لكم فإنكم مبتغون وجهه، لم تخرجوا عن ملكه وطاعته. إن الله واسع الرحمة بعباده، عليم بأفعالهم، لا يغيب عنه منها شيء."},{"id":"123","jozz":"1","page":"18","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"9","line_end":"10","aya_no":"116","aya_text":"وَقَالُواْ ٱتَّخَذَ ٱللَّهُ وَلَدٗاۗ سُبۡحَٰنَهُۥۖ بَل لَّهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ كُلّٞ لَّهُۥ قَٰنِتُونَ","aya_text_emlaey":"وقالوا اتخذ الله ولدا سبحانه بل له ما في السموات والأرض كل له قانتون","aya_tafseer":"[116] وقالت اليهود والنصارى والمشركون: اتخذ الله لنفسه ولداً، تنزَّه الله -سبحانه- عن هذا القول الباطل، بل كل ما في السموات والأرض ملكه وعبيده، وهم جميعاً خاضعون له، مسخَّرون تحت تدبيره."},{"id":"124","jozz":"1","page":"18","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"10","line_end":"11","aya_no":"117","aya_text":"بَدِيعُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ وَإِذَا قَضَىٰٓ أَمۡرٗا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ","aya_text_emlaey":"بديع السموات والأرض وإذا قضى أمرا فإنما يقول له كن فيكون","aya_tafseer":"[117] والله تعالى هو خالق السموات والأرض على غير مثال سبق. وإذا قدَّر أمراً وأراد كونه فإنما يقول له: «كن» فيكون."},{"id":"125","jozz":"1","page":"18","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"11","line_end":"14","aya_no":"118","aya_text":"وَقَالَ ٱلَّذِينَ لَا يَعۡلَمُونَ لَوۡلَا يُكَلِّمُنَا ٱللَّهُ أَوۡ تَأۡتِينَآ ءَايَةٞۗ كَذَٰلِكَ قَالَ ٱلَّذِينَ مِن قَبۡلِهِم مِّثۡلَ قَوۡلِهِمۡۘ تَشَٰبَهَتۡ قُلُوبُهُمۡۗ قَدۡ بَيَّنَّا ٱلۡأٓيَٰتِ لِقَوۡمٖ يُوقِنُونَ","aya_text_emlaey":"وقال الذين لا يعلمون لولا يكلمنا الله أو تأتينا آية كذلك قال الذين من قبلهم مثل قولهم تشابهت قلوبهم قد بينا الآيات لقوم يوقنون","aya_tafseer":"[118] وقال الجهلة من أهل الكتاب وغيرهم لنبي الله ورسوله محمد -صلى الله عليه وسلم- على سبيل العناد: هلَّا يكلمنا الله مباشرة ليخبرنا أنك رسوله، أو تأتينا معجزة من الله تدل على صدقك. مثل هذا القول قالته الأمم مِن قبلُ لرسلها عناداً ومكابرة؛ بسبب تشابه قلوب السابقين واللاحقين في الكفر والضَّلال. قد أوضحنا الآيات للذين يصدِّقون تصديقاً جازماً؛ لكونهم مؤمنين بالله تعالى، متَّبعين ما شرعه لهم."},{"id":"126","jozz":"1","page":"18","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"14","line_end":"15","aya_no":"119","aya_text":"إِنَّآ أَرۡسَلۡنَٰكَ بِٱلۡحَقِّ بَشِيرٗا وَنَذِيرٗاۖ وَلَا تُسۡـَٔلُ عَنۡ أَصۡحَٰبِ ٱلۡجَحِيمِ","aya_text_emlaey":"إنا أرسلناك بالحق بشيرا ونذيرا ولا تسأل عن أصحاب الجحيم","aya_tafseer":"[119] إنا أرسلناك -أيها الرسول- بالدين الحق المؤيد بالحجج والمعجزات، فبلِّغه للناس مع تبشير المؤمنين بخيري الدنيا والآخرة، وتخويف المعاندين بما ينتظرهم مِن عذاب الله، ولست -بعد البلاغ- مسؤولاً عن كفر مَن كفر بك؛ فإنهم يدخلون النار يوم القيامة ولا يخرجون منها."},{"id":"127","jozz":"1","page":"19","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"1","line_end":"3","aya_no":"120","aya_text":"وَلَن تَرۡضَىٰ عَنكَ ٱلۡيَهُودُ وَلَا ٱلنَّصَٰرَىٰ حَتَّىٰ تَتَّبِعَ مِلَّتَهُمۡۗ قُلۡ إِنَّ هُدَى ٱللَّهِ هُوَ ٱلۡهُدَىٰۗ وَلَئِنِ ٱتَّبَعۡتَ أَهۡوَآءَهُم بَعۡدَ ٱلَّذِي جَآءَكَ مِنَ ٱلۡعِلۡمِ مَا لَكَ مِنَ ٱللَّهِ مِن وَلِيّٖ وَلَا نَصِيرٍ","aya_text_emlaey":"ولن ترضى عنك اليهود ولا النصارى حتى تتبع ملتهم قل إن هدى الله هو الهدى ولئن اتبعت أهواءهم بعد الذي جاءك من العلم ما لك من الله من ولي ولا نصير","aya_tafseer":"[120] ولن ترضى عنك -أيها الرسول- اليهود ولا النصارى إلا إذا تركت دينك واتبعتَ دينهم. قل لهم: إن دين الإسلام هو الدين الصحيح. ولئن اتبعت أهواء هؤلاء بعد الذي جاءك من الوحي ما لك عند الله مِن وليٍّ ينفعك، ولا نصير ينصرك. وهذا الخطاب وإن كان خاصّاً بالنبي -صلى الله عليه وسلم-، فهو موجَّه إلى الأمة عامَّة."},{"id":"128","jozz":"1","page":"19","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"3","line_end":"5","aya_no":"121","aya_text":"ٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ يَتۡلُونَهُۥ حَقَّ تِلَاوَتِهِۦٓ أُوْلَٰٓئِكَ يُؤۡمِنُونَ بِهِۦۗ وَمَن يَكۡفُرۡ بِهِۦ فَأُوْلَٰٓئِكَ هُمُ ٱلۡخَٰسِرُونَ","aya_text_emlaey":"الذين آتيناهم الكتاب يتلونه حق تلاوته أولئك يؤمنون به ومن يكفر به فأولئك هم الخاسرون","aya_tafseer":"[121] الذين أعطيناهم الكتاب من اليهود والنصارى، يقرؤونه القراءة الصحيحة، و يتبعونه حق الاتباع، ويؤمنون بما جاء فيه من الإيمان برسل الله، ومنهم خاتمهم نبينا ورسولنا محمد -صلى الله عليه وسلم-، ولا يحرِّفون ولا يبدِّلون ما جاء فيه. هؤلاء هم الذين يؤمنون بالنبي محمد -صلى الله عليه وسلم- وبما أنزل عليه، وأما الذين بدَّلوا بعض الكتاب وكتموا بعضه، فهؤلاء كفار بنبي الله محمد -صلى الله عليه وسلم- وبما أنزل عليه، ومن يكفر به فأولئك هم أشد الناس خسراناً عند الله."},{"id":"129","jozz":"1","page":"19","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"5","line_end":"6","aya_no":"122","aya_text":"يَٰبَنِيٓ إِسۡرَٰٓءِيلَ ٱذۡكُرُواْ نِعۡمَتِيَ ٱلَّتِيٓ أَنۡعَمۡتُ عَلَيۡكُمۡ وَأَنِّي فَضَّلۡتُكُمۡ عَلَى ٱلۡعَٰلَمِينَ","aya_text_emlaey":"يابني إسرائيل اذكروا نعمتي التي أنعمت عليكم وأني فضلتكم على العالمين","aya_tafseer":"[122] يا ذريةَ يعقوبَ اذكروا نعمي الكثيرة عليكم، وأني فَضَّلتكم على عالَمي زمانكم بكثرة أنبيائكم، وما أُنزل عليهم من الكتب."},{"id":"130","jozz":"1","page":"19","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"6","line_end":"8","aya_no":"123","aya_text":"وَٱتَّقُواْ يَوۡمٗا لَّا تَجۡزِي نَفۡسٌ عَن نَّفۡسٖ شَيۡـٔٗا وَلَا يُقۡبَلُ مِنۡهَا عَدۡلٞ وَلَا تَنفَعُهَا شَفَٰعَةٞ وَلَا هُمۡ يُنصَرُونَ","aya_text_emlaey":"واتقوا يوما لا تجزي نفس عن نفس شيئا ولا يقبل منها عدل ولا تنفعها شفاعة ولا هم ينصرون","aya_tafseer":"[123] وخافوا أهوال يوم الحساب إذ لا تغني نفس عن نفس شيئاً، ولا يقبل الله منها فدية تنجيها من العذاب، ولا تنفعها وساطة، ولا أحد ينصرها."},{"id":"131","jozz":"1","page":"19","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"8","line_end":"10","aya_no":"124","aya_text":"۞ وَإِذِ ٱبۡتَلَىٰٓ إِبۡرَٰهِـۧمَ رَبُّهُۥ بِكَلِمَٰتٖ فَأَتَمَّهُنَّۖ قَالَ إِنِّي جَاعِلُكَ لِلنَّاسِ إِمَامٗاۖ قَالَ وَمِن ذُرِّيَّتِيۖ قَالَ لَا يَنَالُ عَهۡدِي ٱلظَّٰلِمِينَ","aya_text_emlaey":"وإذ ابتلى إبراهيم ربه بكلمات فأتمهن قال إني جاعلك للناس إماما قال ومن ذريتي قال لا ينال عهدي الظالمين","aya_tafseer":"[124] واذكر -أيها النبي- حين اختبر الله إبراهيم بما شرع له من تكاليف، فأدَّاها وقام بها خير قيام. قال الله له: إني جاعلك قدوة للناس. قال إبراهيم: ربِّ اجعل بعض نسلي أئمة فضلاً منك، فأجابه الله سبحانه أنه لا تحصل للظالمين الإمامةُ في الدين."},{"id":"132","jozz":"1","page":"19","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"10","line_end":"12","aya_no":"125","aya_text":"وَإِذۡ جَعَلۡنَا ٱلۡبَيۡتَ مَثَابَةٗ لِّلنَّاسِ وَأَمۡنٗا وَٱتَّخِذُواْ مِن مَّقَامِ إِبۡرَٰهِـۧمَ مُصَلّٗىۖ وَعَهِدۡنَآ إِلَىٰٓ إِبۡرَٰهِـۧمَ وَإِسۡمَٰعِيلَ أَن طَهِّرَا بَيۡتِيَ لِلطَّآئِفِينَ وَٱلۡعَٰكِفِينَ وَٱلرُّكَّعِ ٱلسُّجُودِ","aya_text_emlaey":"وإذ جعلنا البيت مثابة للناس وأمنا واتخذوا من مقام إبراهيم مصلى وعهدنا إلى إبراهيم وإسماعيل أن طهرا بيتي للطائفين والعاكفين والركع السجود","aya_tafseer":"[125] واذكر -أيها النبي- حين جعلنا الكعبة مرجعاً للناس، يأتونه، ثم يرجعون إلى أهليهم، ثم يعودون إليه، ومَجْمعاً لهم في الحج والعمرة، والطواف، والصلاة، وأمناً لهم، لا يُغِير عليهم عدو فيه. وقلنا: اتخِذوا من مقام إبراهيم مكاناً للصلاة فيه، وهو الحَجَر الذي وقف عليه إبراهيم عند بنائه الكعبة. وأوحينا إلى إبراهيم وابنه إسماعيل: أن طهِّرا بيتي من كل رجس ودنس؛ للمتعبدين فيه بالطواف حول الكعبة، أو الاعتكاف في المسجد، والصلاة فيه."},{"id":"133","jozz":"1","page":"19","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"13","line_end":"15","aya_no":"126","aya_text":"وَإِذۡ قَالَ إِبۡرَٰهِـۧمُ رَبِّ ٱجۡعَلۡ هَٰذَا بَلَدًا ءَامِنٗا وَٱرۡزُقۡ أَهۡلَهُۥ مِنَ ٱلثَّمَرَٰتِ مَنۡ ءَامَنَ مِنۡهُم بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۚ قَالَ وَمَن كَفَرَ فَأُمَتِّعُهُۥ قَلِيلٗا ثُمَّ أَضۡطَرُّهُۥٓ إِلَىٰ عَذَابِ ٱلنَّارِۖ وَبِئۡسَ ٱلۡمَصِيرُ","aya_text_emlaey":"وإذ قال إبراهيم رب اجعل هذا بلدا آمنا وارزق أهله من الثمرات من آمن منهم بالله واليوم الآخر قال ومن كفر فأمتعه قليلا ثم أضطره إلى عذاب النار وبئس المصير","aya_tafseer":"[126] واذكر -أيها النبي- حين قال إبراهيم داعياً: ربِّ اجعل «مكة» بلداً آمناً من الخوف، وارزق أهله من أنواع الثمرات، وخُصَّ بهذا الرزق مَن آمن منهم بالله واليوم الآخر. قال الله: ومن كفر منهم فأرزقه في الدنيا وأُمتِّعه متاعاً قليلاً، ثم أُلجئُه مرغَماً إلى عذاب النار. وبئس المرجع والمقام هذا المصير."},{"id":"134","jozz":"1","page":"20","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"1","line_end":"2","aya_no":"127","aya_text":"وَإِذۡ يَرۡفَعُ إِبۡرَٰهِـۧمُ ٱلۡقَوَاعِدَ مِنَ ٱلۡبَيۡتِ وَإِسۡمَٰعِيلُ رَبَّنَا تَقَبَّلۡ مِنَّآۖ إِنَّكَ أَنتَ ٱلسَّمِيعُ ٱلۡعَلِيمُ","aya_text_emlaey":"وإذ يرفع إبراهيم القواعد من البيت وإسماعيل ربنا تقبل منا إنك أنت السميع العليم","aya_tafseer":"[127] واذكر -أيها النبي- حين رفع إبراهيم وإسماعيل أسس الكعبة، وهما يدعوان الله في خشوع: ربنا تقبل منَّا صالح أعمالنا ودعاءنا، إنك أنت السميع لأقوال عبادك، العليم بأحوالهم."},{"id":"135","jozz":"1","page":"20","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"2","line_end":"4","aya_no":"128","aya_text":"رَبَّنَا وَٱجۡعَلۡنَا مُسۡلِمَيۡنِ لَكَ وَمِن ذُرِّيَّتِنَآ أُمَّةٗ مُّسۡلِمَةٗ لَّكَ وَأَرِنَا مَنَاسِكَنَا وَتُبۡ عَلَيۡنَآۖ إِنَّكَ أَنتَ ٱلتَّوَّابُ ٱلرَّحِيمُ","aya_text_emlaey":"ربنا واجعلنا مسلمين لك ومن ذريتنا أمة مسلمة لك وأرنا مناسكنا وتب علينا إنك أنت التواب الرحيم","aya_tafseer":"[128] ربنا واجعلنا ثابتَيْن على الإسلام، منقادَيْن لأحكامك، واجعل من ذريتنا أمة منقادة لك، بالإيمان، وبصِّرْنا بمعالم عبادتنا لك، وتجاوز عن ذنوبنا. إنك أنت كثير التوبة على عبادك، واسع الرحمة بهم."},{"id":"136","jozz":"1","page":"20","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"4","line_end":"6","aya_no":"129","aya_text":"رَبَّنَا وَٱبۡعَثۡ فِيهِمۡ رَسُولٗا مِّنۡهُمۡ يَتۡلُواْ عَلَيۡهِمۡ ءَايَٰتِكَ وَيُعَلِّمُهُمُ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَيُزَكِّيهِمۡۖ إِنَّكَ أَنتَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ","aya_text_emlaey":"ربنا وابعث فيهم رسولا منهم يتلو عليهم آياتك ويعلمهم الكتاب والحكمة ويزكيهم إنك أنت العزيز الحكيم","aya_tafseer":"[129] ربنا وابعث في هذه الأمة رسولاً من ذرية إسماعيل يتلو عليهم آياتك ويعلمهم القرآن والسنة، ويطهرهم من الشرك وسوء الأخلاق. إنك أنت العزيز الذي لا يمتنع عليه شيء، الحكيم الذي يضع الأشياء في مواضعها."},{"id":"137","jozz":"1","page":"20","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"6","line_end":"8","aya_no":"130","aya_text":"وَمَن يَرۡغَبُ عَن مِّلَّةِ إِبۡرَٰهِـۧمَ إِلَّا مَن سَفِهَ نَفۡسَهُۥۚ وَلَقَدِ ٱصۡطَفَيۡنَٰهُ فِي ٱلدُّنۡيَاۖ وَإِنَّهُۥ فِي ٱلۡأٓخِرَةِ لَمِنَ ٱلصَّٰلِحِينَ","aya_text_emlaey":"ومن يرغب عن ملة إبراهيم إلا من سفه نفسه ولقد اصطفيناه في الدنيا وإنه في الآخرة لمن الصالحين","aya_tafseer":"[130] ولا أحد يُعرض عن دين إبراهيم -وهو الإسلام- إلا سفيه جاهل، ولقد اخترنا إبراهيمَ في الدنيا نبيّاً ورسولاً، وإنه في الآخرة لمن الصالحين الذين لهم أعلى الدرجات."},{"id":"138","jozz":"1","page":"20","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"8","line_end":"9","aya_no":"131","aya_text":"إِذۡ قَالَ لَهُۥ رَبُّهُۥٓ أَسۡلِمۡۖ قَالَ أَسۡلَمۡتُ لِرَبِّ ٱلۡعَٰلَمِينَ","aya_text_emlaey":"إذ قال له ربه أسلم قال أسلمت لرب العالمين","aya_tafseer":"[131] وسبب هذا الاختيار مسارعته إلى الإسلام دون تردد، حين قال له ربه: أخلص نفسك لله منقاداً له. فاستجاب إبراهيم وقال: أسلمت لرب العالمين، إخلاصاً وتوحيداً ومحبة وإنابة."},{"id":"139","jozz":"1","page":"20","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"9","line_end":"11","aya_no":"132","aya_text":"وَوَصَّىٰ بِهَآ إِبۡرَٰهِـۧمُ بَنِيهِ وَيَعۡقُوبُ يَٰبَنِيَّ إِنَّ ٱللَّهَ ٱصۡطَفَىٰ لَكُمُ ٱلدِّينَ فَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسۡلِمُونَ","aya_text_emlaey":"ووصى بها إبراهيم بنيه ويعقوب يابني إن الله اصطفى لكم الدين فلا تموتن إلا وأنتم مسلمون","aya_tafseer":"[132] وحثَّ إبراهيمُ ويعقوبُ أبناءهما على الثبات على الإسلام قائلَيْن: يا أبناءنا إن الله اختار لكم هذا الدين -وهو دين الإسلام- فلا تفارقوه أيام حياتكم، ولا يأتكم الموت إلا وأنتم عليه."},{"id":"140","jozz":"1","page":"20","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"11","line_end":"14","aya_no":"133","aya_text":"أَمۡ كُنتُمۡ شُهَدَآءَ إِذۡ حَضَرَ يَعۡقُوبَ ٱلۡمَوۡتُ إِذۡ قَالَ لِبَنِيهِ مَا تَعۡبُدُونَ مِنۢ بَعۡدِيۖ قَالُواْ نَعۡبُدُ إِلَٰهَكَ وَإِلَٰهَ ءَابَآئِكَ إِبۡرَٰهِـۧمَ وَإِسۡمَٰعِيلَ وَإِسۡحَٰقَ إِلَٰهٗا وَٰحِدٗا وَنَحۡنُ لَهُۥ مُسۡلِمُونَ","aya_text_emlaey":"أم كنتم شهداء إذ حضر يعقوب الموت إذ قال لبنيه ما تعبدون من بعدي قالوا نعبد إلهك وإله آبائك إبراهيم وإسماعيل وإسحاق إلها واحدا ونحن له مسلمون","aya_tafseer":"[133] أكنتم -أيها اليهود- حاضرين حين جاء الموتُ يعقوبَ، إذ جمع أبناءه وسألهم: ما تعبدون من بعد موتي؟ قالوا: نعبد إلٰهك وإله آبائك إبراهيم وإسماعيل وإسحاق إلٰهاً واحداً، ونحن له منقادون خاضعون."},{"id":"141","jozz":"1","page":"20","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"14","line_end":"15","aya_no":"134","aya_text":"تِلۡكَ أُمَّةٞ قَدۡ خَلَتۡۖ لَهَا مَا كَسَبَتۡ وَلَكُم مَّا كَسَبۡتُمۡۖ وَلَا تُسۡـَٔلُونَ عَمَّا كَانُواْ يَعۡمَلُونَ","aya_text_emlaey":"تلك أمة قد خلت لها ما كسبت ولكم ما كسبتم ولا تسألون عما كانوا يعملون","aya_tafseer":"[134] تلك أُمَّة من أسلافكم قد مضَتْ، لهم أعمالهم، ولكم أعمالكم، ولا تُسْألون عن أعمالهم، وهم لا يُسْألون عن أعمالكم، وكلٌّ سيجازى بما فعله، لا يؤاخذ أحد بذنب أحد، ولا ينفع أحداً إلا إيمانُه وتقواه."},{"id":"142","jozz":"1","page":"21","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"1","line_end":"2","aya_no":"135","aya_text":"وَقَالُواْ كُونُواْ هُودًا أَوۡ نَصَٰرَىٰ تَهۡتَدُواْۗ قُلۡ بَلۡ مِلَّةَ إِبۡرَٰهِـۧمَ حَنِيفٗاۖ وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِينَ","aya_text_emlaey":"وقالوا كونوا هودا أو نصارى تهتدوا قل بل ملة إبراهيم حنيفا وما كان من المشركين","aya_tafseer":"[135] وقالت اليهود لأُمَّة محمد -صلى الله عليه وسلم-: ادخلوا في دين اليهودية تجدوا الهداية، وقالت النصارى لهم مثل ذلك. قل لهم -أيها الرسول-: بل الهداية أن نتبع -جميعاً- ملة إبراهيم، الذي مال عن كل دين باطل إلى دين الحق، وما كان من المشركين بالله تعالى."},{"id":"143","jozz":"1","page":"21","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"2","line_end":"5","aya_no":"136","aya_text":"قُولُوٓاْ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ إِلَيۡنَا وَمَآ أُنزِلَ إِلَىٰٓ إِبۡرَٰهِـۧمَ وَإِسۡمَٰعِيلَ وَإِسۡحَٰقَ وَيَعۡقُوبَ وَٱلۡأَسۡبَاطِ وَمَآ أُوتِيَ مُوسَىٰ وَعِيسَىٰ وَمَآ أُوتِيَ ٱلنَّبِيُّونَ مِن رَّبِّهِمۡ لَا نُفَرِّقُ بَيۡنَ أَحَدٖ مِّنۡهُمۡ وَنَحۡنُ لَهُۥ مُسۡلِمُونَ","aya_text_emlaey":"قولوا آمنا بالله وما أنـزل إلينا وما أنـزل إلى إبراهيم وإسماعيل وإسحاق ويعقوب والأسباط وما أوتي موسى وعيسى وما أوتي النبيون من ربهم لا نفرق بين أحد منهم ونحن له مسلمون","aya_tafseer":"[136] قولوا -أيها المؤمنون- لهؤلاء اليهود والنَّصارى: صدَّقنا بالله الواحد المعبود بحق، وبما أنزل إلينا من القرآن الذي أوحاه الله إلى نبيه ورسوله محمد -صلى الله عليه وسلم-، وما أنزل من الصحف إلى إبراهيم وابنيه إسماعيل وإسحاق، وإلى يعقوب، والأسباط -وهم الأنبياء مِن ولد يعقوب، الذين كانوا في قبائل بني إسرائيل الاثنتي عشرة- وما أُعطي موسى من التوراة، وعيسى من الإنجيل، وما أُعطي الأنبياء جميعاً من وحي ربهم، لا نفرق بين أحد منهم في الإيمان، ونحن خاضعون لله بالطاعة والعبادة."},{"id":"144","jozz":"1","page":"21","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"6","line_end":"7","aya_no":"137","aya_text":"فَإِنۡ ءَامَنُواْ بِمِثۡلِ مَآ ءَامَنتُم بِهِۦ فَقَدِ ٱهۡتَدَواْۖ وَّإِن تَوَلَّوۡاْ فَإِنَّمَا هُمۡ فِي شِقَاقٖۖ فَسَيَكۡفِيكَهُمُ ٱللَّهُۚ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ","aya_text_emlaey":"فإن آمنوا بمثل ما آمنتم به فقد اهتدوا وإن تولوا فإنما هم في شقاق فسيكفيكهم الله وهو السميع العليم","aya_tafseer":"[137] فإن آمن الكفار من اليهود والنصارى وغيرهم، بمثل الذي آمنتم به، مما جاء به الرسول، فقد اهتدوا إلى الحق، وإن أعرضوا فإنما هم في خلاف شديد، فسيكفيك الله -أيها الرسول- شرَّهم وينصرك عليهم، وهو السميع لأقوالكم، العليم بأحوالكم."},{"id":"145","jozz":"1","page":"21","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"8","line_end":"9","aya_no":"138","aya_text":"صِبۡغَةَ ٱللَّهِ وَمَنۡ أَحۡسَنُ مِنَ ٱللَّهِ صِبۡغَةٗۖ وَنَحۡنُ لَهُۥ عَٰبِدُونَ","aya_text_emlaey":"صبغة الله ومن أحسن من الله صبغة ونحن له عابدون","aya_tafseer":"[138] الزموا دين الله الذي فطركم عليه، فليس هناك أحسنُ مِن فطرة الله التي فطر الناس عليها، فالزموها، وقولوا: نحن له خاضعون مطيعون لربِّنا في اتباعنا ملَّة إبراهيم."},{"id":"146","jozz":"1","page":"21","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"9","line_end":"10","aya_no":"139","aya_text":"قُلۡ أَتُحَآجُّونَنَا فِي ٱللَّهِ وَهُوَ رَبُّنَا وَرَبُّكُمۡ وَلَنَآ أَعۡمَٰلُنَا وَلَكُمۡ أَعۡمَٰلُكُمۡ وَنَحۡنُ لَهُۥ مُخۡلِصُونَ","aya_text_emlaey":"قل أتحاجوننا في الله وهو ربنا وربكم ولنا أعمالنا ولكم أعمالكم ونحن له مخلصون","aya_tafseer":"[139] قل -أيها الرسول- لأهل الكتاب: أتجادلوننا في توحيد الله والإخلاص له، وهو رب العالمين جميعاً، لا يختص بقوم دون قوم، ولنا أعمالنا ولكم أعمالكم، ونحن لله مخلصو العبادة والطَّاعة لا نشرك به شيئاً، ولا نعبد أحداً غيره؟"},{"id":"147","jozz":"1","page":"21","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"11","line_end":"14","aya_no":"140","aya_text":"أَمۡ تَقُولُونَ إِنَّ إِبۡرَٰهِـۧمَ وَإِسۡمَٰعِيلَ وَإِسۡحَٰقَ وَيَعۡقُوبَ وَٱلۡأَسۡبَاطَ كَانُواْ هُودًا أَوۡ نَصَٰرَىٰۗ قُلۡ ءَأَنتُمۡ أَعۡلَمُ أَمِ ٱللَّهُۗ وَمَنۡ أَظۡلَمُ مِمَّن كَتَمَ شَهَٰدَةً عِندَهُۥ مِنَ ٱللَّهِۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعۡمَلُونَ","aya_text_emlaey":"أم تقولون إن إبراهيم وإسماعيل وإسحاق ويعقوب والأسباط كانوا هودا أو نصارى قل أأنتم أعلم أم الله ومن أظلم ممن كتم شهادة عنده من الله وما الله بغافل عما تعملون","aya_tafseer":"[140] بل أتقولون مجادلين في الله: إن إبراهيم وإسماعيل وإسحاق ويعقوب والأسباط -وهم الأنبياء من ولد يعقوب، الذين كانوا في قبائل بني إسرائيل الاثنتي عشرة- كانوا على دين اليهود أو النصارى؟ وهذا كذب؛ فقد بُعِثوا وماتوا قبل نزول التوراة والإنجيل . قل لهم -أيها الرسول-: أأنتم أعلم بدينهم أم الله تعالى؟ وقد أخبر في القرآن بأنهم كانوا حنفاء مسلمين، ولا أحد أظلم منكم حين تخفون شهادة ثابتة عندكم من الله تعالى، وتدَّعون خلافها افتراء على الله. وما الله بغافل عن شيء من أعمالكم، بل هو مُحْصٍ لها ومجازيكم عليها."},{"id":"148","jozz":"1","page":"21","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"14","line_end":"15","aya_no":"141","aya_text":"تِلۡكَ أُمَّةٞ قَدۡ خَلَتۡۖ لَهَا مَا كَسَبَتۡ وَلَكُم مَّا كَسَبۡتُمۡۖ وَلَا تُسۡـَٔلُونَ عَمَّا كَانُواْ يَعۡمَلُونَ","aya_text_emlaey":"تلك أمة قد خلت لها ما كسبت ولكم ما كسبتم ولا تسألون عما كانوا يعملون","aya_tafseer":"[141] تلك أُمَّة من أسلافكم قد مضَتْ، لهم أعمالهم ولكم أعمالكم، ولا تُسْألون عن أعمالهم، وهم لا يُسْألون عن أعمالكم. وفي الآية قطع للتعلق بالمخلوقين، وعدم الاغترار بالانتساب إليهم، وأن العبرة بالإيمان بالله وعبادته وحده، واتباع رسله، وأن من كفر برسول منهم فقد كفر بسائر الرسل."},{"id":"149","jozz":"2","page":"22","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"1","line_end":"3","aya_no":"142","aya_text":"۞ سَيَقُولُ ٱلسُّفَهَآءُ مِنَ ٱلنَّاسِ مَا وَلَّىٰهُمۡ عَن قِبۡلَتِهِمُ ٱلَّتِي كَانُواْ عَلَيۡهَاۚ قُل لِّلَّهِ ٱلۡمَشۡرِقُ وَٱلۡمَغۡرِبُۚ يَهۡدِي مَن يَشَآءُ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ","aya_text_emlaey":"سيقول السفهاء من الناس ما ولاهم عن قبلتهم التي كانوا عليها قل لله المشرق والمغرب يهدي من يشاء إلى صراط مستقيم","aya_tafseer":"[142] سيقول الجهال وضعاف العقول من اليهود وأمثالهم، في سخرية واعتراض: ما الذي صرف هؤلاء المسلمين عن قبلتهم التي كانوا يُصَلُّون إلى جهتها أول الإسلام؟ (وهي «بيت المقدس») قل لهم -أيها الرسول-: المشرق والمغرب وما بينهما ملك لله، فليست جهة من الجهات خارجة عن ملكه، يهدي مَن يشاء من عباده إلى طريق الهداية القويم. وفي هذا إشعار بأن الشأن كله لله في امتثال أوامره، فحيثما وَجَّهَنا توجَّهْنا."},{"id":"150","jozz":"2","page":"22","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"3","line_end":"8","aya_no":"143","aya_text":"وَكَذَٰلِكَ جَعَلۡنَٰكُمۡ أُمَّةٗ وَسَطٗا لِّتَكُونُواْ شُهَدَآءَ عَلَى ٱلنَّاسِ وَيَكُونَ ٱلرَّسُولُ عَلَيۡكُمۡ شَهِيدٗاۗ وَمَا جَعَلۡنَا ٱلۡقِبۡلَةَ ٱلَّتِي كُنتَ عَلَيۡهَآ إِلَّا لِنَعۡلَمَ مَن يَتَّبِعُ ٱلرَّسُولَ مِمَّن يَنقَلِبُ عَلَىٰ عَقِبَيۡهِۚ وَإِن كَانَتۡ لَكَبِيرَةً إِلَّا عَلَى ٱلَّذِينَ هَدَى ٱللَّهُۗ وَمَا كَانَ ٱللَّهُ لِيُضِيعَ إِيمَٰنَكُمۡۚ إِنَّ ٱللَّهَ بِٱلنَّاسِ لَرَءُوفٞ رَّحِيمٞ","aya_text_emlaey":"وكذلك جعلناكم أمة وسطا لتكونوا شهداء على الناس ويكون الرسول عليكم شهيدا وما جعلنا القبلة التي كنت عليها إلا لنعلم من يتبع الرسول ممن ينقلب على عقبيه وإن كانت لكبيرة إلا على الذين هدى الله وما كان الله ليضيع إيمانكم إن الله بالناس لرءوف رحيم","aya_tafseer":"[143] وكما هديناكم -أيها المسلمون- إلى الطريق الصحيح في الدين، جعلناكم أمة خياراً عدولاً؛ لتشهدوا على الأمم في الآخرة أن رسلهم بلَّغتهم رسالات ربهم، ويكون الرسول في الآخرة -كذلك- شهيداً عليكم أنَّه بَلَّغكم رسالة ربه. وما جعلنا -أيها الرسول- قبلة «بيت المقدس» التي كنت عليها، ثم صرفناك عنها إلى الكعبة ﺑ«مكة»، إلا ليظهر ما علمناه في الأزل، علماً يتعلق به الثواب والعقاب؛ لنميز مَن يتبعك ويطيعك ويستقبل معك حيث توجهت، ومَن هو ضعيف الإيمان فينقلب مرتدّاً عن دينه لشكِّه ونفاقه. وإن هذه الحال التي هي تحوُّل المسلم في صلاته من استقبال «بيت المقدس» إلى استقبال الكعبة، لثقيلة شاقة، إلا على الذين هداهم الله ومَنَّ عليهم بالإيمان والتقوى. وما كان الله ليضيع إيمانكم به واتِّباعكم لرسوله، ويبطل صلاتكم إلى القبلة السابقة. إنه سبحانه وتعالى ليرحم الناس رحمة واسعة في عاجلهم وآجلهم."},{"id":"151","jozz":"2","page":"22","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"8","line_end":"12","aya_no":"144","aya_text":"قَدۡ نَرَىٰ تَقَلُّبَ وَجۡهِكَ فِي ٱلسَّمَآءِۖ فَلَنُوَلِّيَنَّكَ قِبۡلَةٗ تَرۡضَىٰهَاۚ فَوَلِّ وَجۡهَكَ شَطۡرَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِۚ وَحَيۡثُ مَا كُنتُمۡ فَوَلُّواْ وُجُوهَكُمۡ شَطۡرَهُۥۗ وَإِنَّ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ لَيَعۡلَمُونَ أَنَّهُ ٱلۡحَقُّ مِن رَّبِّهِمۡۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا يَعۡمَلُونَ","aya_text_emlaey":"قد نرى تقلب وجهك في السماء فلنولينك قبلة ترضاها فول وجهك شطر المسجد الحرام وحيث ما كنتم فولوا وجوهكم شطره وإن الذين أوتوا الكتاب ليعلمون أنه الحق من ربهم وما الله بغافل عما يعملون","aya_tafseer":"[144] قد نرى تحوُّل وجهك -أيها الرسول- في جهة السماء، مرة بعد مرة؛ انتظاراً لنزول الوحي إليك في شأن القبلة، فلنصرفنك عن «بيت المقدس» إلى قبلة تحبها وترضاها، وهي وجهة المسجد الحرام ﺑ«مكة»، فولِّ وجهك إليها. وفي أي مكان كنتم -أيها المسلمون- وأردتم الصلاة فتوجهوا نحو المسجد الحرام. وإن الذين أعطاهم الله علم الكتاب من اليهود والنصارى لَيعلمون أن تحويلك إلى الكعبة هو الحق الثابت في كتبهم. وما الله بغافل عما يعمل هؤلاء المعترضون المشككون، وسيجازيهم على ذلك."},{"id":"152","jozz":"2","page":"22","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"12","line_end":"15","aya_no":"145","aya_text":"وَلَئِنۡ أَتَيۡتَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ بِكُلِّ ءَايَةٖ مَّا تَبِعُواْ قِبۡلَتَكَۚ وَمَآ أَنتَ بِتَابِعٖ قِبۡلَتَهُمۡۚ وَمَا بَعۡضُهُم بِتَابِعٖ قِبۡلَةَ بَعۡضٖۚ وَلَئِنِ ٱتَّبَعۡتَ أَهۡوَآءَهُم مِّنۢ بَعۡدِ مَا جَآءَكَ مِنَ ٱلۡعِلۡمِ إِنَّكَ إِذٗا لَّمِنَ ٱلظَّٰلِمِينَ","aya_text_emlaey":"ولئن أتيت الذين أوتوا الكتاب بكل آية ما تبعوا قبلتك وما أنت بتابع قبلتهم وما بعضهم بتابع قبلة بعض ولئن اتبعت أهواءهم من بعد ما جاءك من العلم إنك إذا لمن الظالمين","aya_tafseer":"[145] ولئن جئت -أيها الرسول- الذين أُعطوا التوراة والإنجيل بكل حجة وبرهان على أن توجُّهك إلى الكعبة في الصلاة هو الحق من عند الله، ما تبعوا قبلتك؛ عناداً واستكباراً، وما أنت بتابع قبلتهم مرة أخرى، وما بعضهم بتابع قبلة بعض. ولئن اتبعت أهواءهم في شأن القبلة وغيرها بعد ما جاءك من العلم بأنك على الحق وهم على الباطل، إنك حينئذ لمن الظالمين لأنفسهم. وهذا خطاب لجميع الأمة، وهو تهديد ووعيد لمن يتبع أهواء المخالفين لشريعة الإسلام."},{"id":"153","jozz":"2","page":"23","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"1","line_end":"2","aya_no":"146","aya_text":"ٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ يَعۡرِفُونَهُۥ كَمَا يَعۡرِفُونَ أَبۡنَآءَهُمۡۖ وَإِنَّ فَرِيقٗا مِّنۡهُمۡ لَيَكۡتُمُونَ ٱلۡحَقَّ وَهُمۡ يَعۡلَمُونَ","aya_text_emlaey":"الذين آتيناهم الكتاب يعرفونه كما يعرفون أبناءهم وإن فريقا منهم ليكتمون الحق وهم يعلمون","aya_tafseer":"[146] الذين أعطيناهم التوراة والإنجيل من أحبار اليهود وعلماء النصارى يعرفون أنَّ محمداً -صلى الله عليه وسلم- رسول الله بأوصافه المذكورة في كتبهم، مثل معرفتهم أبناءهم. وإن فريقاً منهم ليكتمون الحق وهم يعلمون صِدْقه، وثبوت أوصافه."},{"id":"154","jozz":"2","page":"23","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"2","line_end":"3","aya_no":"147","aya_text":"ٱلۡحَقُّ مِن رَّبِّكَ فَلَا تَكُونَنَّ مِنَ ٱلۡمُمۡتَرِينَ","aya_text_emlaey":"الحق من ربك فلا تكونن من الممترين","aya_tafseer":"[147] الذي أنزل إليك -أيها النبي- هو الحق من ربك، فلا تكوننَّ من الشاكين فيه. وهذا وإن كان خطاباً للرسول -صلى الله عليه وسلم-، فهو موجَّه للأمَّة."},{"id":"155","jozz":"2","page":"23","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"3","line_end":"5","aya_no":"148","aya_text":"وَلِكُلّٖ وِجۡهَةٌ هُوَ مُوَلِّيهَاۖ فَٱسۡتَبِقُواْ ٱلۡخَيۡرَٰتِۚ أَيۡنَ مَا تَكُونُواْ يَأۡتِ بِكُمُ ٱللَّهُ جَمِيعًاۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ","aya_text_emlaey":"ولكل وجهة هو موليها فاستبقوا الخيرات أين ما تكونوا يأت بكم الله جميعا إن الله على كل شيء قدير","aya_tafseer":"[148] ولكل أمة من الأمم قبلة يتوجَّه إليها كل واحد منها في صلاته، فبادروا -أيها المؤمنون- متسابقين إلى فِعْل الأعمال الصالحة التي شرعها الله لكم في دين الإسلام. وسيجمعكم الله جميعاً يوم القيامة من أي موضع كنتم فيه. إن الله على كل شيء قدير."},{"id":"156","jozz":"2","page":"23","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"5","line_end":"7","aya_no":"149","aya_text":"وَمِنۡ حَيۡثُ خَرَجۡتَ فَوَلِّ وَجۡهَكَ شَطۡرَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِۖ وَإِنَّهُۥ لَلۡحَقُّ مِن رَّبِّكَۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعۡمَلُونَ","aya_text_emlaey":"ومن حيث خرجت فول وجهك شطر المسجد الحرام وإنه للحق من ربك وما الله بغافل عما تعملون","aya_tafseer":"[149] ومن أي مكان خَرَجْتَ -أيها النبي- مسافراً، وأردت الصلاة، فوجِّه وجهك نحو المسجد الحرام. وإنَّ توجُّهك إليه لهو الحق الثابت من ربك. وما الله بغافل عما تعملونه، وسيجازيكم على ذلك."},{"id":"157","jozz":"2","page":"23","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"7","line_end":"11","aya_no":"150","aya_text":"وَمِنۡ حَيۡثُ خَرَجۡتَ فَوَلِّ وَجۡهَكَ شَطۡرَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِۚ وَحَيۡثُ مَا كُنتُمۡ فَوَلُّواْ وُجُوهَكُمۡ شَطۡرَهُۥ لِئَلَّا يَكُونَ لِلنَّاسِ عَلَيۡكُمۡ حُجَّةٌ إِلَّا ٱلَّذِينَ ظَلَمُواْ مِنۡهُمۡ فَلَا تَخۡشَوۡهُمۡ وَٱخۡشَوۡنِي وَلِأُتِمَّ نِعۡمَتِي عَلَيۡكُمۡ وَلَعَلَّكُمۡ تَهۡتَدُونَ","aya_text_emlaey":"ومن حيث خرجت فول وجهك شطر المسجد الحرام وحيث ما كنتم فولوا وجوهكم شطره لئلا يكون للناس عليكم حجة إلا الذين ظلموا منهم فلا تخشوهم واخشوني ولأتم نعمتي عليكم ولعلكم تهتدون","aya_tafseer":"[150] ومن أي مكان خرجت -أيها النبي- فتوجَّه إلى المسجد الحرام، وحيثما كنتم -أيها المسلمون-، بأي قطر من أقطار الأرض فولُّوا وجوهكم نحو المسجد الحرام؛ لكي لا يكون للناس المخالفين لكم احتجاج عليكم بالمخاصمة والمجادلة، بعد هذا التوجه إليه، إلا أهل الظلم والعناد منهم، فسيظلُّون على جدالهم، فلا تخافوهم وخافوني بامتثال أمري، واجتناب نهيي؛ ولكي أتمَّ نعمتي عليكم باختيار أكمل الشرائع لكم، ولعلكم تهتدون إلى الحق والصواب."},{"id":"158","jozz":"2","page":"23","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"11","line_end":"13","aya_no":"151","aya_text":"كَمَآ أَرۡسَلۡنَا فِيكُمۡ رَسُولٗا مِّنكُمۡ يَتۡلُواْ عَلَيۡكُمۡ ءَايَٰتِنَا وَيُزَكِّيكُمۡ وَيُعَلِّمُكُمُ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَيُعَلِّمُكُم مَّا لَمۡ تَكُونُواْ تَعۡلَمُونَ","aya_text_emlaey":"كما أرسلنا فيكم رسولا منكم يتلو عليكم آياتنا ويزكيكم ويعلمكم الكتاب والحكمة ويعلمكم ما لم تكونوا تعلمون","aya_tafseer":"[151] كما أنعمنا عليكم باستقبال الكعبة أرسلنا فيكم رسولاً منكم يتلو عليكم الآيات المبينة للحق من الباطل، ويطهرُكم من دنس الشرك وسوء الأخلاق، ويعلمكم الكتاب والسنة وأحكام الشريعة، ويعلمكم من أخبار الأنبياء، وقصص الأمم السابقة ما كنتم تجهلونه."},{"id":"159","jozz":"2","page":"23","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"13","line_end":"14","aya_no":"152","aya_text":"فَٱذۡكُرُونِيٓ أَذۡكُرۡكُمۡ وَٱشۡكُرُواْ لِي وَلَا تَكۡفُرُونِ","aya_text_emlaey":"فاذكروني أذكركم واشكروا لي ولا تكفرون","aya_tafseer":"[152] أمر تعالى المؤمنين بذكره، ووعد عليه أفضل الجزاء، وهو الثناء في الملأ الأعلى على مَن ذكره، وخُصُّوني -أيها المؤمنون- بالشكر قولاً وعملاً، ولا تجحدوا نعمي عليكم."},{"id":"160","jozz":"2","page":"23","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"14","line_end":"15","aya_no":"153","aya_text":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱسۡتَعِينُواْ بِٱلصَّبۡرِ وَٱلصَّلَوٰةِۚ إِنَّ ٱللَّهَ مَعَ ٱلصَّٰبِرِينَ","aya_text_emlaey":"ياأيها الذين آمنوا استعينوا بالصبر والصلاة إن الله مع الصابرين","aya_tafseer":"[153] يا أيها المؤمنون اطلبوا العون من الله في كل أموركم: بالصبر على النوائب والمصائب، وبالصبر على تركِ المعاصي والذنوب، وبالصبر على الطاعات والقربات، وبالصلاة التي تطمئن بها النفس، وتنهى عن الفحشاء والمنكر. إن الله مع الصابرين بعونه وتوفيقه وتسديده. وفي الآية إثبات معيَّة الله الخاصة بالمؤمنين، المقتضية لما سلف ذكره؛ أما المعية العامة، المقتضية للعلم والإحاطة فهي لجميع الخلق."},{"id":"161","jozz":"2","page":"24","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"1","line_end":"2","aya_no":"154","aya_text":"وَلَا تَقُولُواْ لِمَن يُقۡتَلُ فِي سَبِيلِ ٱللَّهِ أَمۡوَٰتُۢۚ بَلۡ أَحۡيَآءٞ وَلَٰكِن لَّا تَشۡعُرُونَ","aya_text_emlaey":"ولا تقولوا لمن يقتل في سبيل الله أموات بل أحياء ولكن لا تشعرون","aya_tafseer":"[154] ولا تقولوا -أيها المؤمنون- فيمن يُقتلون مجاهدين في سبيل الله: هم أموات؛ بل هم أحياء حياة خاصة بهم في قبورهم، لا يعلم كيفيتها إلا الله -تعالى-، ولكنكم لا تُحسُّون بها. وفي هذا دليل على نعيم القبر."},{"id":"162","jozz":"2","page":"24","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"2","line_end":"3","aya_no":"155","aya_text":"وَلَنَبۡلُوَنَّكُم بِشَيۡءٖ مِّنَ ٱلۡخَوۡفِ وَٱلۡجُوعِ وَنَقۡصٖ مِّنَ ٱلۡأَمۡوَٰلِ وَٱلۡأَنفُسِ وَٱلثَّمَرَٰتِۗ وَبَشِّرِ ٱلصَّٰبِرِينَ","aya_text_emlaey":"ولنبلونكم بشيء من الخوف والجوع ونقص من الأموال والأنفس والثمرات وبشر الصابرين","aya_tafseer":"[155] ولنختبرنكم بشيء يسير من الخوف، ومن الجوع، وبنقص من الأموال بتعسر الحصول عليها، أو ذهابها، ومن الأنفس: بالموت أو الشهادة في سبيل الله، وبنقص من ثمرات النخيل والأعناب والحبوب، بقلَّة ناتجها أو فسادها. وبشِّر -أيها النبي- الصابرين على هذا وأمثاله بما يفرحهم ويَسُرُّهم من حسن العاقبة في الدنيا والآخرة."},{"id":"163","jozz":"2","page":"24","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"4","line_end":"4","aya_no":"156","aya_text":"ٱلَّذِينَ إِذَآ أَصَٰبَتۡهُم مُّصِيبَةٞ قَالُوٓاْ إِنَّا لِلَّهِ وَإِنَّآ إِلَيۡهِ رَٰجِعُونَ","aya_text_emlaey":"الذين إذا أصابتهم مصيبة قالوا إنا لله وإنا إليه راجعون","aya_tafseer":"[156] من صفة هؤلاء الصابرين أنهم إذا أصابهم شيء يكرهونه قالوا: إنَّا عبيد مملوكون لله، مدبَّرون بأمره وتصريفه، يفعل بنا ما يشاء، وإنا إليه راجعون بالموت، ثم بالبعث للحساب والجزاء."},{"id":"164","jozz":"2","page":"24","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"5","line_end":"6","aya_no":"157","aya_text":"أُوْلَٰٓئِكَ عَلَيۡهِمۡ صَلَوَٰتٞ مِّن رَّبِّهِمۡ وَرَحۡمَةٞۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُهۡتَدُونَ","aya_text_emlaey":"أولئك عليهم صلوات من ربهم ورحمة وأولئك هم المهتدون","aya_tafseer":"[157] أولئك الصابرون لهم ثناء من ربهم ورحمة عظيمة منه سبحانه، وأولئك هم المهتدون إلى الرشاد."},{"id":"165","jozz":"2","page":"24","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"6","line_end":"8","aya_no":"158","aya_text":"۞ إِنَّ ٱلصَّفَا وَٱلۡمَرۡوَةَ مِن شَعَآئِرِ ٱللَّهِۖ فَمَنۡ حَجَّ ٱلۡبَيۡتَ أَوِ ٱعۡتَمَرَ فَلَا جُنَاحَ عَلَيۡهِ أَن يَطَّوَّفَ بِهِمَاۚ وَمَن تَطَوَّعَ خَيۡرٗا فَإِنَّ ٱللَّهَ شَاكِرٌ عَلِيمٌ","aya_text_emlaey":"إن الصفا والمروة من شعائر الله فمن حج البيت أو اعتمر فلا جناح عليه أن يطوف بهما ومن تطوع خيرا فإن الله شاكر عليم","aya_tafseer":"[158] إن الصفا والمروة -وهما جبلان صغيران قرب الكعبة من جهة الشرق- من معالم دين الله الظاهرة التي تعبَّد الله عباده بالسعي بينهما. فمَن قصد الكعبة حاجّاً أو معتمراً، فلا إثم عليه ولا حرج في أن يسعى بينهما، بل يجب عليه ذلك، ومن فعل الطاعات طواعية من نفسه، مخلصاً بها لله تعالى، فإن الله تعالى شاكر يثيب على القليل بالكثير، عليم بأعمال عباده فلا يضيعها، ولا يبخس أحداً مثقال ذرة."},{"id":"166","jozz":"2","page":"24","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"8","line_end":"10","aya_no":"159","aya_text":"إِنَّ ٱلَّذِينَ يَكۡتُمُونَ مَآ أَنزَلۡنَا مِنَ ٱلۡبَيِّنَٰتِ وَٱلۡهُدَىٰ مِنۢ بَعۡدِ مَا بَيَّنَّٰهُ لِلنَّاسِ فِي ٱلۡكِتَٰبِ أُوْلَٰٓئِكَ يَلۡعَنُهُمُ ٱللَّهُ وَيَلۡعَنُهُمُ ٱللَّٰعِنُونَ","aya_text_emlaey":"إن الذين يكتمون ما أنـزلنا من البينات والهدى من بعد ما بيناه للناس في الكتاب أولئك يلعنهم الله ويلعنهم اللاعنون","aya_tafseer":"[159] إن الذين يُخْفون ما أنزلنا من الآيات الواضحات الدالة على نبوة محمد -صلى الله عليه وسلم- وما جاء به، وهم أحبار اليهود وعلماء النصارى وغيرهم ممن يكتم ما أنزل الله من بعد ما أظهرناه للناس في التوراة والإنجيل، أولئك يطردهم الله من رحمته، ويدعو عليهم باللَّعنة جميعُ الخليقة."},{"id":"167","jozz":"2","page":"24","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"11","line_end":"12","aya_no":"160","aya_text":"إِلَّا ٱلَّذِينَ تَابُواْ وَأَصۡلَحُواْ وَبَيَّنُواْ فَأُوْلَٰٓئِكَ أَتُوبُ عَلَيۡهِمۡ وَأَنَا ٱلتَّوَّابُ ٱلرَّحِيمُ","aya_text_emlaey":"إلا الذين تابوا وأصلحوا وبينوا فأولئك أتوب عليهم وأنا التواب الرحيم","aya_tafseer":"[160] إلا الذين رجعوا مستغفرين الله من خطاياهم، وأصلحوا ما أفسدوه، وبَيَّنوا ما كتموه، فأولئك أقبل توبتهم وأجازيهم بالمغفرة، وأنا التواب على من تاب من عبادي، الرحيم بهم؛ إذْ وفقتُهم للتوبة وقبلتها منهم."},{"id":"168","jozz":"2","page":"24","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"12","line_end":"13","aya_no":"161","aya_text":"إِنَّ ٱلَّذِينَ كَفَرُواْ وَمَاتُواْ وَهُمۡ كُفَّارٌ أُوْلَٰٓئِكَ عَلَيۡهِمۡ لَعۡنَةُ ٱللَّهِ وَٱلۡمَلَٰٓئِكَةِ وَٱلنَّاسِ أَجۡمَعِينَ","aya_text_emlaey":"إن الذين كفروا وماتوا وهم كفار أولئك عليهم لعنة الله والملائكة والناس أجمعين","aya_tafseer":"[161] إن الذين جحدوا الإيمان وكتموا الحق، واستمروا على ذلك حتى ماتوا، أولئك عليهم لعنة الله بالطرد من رحمته، وعليهم لعنةُ الملائكةِ والناس أجمعين."},{"id":"169","jozz":"2","page":"24","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"14","line_end":"14","aya_no":"162","aya_text":"خَٰلِدِينَ فِيهَا لَا يُخَفَّفُ عَنۡهُمُ ٱلۡعَذَابُ وَلَا هُمۡ يُنظَرُونَ","aya_text_emlaey":"خالدين فيها لا يخفف عنهم العذاب ولا هم ينظرون","aya_tafseer":"[162] دائمين في اللعنة والنار، لا يخفف عنهم العذاب، ولا هم يُمْهَلون بمعذرة يعتذرون بها."},{"id":"170","jozz":"2","page":"24","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"15","line_end":"15","aya_no":"163","aya_text":"وَإِلَٰهُكُمۡ إِلَٰهٞ وَٰحِدٞۖ لَّآ إِلَٰهَ إِلَّا هُوَ ٱلرَّحۡمَٰنُ ٱلرَّحِيمُ","aya_text_emlaey":"وإلهكم إله واحد لا إله إلا هو الرحمن الرحيم","aya_tafseer":"[163] وإلهكم -أيها الناس- إله واحد متفرد في ذاته وأسمائه وصفاته وأفعاله، وعبودية خلقه له، لا معبود بحق إلا هو، الرحمن المتصف بالرحمة في ذاته وأفعاله لجميع الخلق، الرحيم بالمؤمنين."},{"id":"171","jozz":"2","page":"25","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"1","line_end":"5","aya_no":"164","aya_text":"إِنَّ فِي خَلۡقِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱخۡتِلَٰفِ ٱلَّيۡلِ وَٱلنَّهَارِ وَٱلۡفُلۡكِ ٱلَّتِي تَجۡرِي فِي ٱلۡبَحۡرِ بِمَا يَنفَعُ ٱلنَّاسَ وَمَآ أَنزَلَ ٱللَّهُ مِنَ ٱلسَّمَآءِ مِن مَّآءٖ فَأَحۡيَا بِهِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَا وَبَثَّ فِيهَا مِن كُلِّ دَآبَّةٖ وَتَصۡرِيفِ ٱلرِّيَٰحِ وَٱلسَّحَابِ ٱلۡمُسَخَّرِ بَيۡنَ ٱلسَّمَآءِ وَٱلۡأَرۡضِ لَأٓيَٰتٖ لِّقَوۡمٖ يَعۡقِلُونَ","aya_text_emlaey":"إن في خلق السموات والأرض واختلاف الليل والنهار والفلك التي تجري في البحر بما ينفع الناس وما أنـزل الله من السماء من ماء فأحيا به الأرض بعد موتها وبث فيها من كل دابة وتصريف الرياح والسحاب المسخر بين السماء والأرض لآيات لقوم يعقلون","aya_tafseer":"[164] إن في خلق السموات بارتفاعها واتساعها، والأرض بجبالها وسهولها وبحارها، وفي اختلاف الليل والنهار من الطول والقصر، والظلمة والنور، وتعاقبهما بأن يَخْلُف كل منهما الآخر، وفي السفن الجارية في البحار، التي تحمل ما ينفع الناس، وما أنزل الله من السماء من ماء المطر، فأحيا به الأرض، فصارت مخضرَّة ذات بهجة بعد أن كانت يابسة لا نبات فيها، وما نشره الله فيها من كل ما دبَّ على وجه الأرض، وما أنعم به عليكم من تقليب الرياح وتوجيهها، والسحاب المسيَّر بين السماء والأرض، إن في كل الدلائل السابقة لآياتٍ على وحدانية الله، وجليل نعمه، لقوم يعقلون مواضع الحجج، ويفهمون أدلته سبحانه على وحدانيته، واستحقاقه وحده للعبادة."},{"id":"172","jozz":"2","page":"25","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"5","line_end":"8","aya_no":"165","aya_text":"وَمِنَ ٱلنَّاسِ مَن يَتَّخِذُ مِن دُونِ ٱللَّهِ أَندَادٗا يُحِبُّونَهُمۡ كَحُبِّ ٱللَّهِۖ وَٱلَّذِينَ ءَامَنُوٓاْ أَشَدُّ حُبّٗا لِّلَّهِۗ وَلَوۡ يَرَى ٱلَّذِينَ ظَلَمُوٓاْ إِذۡ يَرَوۡنَ ٱلۡعَذَابَ أَنَّ ٱلۡقُوَّةَ لِلَّهِ جَمِيعٗا وَأَنَّ ٱللَّهَ شَدِيدُ ٱلۡعَذَابِ","aya_text_emlaey":"ومن الناس من يتخذ من دون الله أندادا يحبونهم كحب الله والذين آمنوا أشد حبا لله ولو يرى الذين ظلموا إذ يرون العذاب أن القوة لله جميعا وأن الله شديد العذاب","aya_tafseer":"[165] ومع هذه البراهين القاطعة يتخذ فريق من الناس من دون الله أصناماً وأوثاناً وأولياء يجعلونهم نظراء لله تعالى، ويعطونهم من المحبة والتعظيم والطاعة، ما لا يليق إلا بالله وحده. والمؤمنون أعظم حبّاً لله من حب هؤلاء الكفار لله ولآلهتهم؛ لأن المؤمنين أخلصوا المحبة كلها لله، وأولئك أشركوا في المحبة. ولو يعلم الذين ظلموا أنفسهم بالشرك في الحياة الدنيا، حين يشاهدون عذاب الآخرة، أن الله هو المتفرد بالقوة جميعاً، وأن الله شديد العذاب، لَمَا اتخذوا من دون الله آلهة يعبدونهم من دونه، ويتقربون بهم إليه."},{"id":"173","jozz":"2","page":"25","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"9","line_end":"10","aya_no":"166","aya_text":"إِذۡ تَبَرَّأَ ٱلَّذِينَ ٱتُّبِعُواْ مِنَ ٱلَّذِينَ ٱتَّبَعُواْ وَرَأَوُاْ ٱلۡعَذَابَ وَتَقَطَّعَتۡ بِهِمُ ٱلۡأَسۡبَابُ","aya_text_emlaey":"إذ تبرأ الذين اتبعوا من الذين اتبعوا ورأوا العذاب وتقطعت بهم الأسباب","aya_tafseer":"[166] عند معاينتهم عذاب الآخرة يتبرأ الرؤساء المتبوعون ممن اتبعهم على الشرك، وتنقطع بينهم كل الصلات التي ارتبطوا بها في الدنيا: من القرابة، والاتِّباع، والدين، وغير ذلك."},{"id":"174","jozz":"2","page":"25","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"10","line_end":"12","aya_no":"167","aya_text":"وَقَالَ ٱلَّذِينَ ٱتَّبَعُواْ لَوۡ أَنَّ لَنَا كَرَّةٗ فَنَتَبَرَّأَ مِنۡهُمۡ كَمَا تَبَرَّءُواْ مِنَّاۗ كَذَٰلِكَ يُرِيهِمُ ٱللَّهُ أَعۡمَٰلَهُمۡ حَسَرَٰتٍ عَلَيۡهِمۡۖ وَمَا هُم بِخَٰرِجِينَ مِنَ ٱلنَّارِ","aya_text_emlaey":"وقال الذين اتبعوا لو أن لنا كرة فنتبرأ منهم كما تبرءوا منا كذلك يريهم الله أعمالهم حسرات عليهم وما هم بخارجين من النار","aya_tafseer":"[167] وقال التابعون: يا ليت لنا عودة إلى الدنيا، فنعلن براءتنا من هؤلاء الرؤساء، كما أعلنوا براءتهم مِنَّا. وكما أراهم الله شدة عذابه يوم القيامة يريهم أعمالهم الباطلة ندامات عليهم، وليسوا بخارجين من النار أبداً."},{"id":"175","jozz":"2","page":"25","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"13","line_end":"14","aya_no":"168","aya_text":"يَٰٓأَيُّهَا ٱلنَّاسُ كُلُواْ مِمَّا فِي ٱلۡأَرۡضِ حَلَٰلٗا طَيِّبٗا وَلَا تَتَّبِعُواْ خُطُوَٰتِ ٱلشَّيۡطَٰنِۚ إِنَّهُۥ لَكُمۡ عَدُوّٞ مُّبِينٌ","aya_text_emlaey":"ياأيها الناس كلوا مما في الأرض حلالا طيبا ولا تتبعوا خطوات الشيطان إنه لكم عدو مبين","aya_tafseer":"[168] يا أيها الناس كلوا من رزق الله الذي أباحه لكم في الأرض، وهو الطاهر غير النجس، النافع غير الضار، ولا تتبعوا طرق الشيطان في التحليل والتحريم، والبدع والمعاصي. إنه عدو لكم ظاهر العداوة."},{"id":"176","jozz":"2","page":"25","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"14","line_end":"15","aya_no":"169","aya_text":"إِنَّمَا يَأۡمُرُكُم بِٱلسُّوٓءِ وَٱلۡفَحۡشَآءِ وَأَن تَقُولُواْ عَلَى ٱللَّهِ مَا لَا تَعۡلَمُونَ","aya_text_emlaey":"إنما يأمركم بالسوء والفحشاء وأن تقولوا على الله ما لا تعلمون","aya_tafseer":"[169] إنما يأمركم الشيطان بكل ذنب قبيح يسوءُكم، وبكل معصية بالغة القبح، وبأن تفتروا على الله الكذب من تحريم الحلال وغيره بدون علم."},{"id":"177","jozz":"2","page":"26","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"1","line_end":"3","aya_no":"170","aya_text":"وَإِذَا قِيلَ لَهُمُ ٱتَّبِعُواْ مَآ أَنزَلَ ٱللَّهُ قَالُواْ بَلۡ نَتَّبِعُ مَآ أَلۡفَيۡنَا عَلَيۡهِ ءَابَآءَنَآۚ أَوَلَوۡ كَانَ ءَابَآؤُهُمۡ لَا يَعۡقِلُونَ شَيۡـٔٗا وَلَا يَهۡتَدُونَ","aya_text_emlaey":"وإذا قيل لهم اتبعوا ما أنـزل الله قالوا بل نتبع ما ألفينا عليه آباءنا أو لو كان آباؤهم لا يعقلون شيئا ولا يهتدون","aya_tafseer":"[170] وإذا قال المؤمنون ناصحين أهل الضلال: اتبعوا ما أنزل الله من القرآن والهدى، أصرُّوا على تقليد أسلافهم المشركين قائلين: لا نتبع دينكم، بل نتبع ما وجدنا عليه آباءنا. أيتبعون آباءهم ولو كانوا لا يعقلون عن الله شيئاً، ولا يدركون رشداً؟"},{"id":"178","jozz":"2","page":"26","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"3","line_end":"4","aya_no":"171","aya_text":"وَمَثَلُ ٱلَّذِينَ كَفَرُواْ كَمَثَلِ ٱلَّذِي يَنۡعِقُ بِمَا لَا يَسۡمَعُ إِلَّا دُعَآءٗ وَنِدَآءٗۚ صُمُّۢ بُكۡمٌ عُمۡيٞ فَهُمۡ لَا يَعۡقِلُونَ","aya_text_emlaey":"ومثل الذين كفروا كمثل الذي ينعق بما لا يسمع إلا دعاء ونداء صم بكم عمي فهم لا يعقلون","aya_tafseer":"[171] وصفة الذين كفروا وداعيهم إلى الهدى والإيمان كصفة الراعي الذي يصيح بالبهائم ويزجرها، وهي لا تفهم معانيَ كلامه، وإنما تسمع النداء ودَوِيَّ الصوت فقط. هؤلاء الكفار صُمٌّ سَدُّوا أسماعهم عن الحق، بُكْم أخرسوا ألسنتهم عن النطق به، عُمْي لا ترى أعينهم براهينه الباهرة، فهم لا يُعملون عقولهم فيما ينفعهم."},{"id":"179","jozz":"2","page":"26","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"5","line_end":"6","aya_no":"172","aya_text":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُلُواْ مِن طَيِّبَٰتِ مَا رَزَقۡنَٰكُمۡ وَٱشۡكُرُواْ لِلَّهِ إِن كُنتُمۡ إِيَّاهُ تَعۡبُدُونَ","aya_text_emlaey":"ياأيها الذين آمنوا كلوا من طيبات ما رزقناكم واشكروا لله إن كنتم إياه تعبدون","aya_tafseer":"[172] يا أيها المؤمنون كلوا من الأطعمة المستلَذَّة الحلال التي رزقناكم، ولا تكونوا كالكفار الذين يحرِّمون الطيبات، ويستحِلُّون الخبائث، واشكروا لله نعمه العظيمة عليكم بقلوبكم وألسنتكم وجوارحكم، إن كنتم حقّاً منقادين لأمره، سامعين مطيعين له، تعبدونه وحده لا شريك له."},{"id":"180","jozz":"2","page":"26","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"6","line_end":"9","aya_no":"173","aya_text":"إِنَّمَا حَرَّمَ عَلَيۡكُمُ ٱلۡمَيۡتَةَ وَٱلدَّمَ وَلَحۡمَ ٱلۡخِنزِيرِ وَمَآ أُهِلَّ بِهِۦ لِغَيۡرِ ٱللَّهِۖ فَمَنِ ٱضۡطُرَّ غَيۡرَ بَاغٖ وَلَا عَادٖ فَلَآ إِثۡمَ عَلَيۡهِۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٌ","aya_text_emlaey":"إنما حرم عليكم الميتة والدم ولحم الخنـزير وما أهل به لغير الله فمن اضطر غير باغ ولا عاد فلا إثم عليه إن الله غفور رحيم","aya_tafseer":"[173] إنما حَرَّم الله عليكم ما يضركم كالميتة التي لم تذبح بطريقة شرعية، والدم المسفوح، ولحم الخنزير، والذبائح التي ذبحت لغير الله. ومِن فَضْلِ الله عليكم وتيسيره أنه أباح لكم أكل هذه المحرمات عند الضرورة. فمن ألجأته الضرورة إلى أكل شيء منها، غير ظالم في أكله فوق حاجته، ولا متجاوز حدود الله فيما أُبيح له، فلا ذنب عليه في ذلك. إن الله غفور لعباده، رحيم بهم."},{"id":"181","jozz":"2","page":"26","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"9","line_end":"12","aya_no":"174","aya_text":"إِنَّ ٱلَّذِينَ يَكۡتُمُونَ مَآ أَنزَلَ ٱللَّهُ مِنَ ٱلۡكِتَٰبِ وَيَشۡتَرُونَ بِهِۦ ثَمَنٗا قَلِيلًا أُوْلَٰٓئِكَ مَا يَأۡكُلُونَ فِي بُطُونِهِمۡ إِلَّا ٱلنَّارَ وَلَا يُكَلِّمُهُمُ ٱللَّهُ يَوۡمَ ٱلۡقِيَٰمَةِ وَلَا يُزَكِّيهِمۡ وَلَهُمۡ عَذَابٌ أَلِيمٌ","aya_text_emlaey":"إن الذين يكتمون ما أنـزل الله من الكتاب ويشترون به ثمنا قليلا أولئك ما يأكلون في بطونهم إلا النار ولا يكلمهم الله يوم القيامة ولا يزكيهم ولهم عذاب أليم","aya_tafseer":"[174] إن الذين يُخْفون ما أنزل الله في كتبه من صفة محمد -صلى الله عليه وسلم- وغير ذلك من الحق، ويحرصون على أخذ عوض قليل من عرض الحياة الدنيا مقابل هذا الإخفاء، هؤلاء ما يأكلون في مقابلة كتمان الحق إلا نارَ جهنم تتأجج في بطونهم ، ولا يكلمهم الله يوم القيامة لغضبه وسخطه عليهم، ولا يطهرهم مِن دنس ذنوبهم وكفرهم، ولهم عذاب موجع."},{"id":"182","jozz":"2","page":"26","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"12","line_end":"14","aya_no":"175","aya_text":"أُوْلَٰٓئِكَ ٱلَّذِينَ ٱشۡتَرَوُاْ ٱلضَّلَٰلَةَ بِٱلۡهُدَىٰ وَٱلۡعَذَابَ بِٱلۡمَغۡفِرَةِۚ فَمَآ أَصۡبَرَهُمۡ عَلَى ٱلنَّارِ","aya_text_emlaey":"أولئك الذين اشتروا الضلالة بالهدى والعذاب بالمغفرة فما أصبرهم على النار","aya_tafseer":"[175] أولئك المتصفون بهذه الصفات استبدلوا الضلالة بالهدى وعذاب الله بمغفرته، فما أشد جراءتهم على النار بعملهم أعمال أهل النار! يعجب الله من إقدامهم على ذلك، فاعجبوا -أيها الناس- من جراءتهم، ومن صبرهم على النار ومكثهم فيها. وهذا على وجه الاستهانة، بهم والاستخفاف بأمرهم."},{"id":"183","jozz":"2","page":"26","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"14","line_end":"15","aya_no":"176","aya_text":"ذَٰلِكَ بِأَنَّ ٱللَّهَ نَزَّلَ ٱلۡكِتَٰبَ بِٱلۡحَقِّۗ وَإِنَّ ٱلَّذِينَ ٱخۡتَلَفُواْ فِي ٱلۡكِتَٰبِ لَفِي شِقَاقِۭ بَعِيدٖ","aya_text_emlaey":"ذلك بأن الله نـزل الكتاب بالحق وإن الذين اختلفوا في الكتاب لفي شقاق بعيد","aya_tafseer":"[176] ذلك العذاب الذي استحقوه بسبب أن الله تعالى نَزَّل كتبه على رسله مشتملة على الحق المبين، فكفروا به. وإن الذين اختلفوا في الكتاب فآمنوا ببعضه وكفروا ببعضه، لفي منازعة ومفارقة بعيدة عن الرشد والصواب."},{"id":"184","jozz":"2","page":"27","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"1","line_end":"7","aya_no":"177","aya_text":"۞ لَّيۡسَ ٱلۡبِرَّ أَن تُوَلُّواْ وُجُوهَكُمۡ قِبَلَ ٱلۡمَشۡرِقِ وَٱلۡمَغۡرِبِ وَلَٰكِنَّ ٱلۡبِرَّ مَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَٱلۡمَلَٰٓئِكَةِ وَٱلۡكِتَٰبِ وَٱلنَّبِيِّـۧنَ وَءَاتَى ٱلۡمَالَ عَلَىٰ حُبِّهِۦ ذَوِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينَ وَٱبۡنَ ٱلسَّبِيلِ وَٱلسَّآئِلِينَ وَفِي ٱلرِّقَابِ وَأَقَامَ ٱلصَّلَوٰةَ وَءَاتَى ٱلزَّكَوٰةَ وَٱلۡمُوفُونَ بِعَهۡدِهِمۡ إِذَا عَٰهَدُواْۖ وَٱلصَّٰبِرِينَ فِي ٱلۡبَأۡسَآءِ وَٱلضَّرَّآءِ وَحِينَ ٱلۡبَأۡسِۗ أُوْلَٰٓئِكَ ٱلَّذِينَ صَدَقُواْۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُتَّقُونَ","aya_text_emlaey":"ليس البر أن تولوا وجوهكم قبل المشرق والمغرب ولكن البر من آمن بالله واليوم الآخر والملائكة والكتاب والنبيين وآتى المال على حبه ذوي القربى واليتامى والمساكين وابن السبيل والسائلين وفي الرقاب وأقام الصلاة وآتى الزكاة والموفون بعهدهم إذا عاهدوا والصابرين في البأساء والضراء وحين البأس أولئك الذين صدقوا وأولئك هم المتقون","aya_tafseer":"[177] ليس الخير عند الله -تعالى- في التوجه في الصلاة إلى جهة المشرق والمغرب إن لم يكن عن أمر الله وشرعه، وإنما الخير كلُّ الخير هو إيمان من آمن بالله وصدَّق به معبوداً وحده لا شريك له، وآمن بيوم البعث والجزاء، وبالملائكة جميعاً، وبالكتب المنزلة كافة، وبجميع النبيين من غير تفريق، وأعطى المال تطوُّعاً- مع شدة حبه- ذوي القربى، واليتامى المحتاجين الذين مات آباؤهم وهم دون سن البلوغ، والمساكين الذين لا يملكون ما يكفيهم ويسدُّ حاجتهم، والمسافرين المحتاجين الذين بَعُدوا عن أهلهم ومالهم، والسائلين الذين اضطروا إلى السؤال لشدة حاجتهم، وأنفق في تحرير الرقيق والأسرى، وأقام الصلاة، وأدى الزكاة المفروضة، والذين يوفون بالعهود، ومن صبر في حال فقره ومرضه، وفي شدة القتال. أولئك المتصفون بهذه الصفات هم الذين صدقوا في إيمانهم، وأولئك هم الذين اتقَوا عقاب الله فتجنبوا معاصيه."},{"id":"185","jozz":"2","page":"27","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"7","line_end":"11","aya_no":"178","aya_text":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُتِبَ عَلَيۡكُمُ ٱلۡقِصَاصُ فِي ٱلۡقَتۡلَىۖ ٱلۡحُرُّ بِٱلۡحُرِّ وَٱلۡعَبۡدُ بِٱلۡعَبۡدِ وَٱلۡأُنثَىٰ بِٱلۡأُنثَىٰۚ فَمَنۡ عُفِيَ لَهُۥ مِنۡ أَخِيهِ شَيۡءٞ فَٱتِّبَاعُۢ بِٱلۡمَعۡرُوفِ وَأَدَآءٌ إِلَيۡهِ بِإِحۡسَٰنٖۗ ذَٰلِكَ تَخۡفِيفٞ مِّن رَّبِّكُمۡ وَرَحۡمَةٞۗ فَمَنِ ٱعۡتَدَىٰ بَعۡدَ ذَٰلِكَ فَلَهُۥ عَذَابٌ أَلِيمٞ","aya_text_emlaey":"ياأيها الذين آمنوا كتب عليكم القصاص في القتلى الحر بالحر والعبد بالعبد والأنثى بالأنثى فمن عفي له من أخيه شيء فاتباع بالمعروف وأداء إليه بإحسان ذلك تخفيف من ربكم ورحمة فمن اعتدى بعد ذلك فله عذاب أليم","aya_tafseer":"[178] يا أيها الذين صَدَّقوا الله ورسوله وعملوا بشرعه فرض الله عليكم أن تقتصوا من القاتل عمداً بقتله، بشرط المساواة والمماثلة: يُقتل الحر بمثله سواء الرجلُ بالمرأة أو المرأةُ بالرجل، والعبد بمثله، والأنثى بمثلها. فمن سامحه وليُّ المقتول بالعفو عن الاقتصاص منه والاكتفاء بأخذ الدية -وهي قدر مالي محدد يدفعه الجاني مقابل العفو عنه- فليلتزم الطرفان بحسن الخلق، فيطالب الولي بالدية من غير عنف، ويدفع القاتل إليه حقه بإحسان، مِن غير تأخير ولا نقص. ذلك العفو مع أخذ الدية تخفيف من ربكم ورحمة بكم؛ لما فيه من التسهيل والانتفاع. فمَن قتل القاتل بعد العفو عنه وأَخْذِ الدية فله عذاب أليم بقتله قصاصاً في الدنيا، أو بالنار في الآخرة."},{"id":"186","jozz":"2","page":"27","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"11","line_end":"12","aya_no":"179","aya_text":"وَلَكُمۡ فِي ٱلۡقِصَاصِ حَيَوٰةٞ يَٰٓأُوْلِي ٱلۡأَلۡبَٰبِ لَعَلَّكُمۡ تَتَّقُونَ","aya_text_emlaey":"ولكم في القصاص حياة ياأولي الألباب لعلكم تتقون","aya_tafseer":"[179] ولكم في تشريع القصاص وتنفيذه حياة آمنة -يا أصحاب العقول السليمة-؛ رجاء تقوى الله وخشيته بطاعته دائماً."},{"id":"187","jozz":"2","page":"27","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"12","line_end":"14","aya_no":"180","aya_text":"كُتِبَ عَلَيۡكُمۡ إِذَا حَضَرَ أَحَدَكُمُ ٱلۡمَوۡتُ إِن تَرَكَ خَيۡرًا ٱلۡوَصِيَّةُ لِلۡوَٰلِدَيۡنِ وَٱلۡأَقۡرَبِينَ بِٱلۡمَعۡرُوفِۖ حَقًّا عَلَى ٱلۡمُتَّقِينَ","aya_text_emlaey":"كتب عليكم إذا حضر أحدكم الموت إن ترك خيرا الوصية للوالدين والأقربين بالمعروف حقا على المتقين","aya_tafseer":"[180] فرض الله عليكم إذا حضر أحدَكم علاماتُ الموت ومقدماتُه -إن ترك مالاً- الوصية بجزء من ماله للوالدين والأقربين مع مراعاة العدل؛ فلا يدع الفقير ويوصي للغني، ولا يتجاوز الثلث، وذلك حق ثابت يعمل به أهل التقوى الذين يخافون الله. وكان هذا قبل نزول آيات المواريث التي حَدَّد الله فيها نصيب كل وارث."},{"id":"188","jozz":"2","page":"27","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"14","line_end":"15","aya_no":"181","aya_text":"فَمَنۢ بَدَّلَهُۥ بَعۡدَ مَا سَمِعَهُۥ فَإِنَّمَآ إِثۡمُهُۥ عَلَى ٱلَّذِينَ يُبَدِّلُونَهُۥٓۚ إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٞ","aya_text_emlaey":"فمن بدله بعد ما سمعه فإنما إثمه على الذين يبدلونه إن الله سميع عليم","aya_tafseer":"[181] فمَن غَيَّر وصية الميت بعدما سمعها منه قبل موته، فإنما الذنب على مَن غيَّر وبَدَّل. إن الله سميع لوصيتكم وأقوالكم، عليم بما تخفيه صدوركم من الميل إلى الحق والعدل أو الجَوْرِ والحَيْفِ، وسيجازيكم على ذلك."},{"id":"189","jozz":"2","page":"28","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"1","line_end":"2","aya_no":"182","aya_text":"فَمَنۡ خَافَ مِن مُّوصٖ جَنَفًا أَوۡ إِثۡمٗا فَأَصۡلَحَ بَيۡنَهُمۡ فَلَآ إِثۡمَ عَلَيۡهِۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ","aya_text_emlaey":"فمن خاف من موص جنفا أو إثما فأصلح بينهم فلا إثم عليه إن الله غفور رحيم","aya_tafseer":"[182] فمَن علم مِن موصٍ ميلاً عن الحق في وصيته على سبيل الخطأ أو العمد، فنصح الموصيَ وقت الوصية بما هو الأعدل، فإن لم يحصل له ذلك فأصلح بين الأطراف بتغيير الوصية؛ لتوافق الشريعة، فلا ذنب عليه في هذا الإصلاح. إن الله غفور لعباده، رحيم بهم."},{"id":"190","jozz":"2","page":"28","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"2","line_end":"4","aya_no":"183","aya_text":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُتِبَ عَلَيۡكُمُ ٱلصِّيَامُ كَمَا كُتِبَ عَلَى ٱلَّذِينَ مِن قَبۡلِكُمۡ لَعَلَّكُمۡ تَتَّقُونَ","aya_text_emlaey":"ياأيها الذين آمنوا كتب عليكم الصيام كما كتب على الذين من قبلكم لعلكم تتقون","aya_tafseer":"[183] يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، فرض الله عليكم الصيام كما فرضه على الأمم قبلكم؛ لعلكم تتقون ربكم، فتجعلون بينكم وبين المعاصي وقاية بطاعته وعبادته وحده."},{"id":"191","jozz":"2","page":"28","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"4","line_end":"7","aya_no":"184","aya_text":"أَيَّامٗا مَّعۡدُودَٰتٖۚ فَمَن كَانَ مِنكُم مَّرِيضًا أَوۡ عَلَىٰ سَفَرٖ فَعِدَّةٞ مِّنۡ أَيَّامٍ أُخَرَۚ وَعَلَى ٱلَّذِينَ يُطِيقُونَهُۥ فِدۡيَةٞ طَعَامُ مِسۡكِينٖۖ فَمَن تَطَوَّعَ خَيۡرٗا فَهُوَ خَيۡرٞ لَّهُۥۚ وَأَن تَصُومُواْ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ","aya_text_emlaey":"أياما معدودات فمن كان منكم مريضا أو على سفر فعدة من أيام أخر وعلى الذين يطيقونه فدية طعام مسكين فمن تطوع خيرا فهو خير له وأن تصوموا خير لكم إن كنتم تعلمون","aya_tafseer":"[184] فرض الله عليكم صيام أيام معلومة العدد وهي أيام شهر رمضان. فمن كان منكم مريضاً يشق عليه الصوم، أو مسافراً فله أن يفطر، وعليه صيام عدد من أيام أُخَر بقدر التي أفطر فيها. وعلى الذين يتكلفون الصيام ويشقُّ عليهم مشقة غير محتملة كالشيخ الكبير، والمريض الذي لا يُرْجَى شفاؤه، فدية عن كل يوم يفطره، وهي طعام محتاجٍ لا يملك ما يكفيه ويسدُّ حاجته، فمن زاد في قدر الفدية تبرعاً منه فهو خير له، وصيامكم خير لكم من إعطاء الفدية، إن كنتم تعلمون الفضل العظيم للصوم عند الله تعالى."},{"id":"192","jozz":"2","page":"28","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"8","line_end":"13","aya_no":"185","aya_text":"شَهۡرُ رَمَضَانَ ٱلَّذِيٓ أُنزِلَ فِيهِ ٱلۡقُرۡءَانُ هُدٗى لِّلنَّاسِ وَبَيِّنَٰتٖ مِّنَ ٱلۡهُدَىٰ وَٱلۡفُرۡقَانِۚ فَمَن شَهِدَ مِنكُمُ ٱلشَّهۡرَ فَلۡيَصُمۡهُۖ وَمَن كَانَ مَرِيضًا أَوۡ عَلَىٰ سَفَرٖ فَعِدَّةٞ مِّنۡ أَيَّامٍ أُخَرَۗ يُرِيدُ ٱللَّهُ بِكُمُ ٱلۡيُسۡرَ وَلَا يُرِيدُ بِكُمُ ٱلۡعُسۡرَ وَلِتُكۡمِلُواْ ٱلۡعِدَّةَ وَلِتُكَبِّرُواْ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمۡ وَلَعَلَّكُمۡ تَشۡكُرُونَ","aya_text_emlaey":"شهر رمضان الذي أنـزل فيه القرآن هدى للناس وبينات من الهدى والفرقان فمن شهد منكم الشهر فليصمه ومن كان مريضا أو على سفر فعدة من أيام أخر يريد الله بكم اليسر ولا يريد بكم العسر ولتكملوا العدة ولتكبروا الله على ما هداكم ولعلكم تشكرون","aya_tafseer":"[185] شهر رمضان الذي ابتدأ الله فيه إنزال القرآن في ليلة القدر؛ هداية للناس إلى الحق، فيه أوضح الدلائل على هدى الله، وعلى الفارق بين الحق والباطل. فمن حضر منكم الشهر وكان صحيحاً مقيماً فليصم نهاره. ويُرخَّص للمريض والمسافر في الفطر، ثم يقضيان عدد تلك الأيام. يريد الله تعالى بكم اليسر والسهولة في شرائعه، ولا يريد بكم العسر والمشقة، ولتكملوا عدة الصيام شهراً، ولتختموا الصيام بتكبير الله في عيد الفطر، ولتعظموه على هدايته لكم، ولكي تشكروا له على ما أنعم به عليكم من الهداية والتوفيق والتيسير."},{"id":"193","jozz":"2","page":"28","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"13","line_end":"15","aya_no":"186","aya_text":"وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌۖ أُجِيبُ دَعۡوَةَ ٱلدَّاعِ إِذَا دَعَانِۖ فَلۡيَسۡتَجِيبُواْ لِي وَلۡيُؤۡمِنُواْ بِي لَعَلَّهُمۡ يَرۡشُدُونَ","aya_text_emlaey":"وإذا سألك عبادي عني فإني قريب أجيب دعوة الداع إذا دعان فليستجيبوا لي وليؤمنوا بي لعلهم يرشدون","aya_tafseer":"[186] وإذا سألك -أيها النبي- عبادي عني فقل لهم: إني قريب منهم، أُجيب دعوة الداعي إذا دعاني، فليطيعوني فيما أمرتهم به ونهيتهم عنه، وليؤمنوا بي، لعلهم يهتدون إلى مصالح دينهم ودنياهم. وفي هذه الآية إخبار منه سبحانه عن قربه من عباده، القرب اللائق بجلاله."},{"id":"194","jozz":"2","page":"29","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"1","line_end":"8","aya_no":"187","aya_text":"أُحِلَّ لَكُمۡ لَيۡلَةَ ٱلصِّيَامِ ٱلرَّفَثُ إِلَىٰ نِسَآئِكُمۡۚ هُنَّ لِبَاسٞ لَّكُمۡ وَأَنتُمۡ لِبَاسٞ لَّهُنَّۗ عَلِمَ ٱللَّهُ أَنَّكُمۡ كُنتُمۡ تَخۡتَانُونَ أَنفُسَكُمۡ فَتَابَ عَلَيۡكُمۡ وَعَفَا عَنكُمۡۖ فَٱلۡـَٰٔنَ بَٰشِرُوهُنَّ وَٱبۡتَغُواْ مَا كَتَبَ ٱللَّهُ لَكُمۡۚ وَكُلُواْ وَٱشۡرَبُواْ حَتَّىٰ يَتَبَيَّنَ لَكُمُ ٱلۡخَيۡطُ ٱلۡأَبۡيَضُ مِنَ ٱلۡخَيۡطِ ٱلۡأَسۡوَدِ مِنَ ٱلۡفَجۡرِۖ ثُمَّ أَتِمُّواْ ٱلصِّيَامَ إِلَى ٱلَّيۡلِۚ وَلَا تُبَٰشِرُوهُنَّ وَأَنتُمۡ عَٰكِفُونَ فِي ٱلۡمَسَٰجِدِۗ تِلۡكَ حُدُودُ ٱللَّهِ فَلَا تَقۡرَبُوهَاۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ ءَايَٰتِهِۦ لِلنَّاسِ لَعَلَّهُمۡ يَتَّقُونَ","aya_text_emlaey":"أحل لكم ليلة الصيام الرفث إلى نسائكم هن لباس لكم وأنتم لباس لهن علم الله أنكم كنتم تختانون أنفسكم فتاب عليكم وعفا عنكم فالآن باشروهن وابتغوا ما كتب الله لكم وكلوا واشربوا حتى يتبين لكم الخيط الأبيض من الخيط الأسود من الفجر ثم أتموا الصيام إلى الليل ولا تباشروهن وأنتم عاكفون في المساجد تلك حدود الله فلا تقربوها كذلك يبين الله آياته للناس لعلهم يتقون","aya_tafseer":"[187] أباح الله لكم في ليالي شهر رمضان جماعَ نسائكم، هنَّ ستر وحفظ لكم، وأنتم ستر وحفظ لهن. علم الله أنكم كنتم تخونون أنفسكم؛ بمخالفة ما حَرَّمه الله عليكم من مجامعة النساء بعد العشاء في ليالي الصيام -وكان ذلك في أول الإسلام-، فتاب الله عليكم ووسَّع لكم في الأمر، فالآن جامعوهن، واطلبوا ما قدَّره الله لكم من الأولاد، وكلوا واشربوا حتى يتبيَّن لكم ضياء الصباح من سواد الليل؛ بظهور الفجر الصادق، ثم أتمُّوا الصيام بالإمساك عن المفطرات إلى دخول الليل بغروب الشمس. ولا تجامعوا نساءكم أو تتعاطوا ما يفضي إلى جماعهنَّ إذا كنتم معتكفين في المساجد؛ لأن هذا يفسد الاعتكاف (وهو الإقامة في المسجد مدة معلومة بنيَّة التقرب إلى الله تعالى). تلك الأحكام التي شرعها الله لكم هي حدوده الفاصلة بين الحلال والحرام، فلا تقربوها حتى لا تقعوا في الحرام. بمثل هذا البيان الواضح يبين الله آياته وأحكامه للناس؛ كي يتقوه ويخشَوْه."},{"id":"195","jozz":"2","page":"29","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"8","line_end":"10","aya_no":"188","aya_text":"وَلَا تَأۡكُلُوٓاْ أَمۡوَٰلَكُم بَيۡنَكُم بِٱلۡبَٰطِلِ وَتُدۡلُواْ بِهَآ إِلَى ٱلۡحُكَّامِ لِتَأۡكُلُواْ فَرِيقٗا مِّنۡ أَمۡوَٰلِ ٱلنَّاسِ بِٱلۡإِثۡمِ وَأَنتُمۡ تَعۡلَمُونَ","aya_text_emlaey":"ولا تأكلوا أموالكم بينكم بالباطل وتدلوا بها إلى الحكام لتأكلوا فريقا من أموال الناس بالإثم وأنتم تعلمون ","aya_tafseer":"[188] ولا يأكل بعضكم مال بعض بسبب باطل كاليمين الكاذبة، والغَصْب، والسرقة، والرِّشوة، والربا ونحو ذلك، ولا تلقوا إلى الحكام بالحجج الباطلة؛ لتأكلوا عن طريق التخاصم أموال طائفة من الناس بالباطل، وأنتم تعلمون تحريم ذلك عليكم."},{"id":"196","jozz":"2","page":"29","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"11","line_end":"14","aya_no":"189","aya_text":"۞ يَسۡـَٔلُونَكَ عَنِ ٱلۡأَهِلَّةِۖ قُلۡ هِيَ مَوَٰقِيتُ لِلنَّاسِ وَٱلۡحَجِّۗ وَلَيۡسَ ٱلۡبِرُّ بِأَن تَأۡتُواْ ٱلۡبُيُوتَ مِن ظُهُورِهَا وَلَٰكِنَّ ٱلۡبِرَّ مَنِ ٱتَّقَىٰۗ وَأۡتُواْ ٱلۡبُيُوتَ مِنۡ أَبۡوَٰبِهَاۚ وَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تُفۡلِحُونَ","aya_text_emlaey":"يسألونك عن الأهلة قل هي مواقيت للناس والحج وليس البر بأن تأتوا البيوت من ظهورها ولكن البر من اتقى وأتوا البيوت من أبوابها واتقوا الله لعلكم تفلحون","aya_tafseer":"[189] يسألك أصحابك -أيها النبي-: عن الأهلة وتغيُّر أحوالها، قل لهم: جعل اللهُ الأهلة علامات يعرف بها الناس أوقات عباداتهم المحددة بوقت مثل الصيام والحج، ومعاملاتهم. وليس الخير ما تعودتم عليه في الجاهلية وأول الإسلام من دخول البيوت من ظهورها حين تُحْرِمون بالحج أو العمرة، ظانين أن ذلك قربة إلى الله، ولكن الخير هو فِعْلُ مَنِ اتقى الله واجتنب المعاصي، وادخلوا البيوت من أبوابها عند إحرامكم بالحج أو العمرة، واخشوا الله تعالى في كل أموركم؛ لتفوزوا بكل ما تحبون من خيري الدنيا والآخرة."},{"id":"197","jozz":"2","page":"29","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"14","line_end":"15","aya_no":"190","aya_text":"وَقَٰتِلُواْ فِي سَبِيلِ ٱللَّهِ ٱلَّذِينَ يُقَٰتِلُونَكُمۡ وَلَا تَعۡتَدُوٓاْۚ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡمُعۡتَدِينَ","aya_text_emlaey":"وقاتلوا في سبيل الله الذين يقاتلونكم ولا تعتدوا إن الله لا يحب المعتدين","aya_tafseer":"[190] وقاتلوا -أيها المؤمنون- لنصرة دين الله الذين يقاتلونكم، ولا ترتكبوا المناهي من المُثْلة، والغُلول، وقَتْلِ من لا يحلُّ قتله من النساء والصبيان والشيوخ، ومَنْ في حكمهم. إن الله لا يحب الذين يجاوزون حدوده، فيستحلون ما حرَّم الله ورسوله -صلى الله عليه وسلم-."},{"id":"198","jozz":"2","page":"30","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"1","line_end":"3","aya_no":"191","aya_text":"وَٱقۡتُلُوهُمۡ حَيۡثُ ثَقِفۡتُمُوهُمۡ وَأَخۡرِجُوهُم مِّنۡ حَيۡثُ أَخۡرَجُوكُمۡۚ وَٱلۡفِتۡنَةُ أَشَدُّ مِنَ ٱلۡقَتۡلِۚ وَلَا تُقَٰتِلُوهُمۡ عِندَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ حَتَّىٰ يُقَٰتِلُوكُمۡ فِيهِۖ فَإِن قَٰتَلُوكُمۡ فَٱقۡتُلُوهُمۡۗ كَذَٰلِكَ جَزَآءُ ٱلۡكَٰفِرِينَ","aya_text_emlaey":"واقتلوهم حيث ثقفتموهم وأخرجوهم من حيث أخرجوكم والفتنة أشد من القتل ولا تقاتلوهم عند المسجد الحرام حتى يقاتلوكم فيه فإن قاتلوكم فاقتلوهم كذلك جزاء الكافرين","aya_tafseer":"[191] واقتلوا الذين يقاتلونكم من المشركين حيث وجدتموهم، وأخرجوهم من المكان الذي أخرجوكم منه وهو «مكة». والفتنة -وهي الكفر والشرك والصد عن الإسلام- أشد من قتلكم إياهم. ولا تبدؤوهم بالقتال عند المسجد الحرام تعظيماً لحرماته حتى يبدؤوكم بالقتال فيه، فإن قاتلوكم في المسجد الحرام فاقتلوهم فيه. مثل ذلك الجزاء الرادع يكون جزاء الكافرين."},{"id":"199","jozz":"2","page":"30","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"3","line_end":"4","aya_no":"192","aya_text":"فَإِنِ ٱنتَهَوۡاْ فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ","aya_text_emlaey":"فإن انتهوا فإن الله غفور رحيم","aya_tafseer":"[192] فإن تركوا ما هم فيه من الكفر وقتالكم عند المسجد الحرام، ودخلوا في الإيمان، فإن الله غفور لعباده، رحيم بهم."},{"id":"200","jozz":"2","page":"30","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"4","line_end":"5","aya_no":"193","aya_text":"وَقَٰتِلُوهُمۡ حَتَّىٰ لَا تَكُونَ فِتۡنَةٞ وَيَكُونَ ٱلدِّينُ لِلَّهِۖ فَإِنِ ٱنتَهَوۡاْ فَلَا عُدۡوَٰنَ إِلَّا عَلَى ٱلظَّٰلِمِينَ","aya_text_emlaey":"وقاتلوهم حتى لا تكون فتنة ويكون الدين لله فإن انتهوا فلا عدوان إلا على الظالمين","aya_tafseer":"[193] واستمِرُّوا -أيها المؤمنون- في قتال المشركين المعتدين، حتى لا تكون فتنة للمسلمين عن دينهم ولا شرك بالله، ويبقى الدين لله وحده خالصاً لا يُعْبَد معه غيره. فإن كفُّوا عن الكفر والقتال فكُفُّوا عنهم؛ فالعقوبة لا تكون إلا على المستمرين على كفرهم وعدوانهم."},{"id":"201","jozz":"2","page":"30","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"5","line_end":"8","aya_no":"194","aya_text":"ٱلشَّهۡرُ ٱلۡحَرَامُ بِٱلشَّهۡرِ ٱلۡحَرَامِ وَٱلۡحُرُمَٰتُ قِصَاصٞۚ فَمَنِ ٱعۡتَدَىٰ عَلَيۡكُمۡ فَٱعۡتَدُواْ عَلَيۡهِ بِمِثۡلِ مَا ٱعۡتَدَىٰ عَلَيۡكُمۡۚ وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ مَعَ ٱلۡمُتَّقِينَ","aya_text_emlaey":"الشهر الحرام بالشهر الحرام والحرمات قصاص فمن اعتدى عليكم فاعتدوا عليه بمثل ما اعتدى عليكم واتقوا الله واعلموا أن الله مع المتقين","aya_tafseer":"[194] قتالكم -أيها المؤمنون- للمشركين في الشهر الذي حرَّم الله القتال فيه هو جزاء لقتالهم لكم في الشهر الحرام. والذي يعتدي على ما حَرَّم الله من المكان والزمان، يعاقب بمثل فعله، ومن جنس عمله. فمن اعتدى عليكم بالقتال أو غيره فأنزلوا به عقوبة مماثلة لجنايته، ولا حرج عليكم في ذلك؛ لأنهم هم البادئون بالعدوان، وخافوا الله فلا تتجاوزوا المماثلة في العقوبة، واعلموا أن الله مع الذين يتقونه ويطيعونه بأداء فرائضه وتجنب محارمه."},{"id":"202","jozz":"2","page":"30","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"8","line_end":"9","aya_no":"195","aya_text":"وَأَنفِقُواْ فِي سَبِيلِ ٱللَّهِ وَلَا تُلۡقُواْ بِأَيۡدِيكُمۡ إِلَى ٱلتَّهۡلُكَةِ وَأَحۡسِنُوٓاْۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُحۡسِنِينَ","aya_text_emlaey":"وأنفقوا في سبيل الله ولا تلقوا بأيديكم إلى التهلكة وأحسنوا إن الله يحب المحسنين","aya_tafseer":"[195] واستمِرُّوا -أيها المؤمنون- في إنفاق الأموال لنصرة دين الله تعالى، والجهاد في سبيله، ولا توقعوا أنفسكم في المهالك بترك الجهاد في سبيل الله، وعدم الإنفاق فيه، وأحسنوا في الإنفاق والطاعة، واجعلوا عملكم كله خالصاً لوجه الله تعالى. إن الله يحب أهل الإخلاص والإحسان."},{"id":"203","jozz":"2","page":"30","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"9","line_end":"15","aya_no":"196","aya_text":"وَأَتِمُّواْ ٱلۡحَجَّ وَٱلۡعُمۡرَةَ لِلَّهِۚ فَإِنۡ أُحۡصِرۡتُمۡ فَمَا ٱسۡتَيۡسَرَ مِنَ ٱلۡهَدۡيِۖ وَلَا تَحۡلِقُواْ رُءُوسَكُمۡ حَتَّىٰ يَبۡلُغَ ٱلۡهَدۡيُ مَحِلَّهُۥۚ فَمَن كَانَ مِنكُم مَّرِيضًا أَوۡ بِهِۦٓ أَذٗى مِّن رَّأۡسِهِۦ فَفِدۡيَةٞ مِّن صِيَامٍ أَوۡ صَدَقَةٍ أَوۡ نُسُكٖۚ فَإِذَآ أَمِنتُمۡ فَمَن تَمَتَّعَ بِٱلۡعُمۡرَةِ إِلَى ٱلۡحَجِّ فَمَا ٱسۡتَيۡسَرَ مِنَ ٱلۡهَدۡيِۚ فَمَن لَّمۡ يَجِدۡ فَصِيَامُ ثَلَٰثَةِ أَيَّامٖ فِي ٱلۡحَجِّ وَسَبۡعَةٍ إِذَا رَجَعۡتُمۡۗ تِلۡكَ عَشَرَةٞ كَامِلَةٞۗ ذَٰلِكَ لِمَن لَّمۡ يَكُنۡ أَهۡلُهُۥ حَاضِرِي ٱلۡمَسۡجِدِ ٱلۡحَرَامِۚ وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ","aya_text_emlaey":"وأتموا الحج والعمرة لله فإن أحصرتم فما استيسر من الهدي ولا تحلقوا رءوسكم حتى يبلغ الهدي محله فمن كان منكم مريضا أو به أذى من رأسه ففدية من صيام أو صدقة أو نسك فإذا أمنتم فمن تمتع بالعمرة إلى الحج فما استيسر من الهدي فمن لم يجد فصيام ثلاثة أيام في الحج وسبعة إذا رجعتم تلك عشرة كاملة ذلك لمن لم يكن أهله حاضري المسجد الحرام واتقوا الله واعلموا أن الله شديد العقاب","aya_tafseer":"[196] وأدُّوا الحج والعمرة تامَّيْنِ، خالصين لوجه الله تعالى. فإن منعكم عن الذهاب لإتمامهما بعد الإحرام بهما مانع كالعدو والمرض، فالواجب عليكم ذَبْحُ ما تيسر لكم من الإبل أو البقر أو الغنم تقرباً إلى الله تعالى؛ لكي تَخْرُجوا من إحرامكم بحلق شعر الرأس أو تقصيره، ولا تحلقوا رؤوسكم إذا كنتم مُحْصَرين حتى ينحر المُحْصَر هديه في الموضع الذي حُصر فيه ثم يحل من إحرامه، كما نحر النبي -صلى الله عليه وسلم- في «الحديبية» ثم حلق رأسه، وغير المُحْصَر لا ينحر الهدي إلا في الحرم، الذي هو محله في يوم العيد، اليوم العاشر وما بعده من أيام التشريق. فمن كان منكم مريضاً، أو به أذى من رأسه يحتاج معه إلى الحلق -وهو مُحْرِم- حَلَق، وعليه فدية: بأن يصوم ثلاثة أيام، أو يتصدق على ستة مساكين لكل مسكين نصف صاع من طعام، أو يذبح شاة لفقراء الحرم. فإذا كنتم في أمن وصحَّة: فمن استمتع بالعمرة إلى الحج وذلك باستباحة ما حُرِّم عليه بسبب الإحرام بعد انتهاء عمرته، فعليه ذبح ما تيسر من الهدي، فمن لم يجد هَدْياً يذبحه فعليه صيام ثلاثة أيام في أشهر الحج، وسبعة إذا فرغتم من أعمال الحج ورجعتم إلى أهليكم، تلك عشرة كاملة لا بد من صيامها. ذلك الهَدْيُ وما ترتب عليه من الصيام لمن لم يكن أهله من ساكني أرض الحرم، وخافوا الله تعالى وحافظوا على امتثال أوامره واجتناب نواهيه، واعلموا أن الله شديد العقاب لمن خالف أمره، وارتكب ما عنه زجر."},{"id":"204","jozz":"2","page":"31","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"1","line_end":"4","aya_no":"197","aya_text":"ٱلۡحَجُّ أَشۡهُرٞ مَّعۡلُومَٰتٞۚ فَمَن فَرَضَ فِيهِنَّ ٱلۡحَجَّ فَلَا رَفَثَ وَلَا فُسُوقَ وَلَا جِدَالَ فِي ٱلۡحَجِّۗ وَمَا تَفۡعَلُواْ مِنۡ خَيۡرٖ يَعۡلَمۡهُ ٱللَّهُۗ وَتَزَوَّدُواْ فَإِنَّ خَيۡرَ ٱلزَّادِ ٱلتَّقۡوَىٰۖ وَٱتَّقُونِ يَٰٓأُوْلِي ٱلۡأَلۡبَٰبِ","aya_text_emlaey":"الحج أشهر معلومات فمن فرض فيهن الحج فلا رفث ولا فسوق ولا جدال في الحج وما تفعلوا من خير يعلمه الله وتزودوا فإن خير الزاد التقوى واتقون ياأولي الألباب","aya_tafseer":"[197] وقت الحج أشهر معلومات، وهي: شوال، وذو القعدة، وعشر من ذي الحجة. فمن أوجب الحج على نفسه فيهن بالإحرام، فيَحْرُم عليه الجماع ومقدماته القولية والفعلية، ويَحْرُم عليه الخروج عن طاعة الله تعالى بفعل المعاصي، والجدال في الحج الذي يؤدي إلى الغضب والكراهية. وما تفعلوا من خير يعلمْه الله، فيجازي كُلّاً على عمله. وخذوا لأنفسكم زاداً من الطعام والشراب لسفر الحج، وزاداً من صالح الأعمال للدار الآخرة، فإن خير الزاد تقوى الله، وخافوني يا أصحاب العقول السليمة."},{"id":"205","jozz":"2","page":"31","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"4","line_end":"8","aya_no":"198","aya_text":"لَيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَن تَبۡتَغُواْ فَضۡلٗا مِّن رَّبِّكُمۡۚ فَإِذَآ أَفَضۡتُم مِّنۡ عَرَفَٰتٖ فَٱذۡكُرُواْ ٱللَّهَ عِندَ ٱلۡمَشۡعَرِ ٱلۡحَرَامِۖ وَٱذۡكُرُوهُ كَمَا هَدَىٰكُمۡ وَإِن كُنتُم مِّن قَبۡلِهِۦ لَمِنَ ٱلضَّآلِّينَ","aya_text_emlaey":"ليس عليكم جناح أن تبتغوا فضلا من ربكم فإذا أفضتم من عرفات فاذكروا الله عند المشعر الحرام واذكروه كما هداكم وإن كنتم من قبله لمن الضالين","aya_tafseer":"[198] ليس عليكم حرج في أن تطلبوا رزقاً من ربكم بالربح من التجارة في أيام الحج. فإذا دفعتم بعد غروب الشمس راجعين من «عرفات» -وهي المكان الذي يقف فيه الحجاج يوم التاسع من ذي الحجة- فاذكروا الله بالتسبيح والتلبية والدعاء عند المشعر الحرام -«المزدلفة»-، واذكروا الله على الوجه الصحيح الذي هداكم إليه، ولقد كنتم من قبل هذا الهدى في ضلال لا تعرفون معه الحق."},{"id":"206","jozz":"2","page":"31","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"8","line_end":"9","aya_no":"199","aya_text":"ثُمَّ أَفِيضُواْ مِنۡ حَيۡثُ أَفَاضَ ٱلنَّاسُ وَٱسۡتَغۡفِرُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ","aya_text_emlaey":"ثم أفيضوا من حيث أفاض الناس واستغفروا الله إن الله غفور رحيم","aya_tafseer":"[199] وليكن اندفاعكم من «عرفات» التي أفاض منها إبراهيم عليه السلام، مخالفين بذلك مَن لا يقف بها من أهل الجاهلية، واسألوا الله أن يغفر لكم ذنوبكم. إن الله غفور لعباده المستغفرين التائبين، رحيم بهم."},{"id":"207","jozz":"2","page":"31","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"10","line_end":"12","aya_no":"200","aya_text":"فَإِذَا قَضَيۡتُم مَّنَٰسِكَكُمۡ فَٱذۡكُرُواْ ٱللَّهَ كَذِكۡرِكُمۡ ءَابَآءَكُمۡ أَوۡ أَشَدَّ ذِكۡرٗاۗ فَمِنَ ٱلنَّاسِ مَن يَقُولُ رَبَّنَآ ءَاتِنَا فِي ٱلدُّنۡيَا وَمَا لَهُۥ فِي ٱلۡأٓخِرَةِ مِنۡ خَلَٰقٖ","aya_text_emlaey":"فإذا قضيتم مناسككم فاذكروا الله كذكركم آباءكم أو أشد ذكرا فمن الناس من يقول ربنا آتنا في الدنيا وما له في الآخرة من خلاق","aya_tafseer":"[200] فإذا أتممتم عبادتكم، وفرغتم من أعمال الحج، فأكثروا من ذكر الله والثناء عليه، مثل ذكركم مفاخر آبائكم وأعظم من ذلك. فمن الناس فريق يجعل همه الدنيا فقط، فيدعو قائلاً: ربنا آتنا في الدنيا صحة، ومالاً، وأولاداً، وهؤلاء ليس لهم في الآخرة حظ ولا نصيب؛ لرغبتهم عنها وقَصْرِ هَمِّهم على الدنيا."},{"id":"208","jozz":"2","page":"31","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"13","line_end":"14","aya_no":"201","aya_text":"وَمِنۡهُم مَّن يَقُولُ رَبَّنَآ ءَاتِنَا فِي ٱلدُّنۡيَا حَسَنَةٗ وَفِي ٱلۡأٓخِرَةِ حَسَنَةٗ وَقِنَا عَذَابَ ٱلنَّارِ","aya_text_emlaey":"ومنهم من يقول ربنا آتنا في الدنيا حسنة وفي الآخرة حسنة وقنا عذاب النار","aya_tafseer":"[201] ومن الناس فريق مؤمن يقول في دعائه: ربنا آتنا في الدنيا عافية ورزقاً وعلماً نافعاً، وعملاً صالحاً، وغير ذلك من أمور الدين والدنيا ، وفي الآخرة الجنة، واصرف عنَّا عذاب النار. وهذا الدعاء من أجمع الأدعية، ولهذا كان أكثر دعاء النبي -صلى الله عليه وسلم-، كما ثبت في الصحيحين."},{"id":"209","jozz":"2","page":"31","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"14","line_end":"15","aya_no":"202","aya_text":"أُوْلَٰٓئِكَ لَهُمۡ نَصِيبٞ مِّمَّا كَسَبُواْۚ وَٱللَّهُ سَرِيعُ ٱلۡحِسَابِ","aya_text_emlaey":"أولئك لهم نصيب مما كسبوا والله سريع الحساب","aya_tafseer":"[202] أولئك الداعون بهذا الدعاء لهم ثواب عظيم؛ بسبب ما كسبوه من الأعمال الصالحة. والله سريع الحساب، مُحْصٍ أعمال عباده، ومجازيهم بها."},{"id":"210","jozz":"2","page":"32","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"1","line_end":"3","aya_no":"203","aya_text":"۞ وَٱذۡكُرُواْ ٱللَّهَ فِيٓ أَيَّامٖ مَّعۡدُودَٰتٖۚ فَمَن تَعَجَّلَ فِي يَوۡمَيۡنِ فَلَآ إِثۡمَ عَلَيۡهِ وَمَن تَأَخَّرَ فَلَآ إِثۡمَ عَلَيۡهِۖ لِمَنِ ٱتَّقَىٰۗ وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّكُمۡ إِلَيۡهِ تُحۡشَرُونَ","aya_text_emlaey":"واذكروا الله في أيام معدودات فمن تعجل في يومين فلا إثم عليه ومن تأخر فلا إثم عليه لمن اتقى واتقوا الله واعلموا أنكم إليه تحشرون","aya_tafseer":"[203] واذكروا الله تسبيحاً وتكبيراً في أيام قلائل، وهي أيام التشريق: الحادي عشر والثاني عشر والثالث عشر من شهر ذي الحجة. فمن أراد التعجل وخرج من «مِنى» قبل غروب شمس اليوم الثاني عشر بعد رمي الجمار فلا ذنب عليه، ومن تأخر بأن بات ﺑ«مِنى» حتى يرمي الجمار في اليوم الثالث عشر فلا ذنب عليه، لمن اتقى الله في حجه. والتأخر أفضل؛ لأنه تزوُّد في العبادة واقتداء بفعل النبي -صلى الله عليه وسلم-.وخافوا الله -أيها المسلمون- وراقبوه في كل أعمالكم، واعلموا أنكم إليه وحده تُحْشَرون بعد موتكم للحساب والجزاء."},{"id":"211","jozz":"2","page":"32","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"4","line_end":"5","aya_no":"204","aya_text":"وَمِنَ ٱلنَّاسِ مَن يُعۡجِبُكَ قَوۡلُهُۥ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَيُشۡهِدُ ٱللَّهَ عَلَىٰ مَا فِي قَلۡبِهِۦ وَهُوَ أَلَدُّ ٱلۡخِصَامِ","aya_text_emlaey":"ومن الناس من يعجبك قوله في الحياة الدنيا ويشهد الله على ما في قلبه وهو ألد الخصام","aya_tafseer":"[204] وبعض الناس من المنافقين يعجبك -أيها الرسول- كلامه الفصيح الذي يريد به حظّاً من حظوظ الدنيا لا الآخرة، ويحلف مستشهداً بالله على ما في قلبه من محبة الإسلام، وفي هذا غاية الجرأة على الله، وهو شديد العداوة والخصومة للإسلام والمسلمين."},{"id":"212","jozz":"2","page":"32","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"6","line_end":"7","aya_no":"205","aya_text":"وَإِذَا تَوَلَّىٰ سَعَىٰ فِي ٱلۡأَرۡضِ لِيُفۡسِدَ فِيهَا وَيُهۡلِكَ ٱلۡحَرۡثَ وَٱلنَّسۡلَۚ وَٱللَّهُ لَا يُحِبُّ ٱلۡفَسَادَ","aya_text_emlaey":"وإذا تولى سعى في الأرض ليفسد فيها ويهلك الحرث والنسل والله لا يحب الفساد","aya_tafseer":"[205] وإذا خرج مِن عندك أيها الرسول، جَدَّ ونَشِط في الأرض ليفسد فيها، ويتلف زروع الناس، ويقتل ماشيتهم. والله لا يحب الفساد."},{"id":"213","jozz":"2","page":"32","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"7","line_end":"9","aya_no":"206","aya_text":"وَإِذَا قِيلَ لَهُ ٱتَّقِ ٱللَّهَ أَخَذَتۡهُ ٱلۡعِزَّةُ بِٱلۡإِثۡمِۚ فَحَسۡبُهُۥ جَهَنَّمُۖ وَلَبِئۡسَ ٱلۡمِهَادُ","aya_text_emlaey":"وإذا قيل له اتق الله أخذته العزة بالإثم فحسبه جهنم ولبئس المهاد","aya_tafseer":"[206] وإذا نُصِح ذلك المنافق المفسد، وقيل له: اتق الله واحذر عقابه، وكُفَّ عن الفساد في الأرض، لم يقبل النصيحة، بل يحمله الكبر وحميَّة الجاهلية على مزيد من الآثام، فَحَسْبُه جهنم وكافيته عذاباً، ولبئس الفراش هي."},{"id":"214","jozz":"2","page":"32","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"9","line_end":"10","aya_no":"207","aya_text":"وَمِنَ ٱلنَّاسِ مَن يَشۡرِي نَفۡسَهُ ٱبۡتِغَآءَ مَرۡضَاتِ ٱللَّهِۚ وَٱللَّهُ رَءُوفُۢ بِٱلۡعِبَادِ","aya_text_emlaey":"ومن الناس من يشري نفسه ابتغاء مرضات الله والله رءوف بالعباد","aya_tafseer":"[207] وبعض الناس يبيع نفسه طلباً لرضا الله عنه، بالجهاد في سبيله، والتزام طاعته. والله رؤوف بالعباد، يرحم عباده المؤمنين رحمة واسعة في عاجلهم وآجلهم، فيجازيهم أحسن الجزاء."},{"id":"215","jozz":"2","page":"32","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"10","line_end":"12","aya_no":"208","aya_text":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱدۡخُلُواْ فِي ٱلسِّلۡمِ كَآفَّةٗ وَلَا تَتَّبِعُواْ خُطُوَٰتِ ٱلشَّيۡطَٰنِۚ إِنَّهُۥ لَكُمۡ عَدُوّٞ مُّبِينٞ","aya_text_emlaey":"ياأيها الذين آمنوا ادخلوا في السلم كافة ولا تتبعوا خطوات الشيطان إنه لكم عدو مبين","aya_tafseer":"[208] يا أيها الذين آمنوا بالله ربّاً وبمحمد نبيّاً ورسولاً وبالإسلام ديناً، ادخلوا في جميع شرائع الإسلام، عاملين بجميع أحكامه، ولا تتركوا منها شيئاً، ولا تتبعوا طرق الشيطان فيما يدعوكم إليه من المعاصي. إنه لكم عدو ظاهر العداوة فاحذروه."},{"id":"216","jozz":"2","page":"32","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"12","line_end":"13","aya_no":"209","aya_text":"فَإِن زَلَلۡتُم مِّنۢ بَعۡدِ مَا جَآءَتۡكُمُ ٱلۡبَيِّنَٰتُ فَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ","aya_text_emlaey":"فإن زللتم من بعد ما جاءتكم البينات فاعلموا أن الله عزيز حكيم","aya_tafseer":"[209] فإن انحرفتم عن طريق الحق، من بعد ما جاءتكم الحجج الواضحة من القرآن والسنة، فاعلموا أن الله عزيز في ملكه لا يفوته شيء، حكيم في أمره ونهيه، يضع كل شيء في موضعه المناسب له."},{"id":"217","jozz":"2","page":"32","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"14","line_end":"15","aya_no":"210","aya_text":"هَلۡ يَنظُرُونَ إِلَّآ أَن يَأۡتِيَهُمُ ٱللَّهُ فِي ظُلَلٖ مِّنَ ٱلۡغَمَامِ وَٱلۡمَلَٰٓئِكَةُ وَقُضِيَ ٱلۡأَمۡرُۚ وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ","aya_text_emlaey":"هل ينظرون إلا أن يأتيهم الله في ظلل من الغمام والملائكة وقضي الأمر وإلى الله ترجع الأمور","aya_tafseer":"[210] ما ينتظر هؤلاء المعاندون الكافرون بعد قيام الأدلة البينة إلا أن يأتيهم الله عز وجل، على الوجه اللائق به سبحانه في ظُلَل من السحاب يوم القيامة؛ ليفصل بينهم بالقضاء العادل، وأن تأتي الملائكة، وحينئذ يقضي الله تعالى فيهم قضاءه. وإليه وحده ترجع أمور الخلائق جميعها."},{"id":"218","jozz":"2","page":"33","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"1","line_end":"2","aya_no":"211","aya_text":"سَلۡ بَنِيٓ إِسۡرَٰٓءِيلَ كَمۡ ءَاتَيۡنَٰهُم مِّنۡ ءَايَةِۭ بَيِّنَةٖۗ وَمَن يُبَدِّلۡ نِعۡمَةَ ٱللَّهِ مِنۢ بَعۡدِ مَا جَآءَتۡهُ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ","aya_text_emlaey":"سل بني إسرائيل كم آتيناهم من آية بينة ومن يبدل نعمة الله من بعد ما جاءته فإن الله شديد العقاب","aya_tafseer":"[211] سل -أيها الرسول- بني إسرائيل المعاندين لك: كم أعطيناهم من آيات واضحات في كتبهم تهديهم إلى الحق، فكفروا بها كلِّها، وأعرضوا عنها، وحَرَّفوها عن مواضعها. ومن يبدل نعمة الله -وهي دينه- ويكفر بها من بعد معرفتها، وقيام الحجة عليه بها، فإن الله تعالى شديد العقاب له."},{"id":"219","jozz":"2","page":"33","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"2","line_end":"4","aya_no":"212","aya_text":"زُيِّنَ لِلَّذِينَ كَفَرُواْ ٱلۡحَيَوٰةُ ٱلدُّنۡيَا وَيَسۡخَرُونَ مِنَ ٱلَّذِينَ ءَامَنُواْۘ وَٱلَّذِينَ ٱتَّقَوۡاْ فَوۡقَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِۗ وَٱللَّهُ يَرۡزُقُ مَن يَشَآءُ بِغَيۡرِ حِسَابٖ","aya_text_emlaey":"زين للذين كفروا الحياة الدنيا ويسخرون من الذين آمنوا والذين اتقوا فوقهم يوم القيامة والله يرزق من يشاء بغير حساب","aya_tafseer":"[212] حُسِّن للذين جحدوا وحدانية الله الحياةُ الدنيا وما فيها من الشهوات والملذات، وهم يستهزئون بالمؤمنين. وهؤلاء الذين يخشون ربهم فوق جميع الكفار يوم القيامة؛ حيث يدخلهم الله أعلى درجات الجنة، وينزل الكافرين أسفل دركات النار. والله يرزق مَن يشاء مِن خلقه بغير حساب."},{"id":"220","jozz":"2","page":"33","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"5","line_end":"10","aya_no":"213","aya_text":"كَانَ ٱلنَّاسُ أُمَّةٗ وَٰحِدَةٗ فَبَعَثَ ٱللَّهُ ٱلنَّبِيِّـۧنَ مُبَشِّرِينَ وَمُنذِرِينَ وَأَنزَلَ مَعَهُمُ ٱلۡكِتَٰبَ بِٱلۡحَقِّ لِيَحۡكُمَ بَيۡنَ ٱلنَّاسِ فِيمَا ٱخۡتَلَفُواْ فِيهِۚ وَمَا ٱخۡتَلَفَ فِيهِ إِلَّا ٱلَّذِينَ أُوتُوهُ مِنۢ بَعۡدِ مَا جَآءَتۡهُمُ ٱلۡبَيِّنَٰتُ بَغۡيَۢا بَيۡنَهُمۡۖ فَهَدَى ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ لِمَا ٱخۡتَلَفُواْ فِيهِ مِنَ ٱلۡحَقِّ بِإِذۡنِهِۦۗ وَٱللَّهُ يَهۡدِي مَن يَشَآءُ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٍ","aya_text_emlaey":"كان الناس أمة واحدة فبعث الله النبيين مبشرين ومنذرين وأنـزل معهم الكتاب بالحق ليحكم بين الناس فيما اختلفوا فيه وما اختلف فيه إلا الذين أوتوه من بعد ما جاءتهم البينات بغيا بينهم فهدى الله الذين آمنوا لما اختلفوا فيه من الحق بإذنه والله يهدي من يشاء إلى صراط مستقيم","aya_tafseer":"[213] كان الناس جماعة واحدة، متفقين على الإيمان بالله ثم اختلفوا في دينهم، فبعث الله النبيين دعاة لدين الله، مبشرين مَن أطاع الله بالجنة، ومحذرين من كفر به وعصاه النار، وأنزل معهم الكتب السماوية بالحق الذي اشتملت عليه؛ ليحكموا بما فيها بين الناس فيما اختلفوا فيه، وما اخْتَلَف في أمر محمد -صلى الله عليه وسلم- وكتابه ظلماً وحسداً إلا الذين أعطاهم الله التوراة، وعرفوا ما فيها من الحجج والأحكام، فوفَّق الله المؤمنين بفضله إلى تمييز الحق من الباطل، ومعرفة ما اختلفوا فيه. والله يوفِّق مَن يشاء مِن عباده إلى طريق مستقيم."},{"id":"221","jozz":"2","page":"33","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"10","line_end":"13","aya_no":"214","aya_text":"أَمۡ حَسِبۡتُمۡ أَن تَدۡخُلُواْ ٱلۡجَنَّةَ وَلَمَّا يَأۡتِكُم مَّثَلُ ٱلَّذِينَ خَلَوۡاْ مِن قَبۡلِكُمۖ مَّسَّتۡهُمُ ٱلۡبَأۡسَآءُ وَٱلضَّرَّآءُ وَزُلۡزِلُواْ حَتَّىٰ يَقُولَ ٱلرَّسُولُ وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ مَتَىٰ نَصۡرُ ٱللَّهِۗ أَلَآ إِنَّ نَصۡرَ ٱللَّهِ قَرِيبٞ","aya_text_emlaey":"أم حسبتم أن تدخلوا الجنة ولما يأتكم مثل الذين خلوا من قبلكم مستهم البأساء والضراء وزلزلوا حتى يقول الرسول والذين آمنوا معه متى نصر الله ألا إن نصر الله قريب","aya_tafseer":"[214] بل أظننتم -أيها المؤمنون- أن تدخلوا الجنة، ولَمَّا يصبكم من الابتلاء مِثْلُ ما أصاب المؤمنين الذين مضوا من قبلكم: من الفقر والأمراض والخوف والرعب، وزُلزلوا بأنواع المخاوف، حتى قال رسولهم والمؤمنون معه -على سبيل الاستعجال للنصر من الله تعالى-: متى نصر الله؟ ألا إن نصر الله قريب من المؤمنين."},{"id":"222","jozz":"2","page":"33","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"13","line_end":"15","aya_no":"215","aya_text":"يَسۡـَٔلُونَكَ مَاذَا يُنفِقُونَۖ قُلۡ مَآ أَنفَقۡتُم مِّنۡ خَيۡرٖ فَلِلۡوَٰلِدَيۡنِ وَٱلۡأَقۡرَبِينَ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينِ وَٱبۡنِ ٱلسَّبِيلِۗ وَمَا تَفۡعَلُواْ مِنۡ خَيۡرٖ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٞ","aya_text_emlaey":"يسألونك ماذا ينفقون قل ما أنفقتم من خير فللوالدين والأقربين واليتامى والمساكين وابن السبيل وما تفعلوا من خير فإن الله به عليم","aya_tafseer":"[215] يسألك أصحابك -أيها النبي- أي شيء ينفقون من أصناف أموالهم تقرباً إلى الله تعالى، وعلى مَن ينفقون؟ قل لهم: أنفقوا أيَّ خير يتيسر لكم من أصناف المال الحلال الطيب، واجعلوا نفقتكم للوالدين، والأقربين من أهلكم وذوي أرحامكم، واليتامى الذين مات آباؤهم وهم دون سنِّ البلوغ، والمحتاجين الذين لا يملكون ما يكفيهم ويسدُّ حاجتهم، والمسافر المحتاج الذي بَعُدَ عن أهله وماله. وما تفعلوا من خير فإن الله تعالى به عليم."},{"id":"223","jozz":"2","page":"34","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"1","line_end":"3","aya_no":"216","aya_text":"كُتِبَ عَلَيۡكُمُ ٱلۡقِتَالُ وَهُوَ كُرۡهٞ لَّكُمۡۖ وَعَسَىٰٓ أَن تَكۡرَهُواْ شَيۡـٔٗا وَهُوَ خَيۡرٞ لَّكُمۡۖ وَعَسَىٰٓ أَن تُحِبُّواْ شَيۡـٔٗا وَهُوَ شَرّٞ لَّكُمۡۚ وَٱللَّهُ يَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ","aya_text_emlaey":"كتب عليكم القتال وهو كره لكم وعسى أن تكرهوا شيئا وهو خير لكم وعسى أن تحبوا شيئا وهو شر لكم والله يعلم وأنتم لا تعلمون","aya_tafseer":"[216] فرض الله عليكم -أيها المؤمنون- قتال الكفار، والقتال مكروه لكم من جهة الطبع؛ لمشقته وكثرة مخاطره، وقد تكرهون شيئاً وهو في حقيقته خير لكم، وقد تحبون شيئاً لما فيه من الراحة أو اللذة العاجلة، وهو شر لكم. والله تعالى يعلم ما هو خير لكم، وأنتم لا تعلمون ذلك. فبادروا إلى الجهاد في سبيله."},{"id":"224","jozz":"2","page":"34","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"3","line_end":"10","aya_no":"217","aya_text":"يَسۡـَٔلُونَكَ عَنِ ٱلشَّهۡرِ ٱلۡحَرَامِ قِتَالٖ فِيهِۖ قُلۡ قِتَالٞ فِيهِ كَبِيرٞۚ وَصَدٌّ عَن سَبِيلِ ٱللَّهِ وَكُفۡرُۢ بِهِۦ وَٱلۡمَسۡجِدِ ٱلۡحَرَامِ وَإِخۡرَاجُ أَهۡلِهِۦ مِنۡهُ أَكۡبَرُ عِندَ ٱللَّهِۚ وَٱلۡفِتۡنَةُ أَكۡبَرُ مِنَ ٱلۡقَتۡلِۗ وَلَا يَزَالُونَ يُقَٰتِلُونَكُمۡ حَتَّىٰ يَرُدُّوكُمۡ عَن دِينِكُمۡ إِنِ ٱسۡتَطَٰعُواْۚ وَمَن يَرۡتَدِدۡ مِنكُمۡ عَن دِينِهِۦ فَيَمُتۡ وَهُوَ كَافِرٞ فَأُوْلَٰٓئِكَ حَبِطَتۡ أَعۡمَٰلُهُمۡ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۖ وَأُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ","aya_text_emlaey":"يسألونك عن الشهر الحرام قتال فيه قل قتال فيه كبير وصد عن سبيل الله وكفر به والمسجد الحرام وإخراج أهله منه أكبر عند الله والفتنة أكبر من القتل ولا يزالون يقاتلونكم حتى يردوكم عن دينكم إن استطاعوا ومن يرتدد منكم عن دينه فيمت وهو كافر فأولئك حبطت أعمالهم في الدنيا والآخرة وأولئك أصحاب النار هم فيها خالدون","aya_tafseer":"[217] يسألك المشركون -أيها الرسول- عن الشهر الحرام: هل يحل فيه القتال؟ قل لهم: القتال في الشهر الحرام عظيم عند الله استحلاله وسفك الدماء فيه، ومَنْعكم الناس من دخول الإسلام بالتعذيب والتخويف، وجحودكم بالله وبرسوله وبدينه، ومَنْع المسلمين من دخول المسجد الحرام، وإخراج النبي والمهاجرين منه وهم أهله وأولياؤه، ذلك أكبر ذنباً، وأعظم جرماً عند الله من القتال في الشهر الحرام. والشرك الذي أنتم فيه أكبر وأشد من القتل في الشهر الحرام. وهؤلاء الكفار لم يرتدعوا عن جرائمهم، بل هم مستمرون عليها، ولا يزالون يقاتلونكم حتى يردوكم عن الإسلام إلى الكفر إن استطاعوا تحقيق ذلك. ومن يُطِعْهم منكم -أيها المسلمون- ويَرْتَدِدْ عن دينه فيمت على الكفر، فقد ذهب عمله في الدنيا والآخرة، وصار من الملازمين لنار جهنم لا يخرج منها أبداً."},{"id":"225","jozz":"2","page":"34","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"10","line_end":"12","aya_no":"218","aya_text":"إِنَّ ٱلَّذِينَ ءَامَنُواْ وَٱلَّذِينَ هَاجَرُواْ وَجَٰهَدُواْ فِي سَبِيلِ ٱللَّهِ أُوْلَٰٓئِكَ يَرۡجُونَ رَحۡمَتَ ٱللَّهِۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ","aya_text_emlaey":"إن الذين آمنوا والذين هاجروا وجاهدوا في سبيل الله أولئك يرجون رحمة الله والله غفور رحيم","aya_tafseer":"[218] إن الذين صَدَّقوا بالله ورسوله وعملوا بشرعه والذين تركوا ديارهم، وجاهدوا في سبيل الله، أولئك يطمعون في فضل الله وثوابه. والله غفور لذنوب عباده المؤمنين، رحيم بهم رحمة واسعة."},{"id":"226","jozz":"2","page":"34","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"12","line_end":"15","aya_no":"219","aya_text":"۞ يَسۡـَٔلُونَكَ عَنِ ٱلۡخَمۡرِ وَٱلۡمَيۡسِرِۖ قُلۡ فِيهِمَآ إِثۡمٞ كَبِيرٞ وَمَنَٰفِعُ لِلنَّاسِ وَإِثۡمُهُمَآ أَكۡبَرُ مِن نَّفۡعِهِمَاۗ وَيَسۡـَٔلُونَكَ مَاذَا يُنفِقُونَۖ قُلِ ٱلۡعَفۡوَۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلۡأٓيَٰتِ لَعَلَّكُمۡ تَتَفَكَّرُونَ","aya_text_emlaey":"يسألونك عن الخمر والميسر قل فيهما إثم كبير ومنافع للناس وإثمهما أكبر من نفعهما ويسألونك ماذا ينفقون قل العفو كذلك يبين الله لكم الآيات لعلكم تتفكرون","aya_tafseer":"[219] يسألك المسلمون -أيها النبي- عن حكم تعاطي الخمر شرباً وبيعاً وشراءً، والخمر كل مسكر خامر العقل وغطاه مشروباً كان أو مأكولاً، ويسألونك عن حكم القمار -وهو أَخْذُ المال أو إعطاؤه بالمقامرة وهي المغالبات التي فيها عوض من الطرفين-، قل لهم: في ذلك أضرار ومفاسد كثيرة في الدين والدنيا، والعقول والأموال، وفيهما منافع للناس من جهة كسب الأموال وغيرها، وإثمهما أكبر من نفعهما؛ إذ يصدَّان عن ذكر الله وعن الصلاة، ويوقعان العداوة والبغضاء بين الناس، ويتلفان المال. وكان هذا تمهيداً لتحريمهما. ويسألونك عن القَدْر الذي ينفقونه من أموالهم تبرعاً وصدقة، قل لهم: أنفقوا القَدْر الذي يزيد على حاجتكم. مثل ذلك البيان الواضح يبيِّن الله لكم الآيات وأحكام الشريعة؛ لكي تتفكروا فيما ينفعكم في الدنيا والآخرة."},{"id":"227","jozz":"2","page":"35","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"1","line_end":"3","aya_no":"220","aya_text":"فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۗ وَيَسۡـَٔلُونَكَ عَنِ ٱلۡيَتَٰمَىٰۖ قُلۡ إِصۡلَاحٞ لَّهُمۡ خَيۡرٞۖ وَإِن تُخَالِطُوهُمۡ فَإِخۡوَٰنُكُمۡۚ وَٱللَّهُ يَعۡلَمُ ٱلۡمُفۡسِدَ مِنَ ٱلۡمُصۡلِحِۚ وَلَوۡ شَآءَ ٱللَّهُ لَأَعۡنَتَكُمۡۚ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٞ","aya_text_emlaey":"في الدنيا والآخرة ويسألونك عن اليتامى قل إصلاح لهم خير وإن تخالطوهم فإخوانكم والله يعلم المفسد من المصلح ولو شاء الله لأعنتكم إن الله عزيز حكيم","aya_tafseer":"[220] ويسألونك -أيها النبي- عن اليتامى الذين مات آباؤهم وهم دون سن البلوغ كيف يتصرفون معهم في معاشهم وأموالهم؟ قل لهم: إصلاحكم لهم خير، فافعلوا الأنفع لهم دائماً، وإن تخالطوهم في سائر شؤون المعاش فهم إخوانكم في الدين. وعلى الأخ أن يرعى مصلحة أخيه. والله يعلم المضيع لأموال اليتامى من الحريص على إصلاحها. ولو شاء الله لضيَّق وشقَّ عليكم بتحريم المخالطة. إن الله عزيز في ملكه، حكيم في خلقه وتدبيره وتشريعه."},{"id":"228","jozz":"2","page":"35","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"4","line_end":"8","aya_no":"221","aya_text":"وَلَا تَنكِحُواْ ٱلۡمُشۡرِكَٰتِ حَتَّىٰ يُؤۡمِنَّۚ وَلَأَمَةٞ مُّؤۡمِنَةٌ خَيۡرٞ مِّن مُّشۡرِكَةٖ وَلَوۡ أَعۡجَبَتۡكُمۡۗ وَلَا تُنكِحُواْ ٱلۡمُشۡرِكِينَ حَتَّىٰ يُؤۡمِنُواْۚ وَلَعَبۡدٞ مُّؤۡمِنٌ خَيۡرٞ مِّن مُّشۡرِكٖ وَلَوۡ أَعۡجَبَكُمۡۗ أُوْلَٰٓئِكَ يَدۡعُونَ إِلَى ٱلنَّارِۖ وَٱللَّهُ يَدۡعُوٓاْ إِلَى ٱلۡجَنَّةِ وَٱلۡمَغۡفِرَةِ بِإِذۡنِهِۦۖ وَيُبَيِّنُ ءَايَٰتِهِۦ لِلنَّاسِ لَعَلَّهُمۡ يَتَذَكَّرُونَ","aya_text_emlaey":"ولا تنكحوا المشركات حتى يؤمن ولأمة مؤمنة خير من مشركة ولو أعجبتكم ولا تنكحوا المشركين حتى يؤمنوا ولعبد مؤمن خير من مشرك ولو أعجبكم أولئك يدعون إلى النار والله يدعو إلى الجنة والمغفرة بإذنه ويبين آياته للناس لعلهم يتذكرون","aya_tafseer":"[221] ولا تتزوجوا -أيها المسلمون- المشركات العابدات الأوثان، حتى يدخلن في الإسلام. واعلموا أن امرأة مملوكة لا مال لها ولا حسب، مؤمنةً بالله، خير من امرأة مشركة، وإن أعجبتكم المشركة الحرة. ولا تُزَوِّجوا نساءكم المؤمنات -إماء أو حرائر- للمشركين حتى يؤمنوا بالله ورسوله. واعلموا أن عبداً مؤمناً مع فقره، خير من مشرك، وإن أعجبكم المشرك. أولئك المتصفون بالشرك رجالاً ونساءً يدعون كلَّ مَن يعاشرهم إلى ما يؤدي به إلى النار، والله سبحانه يدعو عباده إلى دينه الحق المؤدي بهم إلى الجنة ومغفرة ذنوبهم بإذنه، ويبين آياته وأحكامه للناس؛ لكي يتذكروا، فيعتبروا."},{"id":"229","jozz":"2","page":"35","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"9","line_end":"11","aya_no":"222","aya_text":"وَيَسۡـَٔلُونَكَ عَنِ ٱلۡمَحِيضِۖ قُلۡ هُوَ أَذٗى فَٱعۡتَزِلُواْ ٱلنِّسَآءَ فِي ٱلۡمَحِيضِ وَلَا تَقۡرَبُوهُنَّ حَتَّىٰ يَطۡهُرۡنَۖ فَإِذَا تَطَهَّرۡنَ فَأۡتُوهُنَّ مِنۡ حَيۡثُ أَمَرَكُمُ ٱللَّهُۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلتَّوَّٰبِينَ وَيُحِبُّ ٱلۡمُتَطَهِّرِينَ","aya_text_emlaey":"ويسألونك عن المحيض قل هو أذى فاعتزلوا النساء في المحيض ولا تقربوهن حتى يطهرن فإذا تطهرن فأتوهن من حيث أمركم الله إن الله يحب التوابين ويحب المتطهرين","aya_tafseer":"[222] ويسألونك عن الحيض -وهو الدم الذي يسيل من أرحام النساء جِبِلَّة في أوقات مخصوصة-، قل لهم -أيها النبي-: هو أذى مستقذر يضر من يَقْرَبُه، فاجتنبوا جماع النساء مدة الحيض حتى ينقطع الدم، فإذا انقطع الدم، واغتسلن، فجامعوهن في الموضع الذي أحلَّه الله لكم، وهو القبل لا الدبر. إن الله يحب عباده المكثرين من الاستغفار والتوبة، ويحب عباده المتطهرين الذين يبتعدون عن الفواحش والأقذار."},{"id":"230","jozz":"2","page":"35","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"12","line_end":"14","aya_no":"223","aya_text":"نِسَآؤُكُمۡ حَرۡثٞ لَّكُمۡ فَأۡتُواْ حَرۡثَكُمۡ أَنَّىٰ شِئۡتُمۡۖ وَقَدِّمُواْ لِأَنفُسِكُمۡۚ وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّكُم مُّلَٰقُوهُۗ وَبَشِّرِ ٱلۡمُؤۡمِنِينَ","aya_text_emlaey":"نساؤكم حرث لكم فأتوا حرثكم أنى شئتم وقدموا لأنفسكم واتقوا الله واعلموا أنكم ملاقوه وبشر المؤمنين","aya_tafseer":"[223] نساؤكم موضع زرع لكم، تضعون النطفة في أرحامهن، فَيَخْرج منها الأولاد بمشيئة الله، فجامعوهن في محل الجماع فقط، وهو القبل بأي كيفية شئتم، وقَدِّموا لأنفسكم أعمالاً صالحة بمراعاة أوامر الله، وخافوا الله، واعلموا أنكم ملاقوه للحساب يوم القيامة. وبشِّر المؤمنين -أيها النبي- بما يُفْرِحهم ويسرُّهم من حسن الجزاء في الآخرة."},{"id":"231","jozz":"2","page":"35","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"14","line_end":"15","aya_no":"224","aya_text":"وَلَا تَجۡعَلُواْ ٱللَّهَ عُرۡضَةٗ لِّأَيۡمَٰنِكُمۡ أَن تَبَرُّواْ وَتَتَّقُواْ وَتُصۡلِحُواْ بَيۡنَ ٱلنَّاسِۚ وَٱللَّهُ سَمِيعٌ عَلِيمٞ","aya_text_emlaey":"ولا تجعلوا الله عرضة لأيمانكم أن تبروا وتتقوا وتصلحوا بين الناس والله سميع عليم","aya_tafseer":"[224] ولا تجعلوا -أيها المسلمون- حلفكم بالله مانعاً لكم من البرِّ وصلة الرحم والتقوى والإصلاح بين الناس: بأن تُدْعَوا إلى فعل شيء منها، فتحتجوا بأنكم أقسمتم بالله ألا تفعلوه، بل على الحالف أن يعدل عن حلفه، ويفعل أعمال البر، ويكفر عن يمينه، ولا يعتاد ذلك. والله سميع لأقوالكم، عليم بجميع أحوالكم."},{"id":"232","jozz":"2","page":"36","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"1","line_end":"2","aya_no":"225","aya_text":"لَّا يُؤَاخِذُكُمُ ٱللَّهُ بِٱللَّغۡوِ فِيٓ أَيۡمَٰنِكُمۡ وَلَٰكِن يُؤَاخِذُكُم بِمَا كَسَبَتۡ قُلُوبُكُمۡۗ وَٱللَّهُ غَفُورٌ حَلِيمٞ","aya_text_emlaey":"لا يؤاخذكم الله باللغو في أيمانكم ولكن يؤاخذكم بما كسبت قلوبكم والله غفور حليم","aya_tafseer":"[225] لا يعاقبكم الله بسبب أيمانكم التي تحلفونها بغير قصد، ولكن يعاقبكم بما قصدَتْه قلوبكم. والله غفور لمن تاب إليه، حليم بمن عصاه حيث لم يعاجله بالعقوبة."},{"id":"233","jozz":"2","page":"36","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"2","line_end":"3","aya_no":"226","aya_text":"لِّلَّذِينَ يُؤۡلُونَ مِن نِّسَآئِهِمۡ تَرَبُّصُ أَرۡبَعَةِ أَشۡهُرٖۖ فَإِن فَآءُو فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ","aya_text_emlaey":"للذين يؤلون من نسائهم تربص أربعة أشهر فإن فاءوا فإن الله غفور رحيم","aya_tafseer":"[226] للذين يحلفون بالله أن لا يجامعوا نساءهم أبداً، أو أكثر من أربعة أشهر، انتظارُ أربعة أشهر، فإن رجعوا قبل فوات الأشهر الأربعة، فإن الله غفور لما وقع منهم من الحلف بسبب رجوعهم، رحيم بهم."},{"id":"234","jozz":"2","page":"36","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"3","line_end":"4","aya_no":"227","aya_text":"وَإِنۡ عَزَمُواْ ٱلطَّلَٰقَ فَإِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٞ","aya_text_emlaey":"وإن عزموا الطلاق فإن الله سميع عليم","aya_tafseer":"[227] وإن عقدوا عزمهم على الطلاق، باستمرارهم في اليمين، وترك الجماع، فإن الله سميع لأقوالهم، عليم بمقاصدهم، وسيجازيهم على ذلك."},{"id":"235","jozz":"2","page":"36","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"4","line_end":"8","aya_no":"228","aya_text":"وَٱلۡمُطَلَّقَٰتُ يَتَرَبَّصۡنَ بِأَنفُسِهِنَّ ثَلَٰثَةَ قُرُوٓءٖۚ وَلَا يَحِلُّ لَهُنَّ أَن يَكۡتُمۡنَ مَا خَلَقَ ٱللَّهُ فِيٓ أَرۡحَامِهِنَّ إِن كُنَّ يُؤۡمِنَّ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۚ وَبُعُولَتُهُنَّ أَحَقُّ بِرَدِّهِنَّ فِي ذَٰلِكَ إِنۡ أَرَادُوٓاْ إِصۡلَٰحٗاۚ وَلَهُنَّ مِثۡلُ ٱلَّذِي عَلَيۡهِنَّ بِٱلۡمَعۡرُوفِۚ وَلِلرِّجَالِ عَلَيۡهِنَّ دَرَجَةٞۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌ","aya_text_emlaey":"والمطلقات يتربصن بأنفسهن ثلاثة قروء ولا يحل لهن أن يكتمن ما خلق الله في أرحامهن إن كن يؤمن بالله واليوم الآخر وبعولتهن أحق بردهن في ذلك إن أرادوا إصلاحا ولهن مثل الذي عليهن بالمعروف وللرجال عليهن درجة والله عزيز حكيم","aya_tafseer":"[228] والمطلقات ذوات الحيض، يجب أن ينتظرن دون نكاح بعد الطلاق مدة ثلاثة أطهار أو ثلاث حيضات على سبيل العدة؛ ليتأكدن من فراغ الرحم من الحمل. ولا يجوز لهن تزوج رجل آخر في أثناء هذه العدة حتى تنتهي. ولا يحل لهن أن يخفين ما خلق الله في أرحامهن من الحمل أو الحيض، إن كانت المطلقات مؤمنات حقّاً بالله واليوم الآخر. وأزواج المطلقات أحق بمراجعتهن في العدة. وينبغي أن يكون ذلك بقصد الإصلاح والخير، وليس بقصد الإضرار؛ تعذيباً لهن بتطويل العدة. وللنساء حقوق على الأزواج، مثل التي عليهن على الوجه المعروف، وللرجال على النساء منزلة زائدة من حسن الصحبة، والعشرة بالمعروف، والقِوامة على البيت، ومِلْك الطلاق. والله عزيز له العزة القاهرة، حكيم يضع كل شيء في موضعه المناسب."},{"id":"236","jozz":"2","page":"36","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"8","line_end":"13","aya_no":"229","aya_text":"ٱلطَّلَٰقُ مَرَّتَانِۖ فَإِمۡسَاكُۢ بِمَعۡرُوفٍ أَوۡ تَسۡرِيحُۢ بِإِحۡسَٰنٖۗ وَلَا يَحِلُّ لَكُمۡ أَن تَأۡخُذُواْ مِمَّآ ءَاتَيۡتُمُوهُنَّ شَيۡـًٔا إِلَّآ أَن يَخَافَآ أَلَّا يُقِيمَا حُدُودَ ٱللَّهِۖ فَإِنۡ خِفۡتُمۡ أَلَّا يُقِيمَا حُدُودَ ٱللَّهِ فَلَا جُنَاحَ عَلَيۡهِمَا فِيمَا ٱفۡتَدَتۡ بِهِۦۗ تِلۡكَ حُدُودُ ٱللَّهِ فَلَا تَعۡتَدُوهَاۚ وَمَن يَتَعَدَّ حُدُودَ ٱللَّهِ فَأُوْلَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ","aya_text_emlaey":"الطلاق مرتان فإمساك بمعروف أو تسريح بإحسان ولا يحل لكم أن تأخذوا مما آتيتموهن شيئا إلا أن يخافا ألا يقيما حدود الله فإن خفتم ألا يقيما حدود الله فلا جناح عليهما فيما افتدت به تلك حدود الله فلا تعتدوها ومن يتعد حدود الله فأولئك هم الظالمون","aya_tafseer":"[229] الطلاق الذي تحصل به الرجعة مرتان، واحدة بعد الأخرى، فحكم الله بعد كل طلقة هو إمساك المرأة بالمعروف، وحسن العشرة بعد مراجعتها، أو تخلية سبيلها مع حسن معاملتها بأداء حقوقها، وألَّا يذكرها مطلقها بسوء. ولا يحل لكم -أيها الأزواج- أن تأخذوا شيئاً مما أعطيتموهن من المهر ونحوه، إلا أن يخاف الزوجان ألا يقوما بالحقوق الزوجية، فحينئذ يَعْرضان أمرهما على الأولياء، فإن خاف الأولياء عدم إقامة الزوجين حدود الله، فلا حرج على الزوجين فيما تدفعه المرأة للزوج مقابل طلاقها. تلك الأحكام هي حدود الله الفاصلة بين الحلال والحرام، فلا تتجاوزوها، ومن يتجاوز حدود الله تعالى فأولئك هم الظالمون أنفسَهم بتعريضها لعذاب الله."},{"id":"237","jozz":"2","page":"36","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"13","line_end":"15","aya_no":"230","aya_text":"فَإِن طَلَّقَهَا فَلَا تَحِلُّ لَهُۥ مِنۢ بَعۡدُ حَتَّىٰ تَنكِحَ زَوۡجًا غَيۡرَهُۥۗ فَإِن طَلَّقَهَا فَلَا جُنَاحَ عَلَيۡهِمَآ أَن يَتَرَاجَعَآ إِن ظَنَّآ أَن يُقِيمَا حُدُودَ ٱللَّهِۗ وَتِلۡكَ حُدُودُ ٱللَّهِ يُبَيِّنُهَا لِقَوۡمٖ يَعۡلَمُونَ","aya_text_emlaey":"فإن طلقها فلا تحل له من بعد حتى تنكح زوجا غيره فإن طلقها فلا جناح عليهما أن يتراجعا إن ظنا أن يقيما حدود الله وتلك حدود الله يبينها لقوم يعلمون","aya_tafseer":"[230] فإن طلَّق الرجل زوجته الطلقة الثالثة، فلا تحلُّ له إلا إذا تزوجت رجلاً غيره زواجاً صحيحاً وجامعها فيه، ويكون الزواج عن رغبة، لا بنية تحليل المرأة لزوجها الأول، فإن طلقها الزوج الآخر أو مات عنها وانقضت عدتها، فلا إثم على المرأة وزوجها الأول أن يتزوجا بعقد جديد، ومهر جديد، إن غلب على ظنهما أن يقيما أحكام الله التي شرعها للزوجين. وتلك أحكام الله المحددة يبينها لقوم يعلمون أحكامه وحدوده؛ لأنهم المنتفعون بها."},{"id":"238","jozz":"2","page":"37","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"1","line_end":"5","aya_no":"231","aya_text":"وَإِذَا طَلَّقۡتُمُ ٱلنِّسَآءَ فَبَلَغۡنَ أَجَلَهُنَّ فَأَمۡسِكُوهُنَّ بِمَعۡرُوفٍ أَوۡ سَرِّحُوهُنَّ بِمَعۡرُوفٖۚ وَلَا تُمۡسِكُوهُنَّ ضِرَارٗا لِّتَعۡتَدُواْۚ وَمَن يَفۡعَلۡ ذَٰلِكَ فَقَدۡ ظَلَمَ نَفۡسَهُۥۚ وَلَا تَتَّخِذُوٓاْ ءَايَٰتِ ٱللَّهِ هُزُوٗاۚ وَٱذۡكُرُواْ نِعۡمَتَ ٱللَّهِ عَلَيۡكُمۡ وَمَآ أَنزَلَ عَلَيۡكُم مِّنَ ٱلۡكِتَٰبِ وَٱلۡحِكۡمَةِ يَعِظُكُم بِهِۦۚ وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ بِكُلِّ شَيۡءٍ عَلِيمٞ","aya_text_emlaey":"وإذا طلقتم النساء فبلغن أجلهن فأمسكوهن بمعروف أو سرحوهن بمعروف ولا تمسكوهن ضرارا لتعتدوا ومن يفعل ذلك فقد ظلم نفسه ولا تتخذوا آيات الله هزوا واذكروا نعمة الله عليكم وما أنـزل عليكم من الكتاب والحكمة يعظكم به واتقوا الله واعلموا أن الله بكل شيء عليم","aya_tafseer":"[231] وإذا طَلَّقتم النساء فقاربن انتهاء عدتهن، فراجعوهن، ونيتكم القيام بحقوقهن على الوجه المستحسن شرعاً وعرفاً، أو اتركوهن حتى تنقضي عدتهن. واحذروا أن تكون مراجعتهن بقصد الإضرار بهن لأجل الاعتداء على حقوقهن. ومن يفعل ذلك فقد ظلم نفسه باستحقاقه العقوبة، ولا تتخذوا آياتِ الله وأحكامَه لعباً ولهواً. واذكروا نعمة الله عليكم بالإسلام وتفصيل الأحكام. واذكروا ما أنزل الله عليكم من القرآن والسنة، واشكروا له سبحانه على هذه النعم الجليلة، يُذكِّركم الله بهذا، ويخوفكم من المخالفة، فخافوا الله وراقبوه، واعلموا أن الله عليم بكل شيء، لا يخفى عليه شيء، وسيجازي كُلّاً بما يستحق."},{"id":"239","jozz":"2","page":"37","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"5","line_end":"9","aya_no":"232","aya_text":"وَإِذَا طَلَّقۡتُمُ ٱلنِّسَآءَ فَبَلَغۡنَ أَجَلَهُنَّ فَلَا تَعۡضُلُوهُنَّ أَن يَنكِحۡنَ أَزۡوَٰجَهُنَّ إِذَا تَرَٰضَوۡاْ بَيۡنَهُم بِٱلۡمَعۡرُوفِۗ ذَٰلِكَ يُوعَظُ بِهِۦ مَن كَانَ مِنكُمۡ يُؤۡمِنُ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۗ ذَٰلِكُمۡ أَزۡكَىٰ لَكُمۡ وَأَطۡهَرُۚ وَٱللَّهُ يَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ","aya_text_emlaey":"وإذا طلقتم النساء فبلغن أجلهن فلا تعضلوهن أن ينكحن أزواجهن إذا تراضوا بينهم بالمعروف ذلك يوعظ به من كان منكم يؤمن بالله واليوم الآخر ذلكم أزكى لكم وأطهر والله يعلم وأنتم لا تعلمون","aya_tafseer":"[232] وإذا طلَّقتم نساءكم دون الثلاث وانتهت عدتهن من غير مراجعة لهن، فلا تضيقوا -أيها الأولياء- على المطلقات بمنعهن من العودة إلى أزواجهن بعقد جديد إذا أردن ذلك، وحدث التراضي شرعاً وعرفاً. ذلك يوعظ به من كان منكم صادق الإيمان بالله واليوم الآخر. إنَّ تَرْكَ العضل وتمكين الأزواج من نكاح زوجاتهم أكثر نماء وطهارة لأعراضكم، وأعظم منفعة وثواباً لكم. والله يعلم ما فيه صلاحكم وأنتم لا تعلمون ذلك."},{"id":"240","jozz":"2","page":"37","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"9","line_end":"15","aya_no":"233","aya_text":"۞ وَٱلۡوَٰلِدَٰتُ يُرۡضِعۡنَ أَوۡلَٰدَهُنَّ حَوۡلَيۡنِ كَامِلَيۡنِۖ لِمَنۡ أَرَادَ أَن يُتِمَّ ٱلرَّضَاعَةَۚ وَعَلَى ٱلۡمَوۡلُودِ لَهُۥ رِزۡقُهُنَّ وَكِسۡوَتُهُنَّ بِٱلۡمَعۡرُوفِۚ لَا تُكَلَّفُ نَفۡسٌ إِلَّا وُسۡعَهَاۚ لَا تُضَآرَّ وَٰلِدَةُۢ بِوَلَدِهَا وَلَا مَوۡلُودٞ لَّهُۥ بِوَلَدِهِۦۚ وَعَلَى ٱلۡوَارِثِ مِثۡلُ ذَٰلِكَۗ فَإِنۡ أَرَادَا فِصَالًا عَن تَرَاضٖ مِّنۡهُمَا وَتَشَاوُرٖ فَلَا جُنَاحَ عَلَيۡهِمَاۗ وَإِنۡ أَرَدتُّمۡ أَن تَسۡتَرۡضِعُوٓاْ أَوۡلَٰدَكُمۡ فَلَا جُنَاحَ عَلَيۡكُمۡ إِذَا سَلَّمۡتُم مَّآ ءَاتَيۡتُم بِٱلۡمَعۡرُوفِۗ وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ بِمَا تَعۡمَلُونَ بَصِيرٞ","aya_text_emlaey":"والوالدات يرضعن أولادهن حولين كاملين لمن أراد أن يتم الرضاعة وعلى المولود له رزقهن وكسوتهن بالمعروف لا تكلف نفس إلا وسعها لا تضار والدة بولدها ولا مولود له بولده وعلى الوارث مثل ذلك فإن أرادا فصالا عن تراض منهما وتشاور فلا جناح عليهما وإن أردتم أن تسترضعوا أولادكم فلا جناح عليكم إذا سلمتم ما آتيتم بالمعروف واتقوا الله واعلموا أن الله بما تعملون بصير","aya_tafseer":"[233] وعلى الوالدات إرضاع أولادهن مدة سنتين كاملتين لمن أراد إتمام الرضاعة، ويجب على الآباء أن يكفُلوا للمرضعات المطلقات طعامهن وكسوتهن، على الوجه المستحسن شرعاً وعرفاً؛ لأن الله لا يكلف نفساً إلا قدر طاقتها، ولا يحل للوالدين أن يجعلوا المولود وسيلة للمضارة بينهما، ويجب على الوارث عند موت الوالد مثل ما يجب على الوالد قبل موته من النفقة والكسوة. فإن أراد الوالدان فطام المولود قبل انتهاء السنتين فلا حرج عليهما إذا تراضيا وتشاورا في ذلك؛ ليصلا إلى ما فيه مصلحة المولود. وإن اتفق الوالدان على إرضاع المولود من مرضعة أخرى غير والدته فلا حرج عليهما، إذا سلَّم الوالد للأم حقَّها، وسلَّم للمرضعة أجرها بما يتعارفه الناس. وخافوا الله في جميع أحوالكم، واعلموا أن الله بما تعملون بصير، وسيجازيكم على ذلك."},{"id":"241","jozz":"2","page":"38","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"1","line_end":"3","aya_no":"234","aya_text":"وَٱلَّذِينَ يُتَوَفَّوۡنَ مِنكُمۡ وَيَذَرُونَ أَزۡوَٰجٗا يَتَرَبَّصۡنَ بِأَنفُسِهِنَّ أَرۡبَعَةَ أَشۡهُرٖ وَعَشۡرٗاۖ فَإِذَا بَلَغۡنَ أَجَلَهُنَّ فَلَا جُنَاحَ عَلَيۡكُمۡ فِيمَا فَعَلۡنَ فِيٓ أَنفُسِهِنَّ بِٱلۡمَعۡرُوفِۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرٞ","aya_text_emlaey":"والذين يتوفون منكم ويذرون أزواجا يتربصن بأنفسهن أربعة أشهر وعشرا فإذا بلغن أجلهن فلا جناح عليكم فيما فعلن في أنفسهن بالمعروف والله بما تعملون خبير","aya_tafseer":"[234] والذين يموتون منكم، ويتركون زوجات بعدهم، يجب عليهن الانتظار بأنفسهن مدة أربعة أشهر وعشرة أيام، لا يخرجن من منزل الزوجية، ولا يتزيَّنَّ، ولا يتزوجن، فإذا انتهت المدة المذكورة فلا إثم عليكم يا أولياء النساء فيما يفعلن في أنفسهن من الخروج، والتزين، والزواج على الوجه المقرر شرعاً. والله سبحانه وتعالى خبير بأعمالكم ظاهرها وباطنها، وسيجازيكم عليها."},{"id":"242","jozz":"2","page":"38","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"4","line_end":"9","aya_no":"235","aya_text":"وَلَا جُنَاحَ عَلَيۡكُمۡ فِيمَا عَرَّضۡتُم بِهِۦ مِنۡ خِطۡبَةِ ٱلنِّسَآءِ أَوۡ أَكۡنَنتُمۡ فِيٓ أَنفُسِكُمۡۚ عَلِمَ ٱللَّهُ أَنَّكُمۡ سَتَذۡكُرُونَهُنَّ وَلَٰكِن لَّا تُوَاعِدُوهُنَّ سِرًّا إِلَّآ أَن تَقُولُواْ قَوۡلٗا مَّعۡرُوفٗاۚ وَلَا تَعۡزِمُواْ عُقۡدَةَ ٱلنِّكَاحِ حَتَّىٰ يَبۡلُغَ ٱلۡكِتَٰبُ أَجَلَهُۥۚ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ يَعۡلَمُ مَا فِيٓ أَنفُسِكُمۡ فَٱحۡذَرُوهُۚ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ غَفُورٌ حَلِيمٞ","aya_text_emlaey":"ولا جناح عليكم فيما عرضتم به من خطبة النساء أو أكننتم في أنفسكم علم الله أنكم ستذكرونهن ولكن لا تواعدوهن سرا إلا أن تقولوا قولا معروفا ولا تعزموا عقدة النكاح حتى يبلغ الكتاب أجله واعلموا أن الله يعلم ما في أنفسكم فاحذروه واعلموا أن الله غفور حليم","aya_tafseer":"[235] ولا إثم عليكم -أيها الرجال- فيما تُلَمِّحون به مِن طلب الزواج بالنساء المتوفَّى عنهنَّ أزواجهن، أو المطلقات طلاقاً بائناً في أثناء عدتهن، ولا ذنب عليكم أيضاً فيما أضمرتموه في أنفسكم من نية الزواج بهن بعد انتهاء عدتهن. علم الله أنكم ستذكرون النساء المعتدَّات، ولن تصبروا على السكوت عنهن، لضعفكم؛ لذلك أباح لكم أن تذكروهن تلميحاً أو إضماراً في النفس، واحذروا أن تواعدوهن على النكاح سرّاً بالزنى أو الاتفاق على الزواج في أثناء العدة، إلا أن تقولوا قولاً يُفْهَم منه أن مثلها يَرْغب فيها الأزواج، ولا تعزموا على عقد النكاح في زمان العدة حتى تنقضي مدتها. واعلموا أن الله يعلم ما في أنفسكم فخافوه، واعلموا أن الله غفور لمن تاب من ذنوبه، حليم على عباده لا يعجل عليهم بالعقوبة."},{"id":"243","jozz":"2","page":"38","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"9","line_end":"12","aya_no":"236","aya_text":"لَّا جُنَاحَ عَلَيۡكُمۡ إِن طَلَّقۡتُمُ ٱلنِّسَآءَ مَا لَمۡ تَمَسُّوهُنَّ أَوۡ تَفۡرِضُواْ لَهُنَّ فَرِيضَةٗۚ وَمَتِّعُوهُنَّ عَلَى ٱلۡمُوسِعِ قَدَرُهُۥ وَعَلَى ٱلۡمُقۡتِرِ قَدَرُهُۥ مَتَٰعَۢا بِٱلۡمَعۡرُوفِۖ حَقًّا عَلَى ٱلۡمُحۡسِنِينَ","aya_text_emlaey":"لا جناح عليكم إن طلقتم النساء ما لم تمسوهن أو تفرضوا لهن فريضة ومتعوهن على الموسع قدره وعلى المقتر قدره متاعا بالمعروف حقا على المحسنين","aya_tafseer":"[236] لا إثم عليكم -أيها الأزواج- إن طلقتم النساء بعد العقد عليهن، وقبل أن تجامعوهن، أو تحددوا مهراً لهن، ومتِّعوهن بشيء ينتفعن به جبراً لهن، ودفعاً لوحشة الطلاق، وإزالة للأحقاد. وهذه المتعة تجب بحسب حال الرجل المطلِّق: على الغني قَدْر سَعَة رزقه، وعلى الفقير قَدْر ما يملكه، متاعاً على الوجه المعروف شرعاً، وهو حق ثابت على الذين يحسنون إلى المطلقات وإلى أنفسهم بطاعة الله."},{"id":"244","jozz":"2","page":"38","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"12","line_end":"15","aya_no":"237","aya_text":"وَإِن طَلَّقۡتُمُوهُنَّ مِن قَبۡلِ أَن تَمَسُّوهُنَّ وَقَدۡ فَرَضۡتُمۡ لَهُنَّ فَرِيضَةٗ فَنِصۡفُ مَا فَرَضۡتُمۡ إِلَّآ أَن يَعۡفُونَ أَوۡ يَعۡفُوَاْ ٱلَّذِي بِيَدِهِۦ عُقۡدَةُ ٱلنِّكَاحِۚ وَأَن تَعۡفُوٓاْ أَقۡرَبُ لِلتَّقۡوَىٰۚ وَلَا تَنسَوُاْ ٱلۡفَضۡلَ بَيۡنَكُمۡۚ إِنَّ ٱللَّهَ بِمَا تَعۡمَلُونَ بَصِيرٌ","aya_text_emlaey":"وإن طلقتموهن من قبل أن تمسوهن وقد فرضتم لهن فريضة فنصف ما فرضتم إلا أن يعفون أو يعفو الذي بيده عقدة النكاح وأن تعفوا أقرب للتقوى ولا تنسوا الفضل بينكم إن الله بما تعملون بصير","aya_tafseer":"[237] وإن طلَّقتم النساء بعد العقد عليهن، ولم تجامعوهن، ولكنكم ألزمتم أنفسكم بمهر محدد لهن، فيجب عليكم أن تعطوهن نصف المهر المتفق عليه، إلا أنْ تُسامِح المطلقات، فيتركن نصف المهر المستحق لهن، أو يسمح الزوج بأن يترك للمطلقة المهر كله، وتسامحكم أيها الرجال والنساء أقرب إلى خشية الله وطاعته، ولا تنسوا -أيها الناس- الفضل والإحسان بينكم، وهو إعطاء ما ليس بواجب عليكم، والتسامح في الحقوق. إن الله بما تعملون بصير، يُرغِّبكم في المعروف، ويحثُّكم على الفضل."},{"id":"245","jozz":"2","page":"39","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"1","line_end":"2","aya_no":"238","aya_text":"حَٰفِظُواْ عَلَى ٱلصَّلَوَٰتِ وَٱلصَّلَوٰةِ ٱلۡوُسۡطَىٰ وَقُومُواْ لِلَّهِ قَٰنِتِينَ","aya_text_emlaey":"حافظوا على الصلوات والصلاة الوسطى وقوموا لله قانتين","aya_tafseer":"[238] حافظوا -أيها المسلمون- على الصلوات الخمس المفروضة بالمداومة على أدائها في أوقاتها بشروطها وأركانها وواجباتها، وحافظوا على الصلاة المتوسطة بينها وهي صلاة العصر، وقوموا في صلاتكم مطيعين لله، خاشعين ذ ليلين."},{"id":"246","jozz":"2","page":"39","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"2","line_end":"3","aya_no":"239","aya_text":"فَإِنۡ خِفۡتُمۡ فَرِجَالًا أَوۡ رُكۡبَانٗاۖ فَإِذَآ أَمِنتُمۡ فَٱذۡكُرُواْ ٱللَّهَ كَمَا عَلَّمَكُم مَّا لَمۡ تَكُونُواْ تَعۡلَمُونَ","aya_text_emlaey":"فإن خفتم فرجالا أو ركبانا فإذا أمنتم فاذكروا الله كما علمكم ما لم تكونوا تعلمون","aya_tafseer":"[239] فإن خفتم من عَدوٍّ لكم فصلُّوا صلاة الخوف ماشين، أو راكبين، على أي هيئة تستطيعونها ولو بالإيماء، أو إلى غير جهة القبلة، فإذا زال خوفكم فصلُّوا صلاة الأمن، واذكروا الله فيها، ولا تنقصوها عن هيئتها الأصلية، واشكروا له على ما علَّمكم من أمور العبادات والأحكام ما لم تكونوا على علم به."},{"id":"247","jozz":"2","page":"39","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"4","line_end":"7","aya_no":"240","aya_text":"وَٱلَّذِينَ يُتَوَفَّوۡنَ مِنكُمۡ وَيَذَرُونَ أَزۡوَٰجٗا وَصِيَّةٗ لِّأَزۡوَٰجِهِم مَّتَٰعًا إِلَى ٱلۡحَوۡلِ غَيۡرَ إِخۡرَاجٖۚ فَإِنۡ خَرَجۡنَ فَلَا جُنَاحَ عَلَيۡكُمۡ فِي مَا فَعَلۡنَ فِيٓ أَنفُسِهِنَّ مِن مَّعۡرُوفٖۗ وَٱللَّهُ عَزِيزٌ حَكِيمٞ","aya_text_emlaey":"والذين يتوفون منكم ويذرون أزواجا وصية لأزواجهم متاعا إلى الحول غير إخراج فإن خرجن فلا جناح عليكم في ما فعلن في أنفسهن من معروف والله عزيز حكيم","aya_tafseer":"[240] والأزواج الذين يموتون ويتركون زوجات بعدهم، فلْيوصوا وصيةً لهنَّ: أن يُمَتَّعن سنة تامة من يوم الوفاة، بالسكنى في منزل الزوج من غير إخراج الورثة لهن مدة السنة؛ جبراً لخاطر الزوجة، وبرّاً بالمتوفَّى. فإن خرجت الزوجات باختيارهن قبل انقضاء السنة، فلا إثم عليكم -أيها الورثة- في ذلك، ولا حرج على الزوجات فيما فعلن في أنفسهن من أمور مباحة. والله عزيز في ملكه، حكيم في أمره ونهيه. وهذه الآية منسوخة بقوله تعالى: وَٱلَّذِينَ يُتَوَفَّوۡنَ مِنكُمۡ وَيَذَرُونَ أَزۡوَٰجٗا يَتَرَبَّصۡنَ بِأَنفُسِهِنَّ أَرۡبَعَةَ أَشۡهُرٖ وَعَشۡرٗاۖ."},{"id":"248","jozz":"2","page":"39","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"7","line_end":"8","aya_no":"241","aya_text":"وَلِلۡمُطَلَّقَٰتِ مَتَٰعُۢ بِٱلۡمَعۡرُوفِۖ حَقًّا عَلَى ٱلۡمُتَّقِينَ","aya_text_emlaey":"وللمطلقات متاع بالمعروف حقا على المتقين","aya_tafseer":"[241] وللمطلقات متاع من كسوة ونفقة على الوجه المعروف المستحسن شرعاً، حقّاً على الذين يخافون الله ويتقونه في أمره ونهيه."},{"id":"249","jozz":"2","page":"39","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"8","line_end":"9","aya_no":"242","aya_text":"كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمۡ ءَايَٰتِهِۦ لَعَلَّكُمۡ تَعۡقِلُونَ","aya_text_emlaey":"كذلك يبين الله لكم آياته لعلكم تعقلون","aya_tafseer":"[242] مثل ذلك البيان الواضح في أحكام الأولاد والنساء، يبيِّن الله لكم آياته وأحكامه في كل ما تحتاجون إليه في معاشكم ومعادكم؛ لكي تعقلوها وتعملوا بها."},{"id":"250","jozz":"2","page":"39","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"9","line_end":"12","aya_no":"243","aya_text":"۞ أَلَمۡ تَرَ إِلَى ٱلَّذِينَ خَرَجُواْ مِن دِيَٰرِهِمۡ وَهُمۡ أُلُوفٌ حَذَرَ ٱلۡمَوۡتِ فَقَالَ لَهُمُ ٱللَّهُ مُوتُواْ ثُمَّ أَحۡيَٰهُمۡۚ إِنَّ ٱللَّهَ لَذُو فَضۡلٍ عَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَشۡكُرُونَ","aya_text_emlaey":"ألم تر إلى الذين خرجوا من ديارهم وهم ألوف حذر الموت فقال لهم الله موتوا ثم أحياهم إن الله لذو فضل على الناس ولكن أكثر الناس لا يشكرون","aya_tafseer":"[243] ألم تعلم -أيها الرسول- قصة الذين فرُّوا من أرضهم ومنازلهم، وهم ألوف كثيرة؛ خشية الموت من الطاعون أو القتال، فقال لهم الله: موتوا، فماتوا دفعة واحدة عقوبة على فرارهم من قدر الله، ثم أحياهم الله تعالى بعد مدة؛ ليستوفوا آجالهم، وليتعظوا ويتوبوا؟ إن الله لذو فضل عظيم على الناس بنعمه الكثيرة، ولكن أكثر الناس لا يشكرون فضل الله عليهم."},{"id":"251","jozz":"2","page":"39","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"13","line_end":"13","aya_no":"244","aya_text":"وَقَٰتِلُواْ فِي سَبِيلِ ٱللَّهِ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ سَمِيعٌ عَلِيمٞ","aya_text_emlaey":"وقاتلوا في سبيل الله واعلموا أن الله سميع عليم","aya_tafseer":"[244] وقاتلوا -أيها المسلمون- الكفار لنصرة دين الله، واعلموا أن الله سميع لأقوالكم، عليم بنيَّاتكم وأعمالكم."},{"id":"252","jozz":"2","page":"39","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"13","line_end":"15","aya_no":"245","aya_text":"مَّن ذَا ٱلَّذِي يُقۡرِضُ ٱللَّهَ قَرۡضًا حَسَنٗا فَيُضَٰعِفَهُۥ لَهُۥٓ أَضۡعَافٗا كَثِيرَةٗۚ وَٱللَّهُ يَقۡبِضُ وَيَبۡصُۜطُ وَإِلَيۡهِ تُرۡجَعُونَ","aya_text_emlaey":"من ذا الذي يقرض الله قرضا حسنا فيضاعفه له أضعافا كثيرة والله يقبض ويبسط وإليه ترجعون","aya_tafseer":"[245] من ذا الذي ينفق في سبيل الله إنفاقاً حسناً احتساباً للأجر، فيضاعفه له أضعافاً كثيرة لا تحصى من الثواب وحسن الجزاء؟ والله يقبض ويبسط، فأنفقوا ولا تبالوا؛ فإنه هو الرزاق، يُضيِّق على مَن يشاء مِن عباده في الرزق، ويوسعه على آخرين، له الحكمة البالغة في ذلك، وإليه وحده ترجعون بعد الموت، فيجازيكم على أعمالكم."},{"id":"253","jozz":"2","page":"40","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"1","line_end":"6","aya_no":"246","aya_text":"أَلَمۡ تَرَ إِلَى ٱلۡمَلَإِ مِنۢ بَنِيٓ إِسۡرَٰٓءِيلَ مِنۢ بَعۡدِ مُوسَىٰٓ إِذۡ قَالُواْ لِنَبِيّٖ لَّهُمُ ٱبۡعَثۡ لَنَا مَلِكٗا نُّقَٰتِلۡ فِي سَبِيلِ ٱللَّهِۖ قَالَ هَلۡ عَسَيۡتُمۡ إِن كُتِبَ عَلَيۡكُمُ ٱلۡقِتَالُ أَلَّا تُقَٰتِلُواْۖ قَالُواْ وَمَا لَنَآ أَلَّا نُقَٰتِلَ فِي سَبِيلِ ٱللَّهِ وَقَدۡ أُخۡرِجۡنَا مِن دِيَٰرِنَا وَأَبۡنَآئِنَاۖ فَلَمَّا كُتِبَ عَلَيۡهِمُ ٱلۡقِتَالُ تَوَلَّوۡاْ إِلَّا قَلِيلٗا مِّنۡهُمۡۚ وَٱللَّهُ عَلِيمُۢ بِٱلظَّٰلِمِينَ","aya_text_emlaey":"ألم تر إلى الملإ من بني إسرائيل من بعد موسى إذ قالوا لنبي لهم ابعث لنا ملكا نقاتل في سبيل الله قال هل عسيتم إن كتب عليكم القتال ألا تقاتلوا قالوا وما لنا ألا نقاتل في سبيل الله وقد أخرجنا من ديارنا وأبنائنا فلما كتب عليهم القتال تولوا إلا قليلا منهم والله عليم بالظالمين","aya_tafseer":"[246] ألم تعلم -أيها الرسول- قصة الأشراف والوجهاء من بني إسرائيل من بعد زمان موسى؟ حين طلبوا مِن نبيهم أن يولي عليهم مَلِكاً، يجتمعون تحت قيادته، ويقاتلون أعداءهم في سبيل الله. قال لهم نبيهم: هل الأمر كما أتوقعه إنْ فُرِض عليكم القتال في سبيل الله أنكم لا تقاتلون؟ فإني أتوقع جُبْنكم وفراركم من القتال، قالوا مستنكرين توقع نبيهم: وأي مانع يمنعنا عن القتال في سبيل الله، وقد أَخْرَجَنَا عدوُّنا مِن ديارنا، وأبعدنا عن أولادنا بالقتل والأسر؟ فلما فرض الله عليهم القتال مع المَلِك الذي عَيَّنه لهم جَبُنوا وفرُّوا عن القتال، إلا قليلاً منهم ثبتوا بفضل الله. والله عليم بالظالمين الناكثين عهودهم."},{"id":"254","jozz":"2","page":"40","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"6","line_end":"11","aya_no":"247","aya_text":"وَقَالَ لَهُمۡ نَبِيُّهُمۡ إِنَّ ٱللَّهَ قَدۡ بَعَثَ لَكُمۡ طَالُوتَ مَلِكٗاۚ قَالُوٓاْ أَنَّىٰ يَكُونُ لَهُ ٱلۡمُلۡكُ عَلَيۡنَا وَنَحۡنُ أَحَقُّ بِٱلۡمُلۡكِ مِنۡهُ وَلَمۡ يُؤۡتَ سَعَةٗ مِّنَ ٱلۡمَالِۚ قَالَ إِنَّ ٱللَّهَ ٱصۡطَفَىٰهُ عَلَيۡكُمۡ وَزَادَهُۥ بَسۡطَةٗ فِي ٱلۡعِلۡمِ وَٱلۡجِسۡمِۖ وَٱللَّهُ يُؤۡتِي مُلۡكَهُۥ مَن يَشَآءُۚ وَٱللَّهُ وَٰسِعٌ عَلِيمٞ","aya_text_emlaey":"وقال لهم نبيهم إن الله قد بعث لكم طالوت ملكا قالوا أنى يكون له الملك علينا ونحن أحق بالملك منه ولم يؤت سعة من المال قال إن الله اصطفاه عليكم وزاده بسطة في العلم والجسم والله يؤتي ملكه من يشاء والله واسع عليم","aya_tafseer":"[247] وقال لهم نبيهم: إن الله قد أرسل إليكم طالوت مَلِكاً إجابة لطلبكم، يقودكم لقتال عدوكم كما طلبتم. قال كبراء بني إسرائيل: كيف يكون طالوت مَلِكاً علينا، وهو لا يستحق ذلك؟ لأنه ليس من سِبْط الملوك، ولا من بيت النبوة، ولم يُعْط كثرة في الأموال يستعين بها في ملكه، فنحن أحق بالملك منه؛ لأننا من سِبْط الملوك ومن بيت النبوة. قال لهم نبيهم: إن الله اختاره عليكم وهو سبحانه أعلم بأمور عباده، وزاده سَعَة في العلم وقوة في الجسم ليجاهد العدو. والله مالك الملك يعطي ملكه مَن يشاء من عباده، والله واسع الفضل والعطاء، عليم بحقائق الأمور، لا يخفى عليه شيء."},{"id":"255","jozz":"2","page":"40","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"12","line_end":"15","aya_no":"248","aya_text":"وَقَالَ لَهُمۡ نَبِيُّهُمۡ إِنَّ ءَايَةَ مُلۡكِهِۦٓ أَن يَأۡتِيَكُمُ ٱلتَّابُوتُ فِيهِ سَكِينَةٞ مِّن رَّبِّكُمۡ وَبَقِيَّةٞ مِّمَّا تَرَكَ ءَالُ مُوسَىٰ وَءَالُ هَٰرُونَ تَحۡمِلُهُ ٱلۡمَلَٰٓئِكَةُۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لَّكُمۡ إِن كُنتُم مُّؤۡمِنِينَ","aya_text_emlaey":"وقال لهم نبيهم إن آية ملكه أن يأتيكم التابوت فيه سكينة من ربكم وبقية مما ترك آل موسى وآل هارون تحمله الملائكة إن في ذلك لآية لكم إن كنتم مؤمنين","aya_tafseer":"[248] وقال لهم نبيهم: إن علامة ملكه أن يأتيكم الصندوق الذي فيه التوراة -وكان أعداؤهم قد انتزعوه منهم- فيه طمأنينة من ربكم تثبت قلوب المخلصين، وفيه بقية من بعض أشياء تركها آل موسى وآل هارون، مثل العصا وفُتات الألواح تحمله الملائكة. إن في ذلك لأعظم برهان لكم على اختيار طالوت ملكاً عليكم بأمر الله، إن كنتم مصدقين بالله ورسله."},{"id":"256","jozz":"2","page":"41","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"1","line_end":"8","aya_no":"249","aya_text":"فَلَمَّا فَصَلَ طَالُوتُ بِٱلۡجُنُودِ قَالَ إِنَّ ٱللَّهَ مُبۡتَلِيكُم بِنَهَرٖ فَمَن شَرِبَ مِنۡهُ فَلَيۡسَ مِنِّي وَمَن لَّمۡ يَطۡعَمۡهُ فَإِنَّهُۥ مِنِّيٓ إِلَّا مَنِ ٱغۡتَرَفَ غُرۡفَةَۢ بِيَدِهِۦۚ فَشَرِبُواْ مِنۡهُ إِلَّا قَلِيلٗا مِّنۡهُمۡۚ فَلَمَّا جَاوَزَهُۥ هُوَ وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ قَالُواْ لَا طَاقَةَ لَنَا ٱلۡيَوۡمَ بِجَالُوتَ وَجُنُودِهِۦۚ قَالَ ٱلَّذِينَ يَظُنُّونَ أَنَّهُم مُّلَٰقُواْ ٱللَّهِ كَم مِّن فِئَةٖ قَلِيلَةٍ غَلَبَتۡ فِئَةٗ كَثِيرَةَۢ بِإِذۡنِ ٱللَّهِۗ وَٱللَّهُ مَعَ ٱلصَّٰبِرِينَ","aya_text_emlaey":"فلما فصل طالوت بالجنود قال إن الله مبتليكم بنهر فمن شرب منه فليس مني ومن لم يطعمه فإنه مني إلا من اغترف غرفة بيده فشربوا منه إلا قليلا منهم فلما جاوزه هو والذين آمنوا معه قالوا لا طاقة لنا اليوم بجالوت وجنوده قال الذين يظنون أنهم ملاقو الله كم من فئة قليلة غلبت فئة كثيرة بإذن الله والله مع الصابرين","aya_tafseer":"[249] فلما خرج طالوت بجنوده لقتال العمالقة قال لهم: إن الله ممتحنكم على الصبر بنهر أمامكم تعبرونه؛ ليتميَّز المؤمن من المنافق، فمن شرب منكم من ماء النهر فليس من أهل ديني، ولا يصلح للجهاد معي، ومن لم يذق الماء فإنه مني؛ لأنه مطيع لأمري وصالح للجهاد، إلا مَن ترخَّص واغترف غُرْفة واحدة بيده فلا لوم عليه. فلما وصلوا إلى النهر انكبوا على الماء، وأفرطوا في الشرب منه، إلا عدداً قليلاً منهم صبروا على العطش والحر، واكتفوا بغُرْفة اليد، وحينئذ تخلَّف العصاة. ولما عبر طالوت النهر هو والقلة المؤمنة معه -وهم ثلاثمائة وبضعة عشر رجلاً- لملاقاة العدو، ورأوا كثرة عدوهم وعدَّتهم، قالوا: لا قدرة لنا اليوم بجالوت وجنوده الأشداء، فأجاب الذين يوقنون بلقاء الله، يُذَكِّرون إخوانهم بالله وقدرته قائلين: كم من جماعة قليلة مؤمنة صابرة، غلبت - بإذن الله وأمره - جماعة كثيرة كافرة باغية. والله مع الصابرين بتوفيقه ونصره، وحسن مثوبته."},{"id":"257","jozz":"2","page":"41","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"8","line_end":"10","aya_no":"250","aya_text":"وَلَمَّا بَرَزُواْ لِجَالُوتَ وَجُنُودِهِۦ قَالُواْ رَبَّنَآ أَفۡرِغۡ عَلَيۡنَا صَبۡرٗا وَثَبِّتۡ أَقۡدَامَنَا وَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ","aya_text_emlaey":"ولما برزوا لجالوت وجنوده قالوا ربنا أفرغ علينا صبرا وثبت أقدامنا وانصرنا على القوم الكافرين","aya_tafseer":"[250] ولما ظهروا لجالوت وجنوده، ورأوا الخطر رأي العين، فزعوا إلى الله بالدعاء والضراعة قائلين: ربنا أنزل على قلوبنا صبراً عظيماً، وثبِّت أقدامنا، واجعلها راسخة في قتال العدو، لا تَفِرُّ مِن هول الحرب، وانصرنا بعونك وتأييدك على القوم الكافرين."},{"id":"258","jozz":"2","page":"41","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"10","line_end":"14","aya_no":"251","aya_text":"فَهَزَمُوهُم بِإِذۡنِ ٱللَّهِ وَقَتَلَ دَاوُۥدُ جَالُوتَ وَءَاتَىٰهُ ٱللَّهُ ٱلۡمُلۡكَ وَٱلۡحِكۡمَةَ وَعَلَّمَهُۥ مِمَّا يَشَآءُۗ وَلَوۡلَا دَفۡعُ ٱللَّهِ ٱلنَّاسَ بَعۡضَهُم بِبَعۡضٖ لَّفَسَدَتِ ٱلۡأَرۡضُ وَلَٰكِنَّ ٱللَّهَ ذُو فَضۡلٍ عَلَى ٱلۡعَٰلَمِينَ","aya_text_emlaey":"فهزموهم بإذن الله وقتل داود جالوت وآتاه الله الملك والحكمة وعلمه مما يشاء ولولا دفع الله الناس بعضهم ببعض لفسدت الأرض ولكن الله ذو فضل على العالمين","aya_tafseer":"[251] فهزموهم بإذن الله، وقتل داودُ -عليه السلام- جالوتَ قائدَ الجبابرة، وأعطى الله عز وجل داود - بعد ذلك - الملك والنبوة في بني إسرائيل، وعَلَّمه مما يشاء من العلوم. ولولا أن يدفع الله ببعض الناس -وهم أهل الطاعة له والإيمانِ به- بعضاً، وهم أهل المعصية لله والشركِ به، لفسدت الأرض بغلبة الكفر، وتمكُّن الطغيان، وأهلِ المعاصي، ولكن الله ذو فضل على المخلوقين جميعاً."},{"id":"259","jozz":"2","page":"41","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"14","line_end":"15","aya_no":"252","aya_text":"تِلۡكَ ءَايَٰتُ ٱللَّهِ نَتۡلُوهَا عَلَيۡكَ بِٱلۡحَقِّۚ وَإِنَّكَ لَمِنَ ٱلۡمُرۡسَلِينَ","aya_text_emlaey":"تلك آيات الله نتلوها عليك بالحق وإنك لمن المرسلين","aya_tafseer":"[252] تلك حجج الله وبراهينه، نقصُّها عليك -أيها النبي- بالصدق، وإنك لمن المرسلين الصادقين."},{"id":"260","jozz":"3","page":"42","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"1","line_end":"6","aya_no":"253","aya_text":"۞ تِلۡكَ ٱلرُّسُلُ فَضَّلۡنَا بَعۡضَهُمۡ عَلَىٰ بَعۡضٖۘ مِّنۡهُم مَّن كَلَّمَ ٱللَّهُۖ وَرَفَعَ بَعۡضَهُمۡ دَرَجَٰتٖۚ وَءَاتَيۡنَا عِيسَى ٱبۡنَ مَرۡيَمَ ٱلۡبَيِّنَٰتِ وَأَيَّدۡنَٰهُ بِرُوحِ ٱلۡقُدُسِۗ وَلَوۡ شَآءَ ٱللَّهُ مَا ٱقۡتَتَلَ ٱلَّذِينَ مِنۢ بَعۡدِهِم مِّنۢ بَعۡدِ مَا جَآءَتۡهُمُ ٱلۡبَيِّنَٰتُ وَلَٰكِنِ ٱخۡتَلَفُواْ فَمِنۡهُم مَّنۡ ءَامَنَ وَمِنۡهُم مَّن كَفَرَۚ وَلَوۡ شَآءَ ٱللَّهُ مَا ٱقۡتَتَلُواْ وَلَٰكِنَّ ٱللَّهَ يَفۡعَلُ مَا يُرِيدُ","aya_text_emlaey":"تلك الرسل فضلنا بعضهم على بعض منهم من كلم الله ورفع بعضهم درجات وآتينا عيسى ابن مريم البينات وأيدناه بروح القدس ولو شاء الله ما اقتتل الذين من بعدهم من بعد ما جاءتهم البينات ولكن اختلفوا فمنهم من آمن ومنهم من كفر ولو شاء الله ما اقتتلوا ولكن الله يفعل ما يريد","aya_tafseer":"[253] هؤلاء الرسل الكرام فضَّل الله بعضهم على بعض، بحسب ما منَّ الله به عليهم: فمنهم مَن كلمه الله كموسى ومحمد عليهما الصلاة والسلام، وفي هذا إثبات صفة الكلام لله عز وجل على الوجه اللائق بجلاله، ومنهم مَن رفعه الله درجاتٍ عاليةً كمحمد -صلى الله عليه وسلم-، بعموم رسالته، وخَتْمِ النبوة به، وتفضيلِ أمته على جميع الأمم، وغير ذلك. وآتى الله تعالى عيسى بن مريم عليه السلام البينات المعجزات الباهرات، كإبراء مَن وُلد أعمى بإذن الله تعالى، ومَن به برص بإذن الله، وكإحيائه الموتى بإذن الله، وأيده بجبريل عليه السلام. ولو شاء الله ألَّا يقتتل الذين جاؤوا مِن بعد هؤلاء الرسل، مِن بعد ما جاءتهم البينات ما اقتتلوا، ولكن وقع الاختلاف بينهم: فمنهم مَن ثبت على إيمانه، ومنهم مَن أصر على كفره. ولو شاء الله بعد ما وقع الاختلاف بينهم، الموجب للاقتتال، ما اقتتلوا، ولكن الله يوفق مَن يشاء لطاعته والإيمان به، ويخذل مَن يشاء، فيعصيه ويكفر به، فهو يفعل ما يشاء ويختار."},{"id":"261","jozz":"3","page":"42","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"6","line_end":"8","aya_no":"254","aya_text":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَنفِقُواْ مِمَّا رَزَقۡنَٰكُم مِّن قَبۡلِ أَن يَأۡتِيَ يَوۡمٞ لَّا بَيۡعٞ فِيهِ وَلَا خُلَّةٞ وَلَا شَفَٰعَةٞۗ وَٱلۡكَٰفِرُونَ هُمُ ٱلظَّٰلِمُونَ","aya_text_emlaey":"ياأيها الذين آمنوا أنفقوا مما رزقناكم من قبل أن يأتي يوم لا بيع فيه ولا خلة ولا شفاعة والكافرون هم الظالمون","aya_tafseer":"[254] يا من آمنتم بالله وصدَّقتم رسوله وعملتم بهديه أخرجوا الزكاة المفروضة، وتصدَّقوا مما أعطاكم الله قبل مجيء يوم القيامة، حين لا بيع فيكون ربح، ولا مال تفتدون به أنفسكم مِن عذاب الله، ولا صداقة صديق تُنقذكم، ولا شافع يملك تخفيف العذاب عنكم. والكافرون هم الظالمون المتجاوزون حدود الله."},{"id":"262","jozz":"3","page":"42","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"8","line_end":"13","aya_no":"255","aya_text":"ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡحَيُّ ٱلۡقَيُّومُۚ لَا تَأۡخُذُهُۥ سِنَةٞ وَلَا نَوۡمٞۚ لَّهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ مَن ذَا ٱلَّذِي يَشۡفَعُ عِندَهُۥٓ إِلَّا بِإِذۡنِهِۦۚ يَعۡلَمُ مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡۖ وَلَا يُحِيطُونَ بِشَيۡءٖ مِّنۡ عِلۡمِهِۦٓ إِلَّا بِمَا شَآءَۚ وَسِعَ كُرۡسِيُّهُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَۖ وَلَا يَـُٔودُهُۥ حِفۡظُهُمَاۚ وَهُوَ ٱلۡعَلِيُّ ٱلۡعَظِيمُ","aya_text_emlaey":"الله لا إله إلا هو الحي القيوم لا تأخذه سنة ولا نوم له ما في السموات وما في الأرض من ذا الذي يشفع عنده إلا بإذنه يعلم ما بين أيديهم وما خلفهم ولا يحيطون بشيء من علمه إلا بما شاء وسع كرسيه السموات والأرض ولا يئوده حفظهما وهو العلي العظيم","aya_tafseer":"[255] الله الذي لا يستحق الألوهية والعبودية إلا هو، الحيُّ الذي له جميع معاني الحياة الكاملة كما يليق بجلاله، القائم على كل شيء، لا تأخذه سِنَة أي: نعاس، ولا نوم، كل ما في السموات وما في الأرض ملك له، ولا يتجاسر أحد أن يشفع عنده إلا بإذنه، محيط علمه بجميع الكائنات ماضيها وحاضرها ومستقبلها، يعلم ما بين أيدي الخلائق من الأمور المستقبلة، وما خلفهم من الأمور الماضية، ولا يَطَّلِعُ أحد من الخلق على شيء من علمه إلا بما أعلمه الله وأطلعه عليه، وسع كرسيه السموات والأرض، والكرسي: هو موضع قدمي الرب -جل جلاله- ولا يعلم كيفيته إلا الله سبحانه، ولا يثقله سبحانه حفظهما، وهو العلي بذاته وصفاته على جميع مخلوقاته، الجامع لجميع صفات العظمة والكبرياء. وهذه الآية أعظم آية في القرآن، وتسمى: (آية الكرسي)."},{"id":"263","jozz":"3","page":"42","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"13","line_end":"15","aya_no":"256","aya_text":"لَآ إِكۡرَاهَ فِي ٱلدِّينِۖ قَد تَّبَيَّنَ ٱلرُّشۡدُ مِنَ ٱلۡغَيِّۚ فَمَن يَكۡفُرۡ بِٱلطَّٰغُوتِ وَيُؤۡمِنۢ بِٱللَّهِ فَقَدِ ٱسۡتَمۡسَكَ بِٱلۡعُرۡوَةِ ٱلۡوُثۡقَىٰ لَا ٱنفِصَامَ لَهَاۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ","aya_text_emlaey":"لا إكراه في الدين قد تبين الرشد من الغي فمن يكفر بالطاغوت ويؤمن بالله فقد استمسك بالعروة الوثقى لا انفصام لها والله سميع عليم","aya_tafseer":"[256] لكمال هذا الدين واتضاح آياته لا يُحتاج إلى الإكراه عليه، فالدلائل بينة يتضح بها الحق من الباطل، والهدى من الضلال. فَمَن يكفر بكل ما عُبِد من دون الله ويؤمن بالله، فقد ثبت واستقام على الطريقة المثلى، واستمسك من الدين بأقوى سبب لا انقطاع له. والله سميع لأقوال عباده، عليم بنياتهم وأفعالهم، وسيجازيهم على ذلك."},{"id":"264","jozz":"3","page":"43","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"1","line_end":"4","aya_no":"257","aya_text":"ٱللَّهُ وَلِيُّ ٱلَّذِينَ ءَامَنُواْ يُخۡرِجُهُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِۖ وَٱلَّذِينَ كَفَرُوٓاْ أَوۡلِيَآؤُهُمُ ٱلطَّٰغُوتُ يُخۡرِجُونَهُم مِّنَ ٱلنُّورِ إِلَى ٱلظُّلُمَٰتِۗ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ","aya_text_emlaey":"الله ولي الذين آمنوا يخرجهم من الظلمات إلى النور والذين كفروا أولياؤهم الطاغوت يخرجونهم من النور إلى الظلمات أولئك أصحاب النار هم فيها خالدون","aya_tafseer":"[257] الله يتولى المؤمنين بنصره وتوفيقه وحفظه، يخرجهم من ظلمات الكفر، إلى نور الإيمان. والذين كفروا أنصارهم وأولياؤهم الأنداد والأوثان الذين يعبدونهم من دون الله، يُخرجونهم من نور الإيمان إلى ظلمات الكفر، أولئك أصحاب النار الملازمون لها، هم فيها باقون بقاء أبديّاً لا يخرجون منها."},{"id":"265","jozz":"3","page":"43","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"4","line_end":"8","aya_no":"258","aya_text":"أَلَمۡ تَرَ إِلَى ٱلَّذِي حَآجَّ إِبۡرَٰهِـۧمَ فِي رَبِّهِۦٓ أَنۡ ءَاتَىٰهُ ٱللَّهُ ٱلۡمُلۡكَ إِذۡ قَالَ إِبۡرَٰهِـۧمُ رَبِّيَ ٱلَّذِي يُحۡيِۦ وَيُمِيتُ قَالَ أَنَا۠ أُحۡيِۦ وَأُمِيتُۖ قَالَ إِبۡرَٰهِـۧمُ فَإِنَّ ٱللَّهَ يَأۡتِي بِٱلشَّمۡسِ مِنَ ٱلۡمَشۡرِقِ فَأۡتِ بِهَا مِنَ ٱلۡمَغۡرِبِ فَبُهِتَ ٱلَّذِي كَفَرَۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ","aya_text_emlaey":"ألم تر إلى الذي حاج إبراهيم في ربه أن آتاه الله الملك إذ قال إبراهيم ربي الذي يحيي ويميت قال أنا أحيي وأميت قال إبراهيم فإن الله يأتي بالشمس من المشرق فأت بها من المغرب فبهت الذي كفر والله لا يهدي القوم الظالمين","aya_tafseer":"[258] هل رأيت -أيها الرسول- أعجب مِن حال هذا الذي جادل إبراهيم عليه السلام في توحيد الله تعالى وربوبيته؛ لأن الله أعطاه المُلْك فتجبَّر وسأل إبراهيمَ: مَن ربُّك؟ فقال عليه السلام: ربي الذي يحيي الخلائق فتحيا، ويَسْلُبها الحياة فتموت، فهو المتفرد بالإحياء والإماتة، قال: أنا أحيي وأميت، أي أقتل مَن أردت قَتْلَه، وأستبقي مَن أردت استبقاءه، فقال له إبراهيم: إن الله الذي أعبده يأتي بالشمس من المشرق، فهل تستطيع تغيير هذه السُّنَّة الإلهية بأن تجعلها تأتي من المغرب؟ فتحيَّر هذا الكافر وانقطعت حجته، شأنه شأن الظالمين لا يهديهم الله إلى الحق والصواب."},{"id":"266","jozz":"3","page":"43","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"8","line_end":"15","aya_no":"259","aya_text":"أَوۡ كَٱلَّذِي مَرَّ عَلَىٰ قَرۡيَةٖ وَهِيَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا قَالَ أَنَّىٰ يُحۡيِۦ هَٰذِهِ ٱللَّهُ بَعۡدَ مَوۡتِهَاۖ فَأَمَاتَهُ ٱللَّهُ مِاْئَةَ عَامٖ ثُمَّ بَعَثَهُۥۖ قَالَ كَمۡ لَبِثۡتَۖ قَالَ لَبِثۡتُ يَوۡمًا أَوۡ بَعۡضَ يَوۡمٖۖ قَالَ بَل لَّبِثۡتَ مِاْئَةَ عَامٖ فَٱنظُرۡ إِلَىٰ طَعَامِكَ وَشَرَابِكَ لَمۡ يَتَسَنَّهۡۖ وَٱنظُرۡ إِلَىٰ حِمَارِكَ وَلِنَجۡعَلَكَ ءَايَةٗ لِّلنَّاسِۖ وَٱنظُرۡ إِلَى ٱلۡعِظَامِ كَيۡفَ نُنشِزُهَا ثُمَّ نَكۡسُوهَا لَحۡمٗاۚ فَلَمَّا تَبَيَّنَ لَهُۥ قَالَ أَعۡلَمُ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ","aya_text_emlaey":"أو كالذي مر على قرية وهي خاوية على عروشها قال أنى يحيي هذه الله بعد موتها فأماته الله مائة عام ثم بعثه قال كم لبثت قال لبثت يوما أو بعض يوم قال بل لبثت مائة عام فانظر إلى طعامك وشرابك لم يتسنه وانظر إلى حمارك ولنجعلك آية للناس وانظر إلى العظام كيف ننشزها ثم نكسوها لحما فلما تبين له قال أعلم أن الله على كل شيء قدير","aya_tafseer":"[259] أو هل رأيت -أيها الرسول- مِثْلَ الذي مرَّ على قرية قد تهدَّمت دورها، وخَوَتْ على عروشها، فقال: كيف يحيي الله هذه القرية بعد موتها؟ فأماته الله مائة عام، ثم ردَّ إليه روحه، وقال له: كم قَدْر الزمان الذي لبثْتَ ميتاً؟ قال: بقيت يوماً أو بعض يوم، فأخبره بأنه بقي ميتاً مائة عام، وأمره أن ينظر إلى طعامه وشرابه، وكيف حفظهما الله من التغيُّر هذه المدة الطويلة، وأمره أن ينظر إلى حماره كيف أحياه الله بعد أن كان عظاماً متفرقة، وقال له: ولنجعلك آية للناس، أي: دلالة ظاهرة على قدرة الله على البعث بعد الموت، وأمره أن ينظر إلى العظام كيف يرفع الله بعضها على بعض، ويصل بعضها ببعض، ثم يكسوها بعد الالتئام لحماً، ثم يعيد فيها الحياة، فلما اتضح له ذلك عِياناً اعترف بعظمة الله، وأنه على كل شيء قدير، وصار آية للناس."},{"id":"267","jozz":"3","page":"44","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"1","line_end":"4","aya_no":"260","aya_text":"وَإِذۡ قَالَ إِبۡرَٰهِـۧمُ رَبِّ أَرِنِي كَيۡفَ تُحۡيِ ٱلۡمَوۡتَىٰۖ قَالَ أَوَلَمۡ تُؤۡمِنۖ قَالَ بَلَىٰ وَلَٰكِن لِّيَطۡمَئِنَّ قَلۡبِيۖ قَالَ فَخُذۡ أَرۡبَعَةٗ مِّنَ ٱلطَّيۡرِ فَصُرۡهُنَّ إِلَيۡكَ ثُمَّ ٱجۡعَلۡ عَلَىٰ كُلِّ جَبَلٖ مِّنۡهُنَّ جُزۡءٗا ثُمَّ ٱدۡعُهُنَّ يَأۡتِينَكَ سَعۡيٗاۚ وَٱعۡلَمۡ أَنَّ ٱللَّهَ عَزِيزٌ حَكِيمٞ","aya_text_emlaey":"وإذ قال إبراهيم رب أرني كيف تحي الموتى قال أو لم تؤمن قال بلى ولكن ليطمئن قلبي قال فخذ أربعة من الطير فصرهن إليك ثم اجعل على كل جبل منهن جزءا ثم ادعهن يأتينك سعيا واعلم أن الله عزيز حكيم","aya_tafseer":"[260] واذكر -أيها الرسول- طلب إبراهيم من ربه أن يريه كيفية البعث، فقال الله له: أَوَ لم تؤمن؟ قال: بلى، ولكن أطلب ذلك لأزداد يقيناً على يقيني، قال: فخذ أربعة من الطير فاضممهن إليك واذبحهن وقطعهن، ثم اجعل على كل جبل منهن جزءاً، ثم نادِهن يأتينك مسرعات. فنادى إبراهيم عليه السلام، فإذا كل جزء يعود إلى موضعه، وإذا بها تأتي مسرعة. واعلم أن الله عزيز لا يغلبه شيء، حكيم في أقواله وأفعاله وشرعه وقدره."},{"id":"268","jozz":"3","page":"44","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"5","line_end":"7","aya_no":"261","aya_text":"مَّثَلُ ٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُمۡ فِي سَبِيلِ ٱللَّهِ كَمَثَلِ حَبَّةٍ أَنۢبَتَتۡ سَبۡعَ سَنَابِلَ فِي كُلِّ سُنۢبُلَةٖ مِّاْئَةُ حَبَّةٖۗ وَٱللَّهُ يُضَٰعِفُ لِمَن يَشَآءُۚ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ","aya_text_emlaey":"مثل الذين ينفقون أموالهم في سبيل الله كمثل حبة أنبتت سبع سنابل في كل سنبلة مائة حبة والله يضاعف لمن يشاء والله واسع عليم","aya_tafseer":"[261] ومِن أعظم ما ينتفع به المؤمنون الإنفاقُ في سبيل الله. ومَثَلُ المؤمنين الذين ينفقون أموالهم في سبيل الله كمثل حبة زُرِعتْ في أرض طيبة، فإذا بها قد أخرجت ساقاً تشعب منها سبع شعب، لكل واحدة سنبلة، في كل سنبلة مائة حبة. والله يضاعف الأجر لمن يشاء، بحسب ما يقوم بقلب المنفق من الإيمان والإخلاص التام. وفضل الله واسع، وهو سبحانه عليم بمن يستحقه، مطلع على نيات عباده."},{"id":"269","jozz":"3","page":"44","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"7","line_end":"10","aya_no":"262","aya_text":"ٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُمۡ فِي سَبِيلِ ٱللَّهِ ثُمَّ لَا يُتۡبِعُونَ مَآ أَنفَقُواْ مَنّٗا وَلَآ أَذٗى لَّهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ","aya_text_emlaey":"الذين ينفقون أموالهم في سبيل الله ثم لا يتبعون ما أنفقوا منا ولا أذى لهم أجرهم عند ربهم ولا خوف عليهم ولا هم يحزنون","aya_tafseer":"[262] الذين يخرجون أموالهم في الجهاد وأنواع الخير، ثم لا يتبعون ما أنفقوا من الخيرات منّاً على مَن أعطَوه ولا أذى بقول أو فِعْلٍ يشعره بالتفضل عليه، لهم ثوابهم العظيم عند ربهم، ولا خوف عليهم فيما يستقبلونه من أمر الآخرة، ولا هم يحزنون على شيء فاتهم في هذه الدنيا."},{"id":"270","jozz":"3","page":"44","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"10","line_end":"11","aya_no":"263","aya_text":"۞ قَوۡلٞ مَّعۡرُوفٞ وَمَغۡفِرَةٌ خَيۡرٞ مِّن صَدَقَةٖ يَتۡبَعُهَآ أَذٗىۗ وَٱللَّهُ غَنِيٌّ حَلِيمٞ","aya_text_emlaey":"قول معروف ومغفرة خير من صدقة يتبعها أذى والله غني حليم","aya_tafseer":"[263] كلام طيب يُرَدُّ به السائل، وعفو عما بدر منه مِن إلحاحٍ في السؤال، خير من صدقة يتبعها من المتصدق أذى وإساءة. والله غني عن صدقات العباد، حليم لا يعاجلهم بالعقوبة."},{"id":"271","jozz":"3","page":"44","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"11","line_end":"15","aya_no":"264","aya_text":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُبۡطِلُواْ صَدَقَٰتِكُم بِٱلۡمَنِّ وَٱلۡأَذَىٰ كَٱلَّذِي يُنفِقُ مَالَهُۥ رِئَآءَ ٱلنَّاسِ وَلَا يُؤۡمِنُ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۖ فَمَثَلُهُۥ كَمَثَلِ صَفۡوَانٍ عَلَيۡهِ تُرَابٞ فَأَصَابَهُۥ وَابِلٞ فَتَرَكَهُۥ صَلۡدٗاۖ لَّا يَقۡدِرُونَ عَلَىٰ شَيۡءٖ مِّمَّا كَسَبُواْۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡكَٰفِرِينَ","aya_text_emlaey":"ياأيها الذين آمنوا لا تبطلوا صدقاتكم بالمن والأذى كالذي ينفق ماله رئاء الناس ولا يؤمن بالله واليوم الآخر فمثله كمثل صفوان عليه تراب فأصابه وابل فتركه صلدا لا يقدرون على شيء مما كسبوا والله لا يهدي القوم الكافرين","aya_tafseer":"[264] يا من آمنتم بالله واليوم الآخر لا تُذْهِبُوا ثواب ما تتصدقون به بالمنِّ والأذى، فهذا شبيه بالذي يخرج ماله ليراه الناس، فيُثنوا عليه، وهو لا يؤمن بالله ولا يوقن باليوم الآخر، فمَثَلُ ذلك مَثَلُ حجر أملس عليه تراب هطل عليه مطر غزير فأزاح عنه التراب، فتركه أملس لا شيء عليه، فكذلك هؤلاء المراؤون تضمحلُّ أعمالهم عند الله، ولا يجدون شيئاً من الثواب على ما أنفقوه. والله لا يوفق الكافرين لإصابة الحق في نفقاتهم وغيرها."},{"id":"272","jozz":"3","page":"45","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"1","line_end":"4","aya_no":"265","aya_text":"وَمَثَلُ ٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُمُ ٱبۡتِغَآءَ مَرۡضَاتِ ٱللَّهِ وَتَثۡبِيتٗا مِّنۡ أَنفُسِهِمۡ كَمَثَلِ جَنَّةِۭ بِرَبۡوَةٍ أَصَابَهَا وَابِلٞ فَـَٔاتَتۡ أُكُلَهَا ضِعۡفَيۡنِ فَإِن لَّمۡ يُصِبۡهَا وَابِلٞ فَطَلّٞۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرٌ","aya_text_emlaey":"ومثل الذين ينفقون أموالهم ابتغاء مرضات الله وتثبيتا من أنفسهم كمثل جنة بربوة أصابها وابل فآتت أكلها ضعفين فإن لم يصبها وابل فطل والله بما تعملون بصير","aya_tafseer":"[265] ومثل الذين ينفقون أموالهم طلباً لرضا الله واعتقاداً راسخاً بصدق وعده، كمثل بستان عظيم بأرض عالية طيبة هطلت عليه أمطار غزيرة، فتضاعفت ثمراته، وإن لم تسقط عليه الأمطار الغزيرة فيكفيه رذاذ المطر ليعطي الثمرة المضاعفة، وكذلك نفقات المخلصين تُقْبل عند الله وتُضاعف، قَلَّتْ أم كثُرت، فالله المُطَّلِع على السرائر، البصير بالظواهر والبواطن، يثيب كُلّاً بحسب إخلاصه."},{"id":"273","jozz":"3","page":"45","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"4","line_end":"8","aya_no":"266","aya_text":"أَيَوَدُّ أَحَدُكُمۡ أَن تَكُونَ لَهُۥ جَنَّةٞ مِّن نَّخِيلٖ وَأَعۡنَابٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ لَهُۥ فِيهَا مِن كُلِّ ٱلثَّمَرَٰتِ وَأَصَابَهُ ٱلۡكِبَرُ وَلَهُۥ ذُرِّيَّةٞ ضُعَفَآءُ فَأَصَابَهَآ إِعۡصَارٞ فِيهِ نَارٞ فَٱحۡتَرَقَتۡۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلۡأٓيَٰتِ لَعَلَّكُمۡ تَتَفَكَّرُونَ","aya_text_emlaey":"أيود أحدكم أن تكون له جنة من نخيل وأعناب تجري من تحتها الأنهار له فيها من كل الثمرات وأصابه الكبر وله ذرية ضعفاء فأصابها إعصار فيه نار فاحترقت كذلك يبين الله لكم الآيات لعلكم تتفكرون","aya_tafseer":"[266] أيرغب الواحد منكم أن يكون له بستان فيه النخيل والأعناب، تجري من تحت أشجاره المياه العذبة، وله فيه من كل ألوان الثمرات، وقد بلغ الكِبَر، ولا يستطيع أن يغرس مثل هذا الغرس، وله أولاد صغار في حاجة إلى هذا البستان، وفي هذه الحالة هبَّت عليه ريح شديدة، فيها نار محرقة فأحرقته؟ وهكذا حال غير المخلصين في نفقاتهم، يأتون يوم القيامة ولا حسنة لهم. بمثل هذا البيان يبيِّن الله لكم ما ينفعكم؛ كي تتأملوا، فتخلصوا نفقاتكم لله."},{"id":"274","jozz":"3","page":"45","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"8","line_end":"12","aya_no":"267","aya_text":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَنفِقُواْ مِن طَيِّبَٰتِ مَا كَسَبۡتُمۡ وَمِمَّآ أَخۡرَجۡنَا لَكُم مِّنَ ٱلۡأَرۡضِۖ وَلَا تَيَمَّمُواْ ٱلۡخَبِيثَ مِنۡهُ تُنفِقُونَ وَلَسۡتُم بِـَٔاخِذِيهِ إِلَّآ أَن تُغۡمِضُواْ فِيهِۚ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ غَنِيٌّ حَمِيدٌ","aya_text_emlaey":"ياأيها الذين آمنوا أنفقوا من طيبات ما كسبتم ومما أخرجنا لكم من الأرض ولا تيمموا الخبيث منه تنفقون ولستم بآخذيه إلا أن تغمضوا فيه واعلموا أن الله غني حميد","aya_tafseer":"[267] يامن آمنتم بي واتبعتم رسلي أنفقوا من الحلال الطيب الذي كسبتموه ومما أخرجنا لكم من الأرض، ولا تقصدوا الرديء منه لتعطوه الفقراء، ولو أُعطِيتموه لم تأخذوه إلا إذا تغاضيتم عما فيه من رداءة ونقص. فكيف ترضون لله ما لا ترضونه لأنفسكم؟ واعلموا أن الله الذي رزقكم غني عن صدقاتكم، مستحق للثناء، محمود في كل حال."},{"id":"275","jozz":"3","page":"45","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"12","line_end":"13","aya_no":"268","aya_text":"ٱلشَّيۡطَٰنُ يَعِدُكُمُ ٱلۡفَقۡرَ وَيَأۡمُرُكُم بِٱلۡفَحۡشَآءِۖ وَٱللَّهُ يَعِدُكُم مَّغۡفِرَةٗ مِّنۡهُ وَفَضۡلٗاۗ وَٱللَّهُ وَٰسِعٌ عَلِيمٞ","aya_text_emlaey":"الشيطان يعدكم الفقر ويأمركم بالفحشاء والله يعدكم مغفرة منه وفضلا والله واسع عليم","aya_tafseer":"[268] هذا البخل واختيار الرديء للصدقة من الشيطان الذي يخوفكم الفقر، ويغريكم بالبخل، ويأمركم بالمعاصي ومخالفة الله تعالى، والله سبحانه وتعالى يعدكم على إنفاقكم غفراناً لذنوبكم ورزقاً واسعاً. والله واسع الفضل، عليم بالنيَّات والأعمال."},{"id":"276","jozz":"3","page":"45","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"14","line_end":"15","aya_no":"269","aya_text":"يُؤۡتِي ٱلۡحِكۡمَةَ مَن يَشَآءُۚ وَمَن يُؤۡتَ ٱلۡحِكۡمَةَ فَقَدۡ أُوتِيَ خَيۡرٗا كَثِيرٗاۗ وَمَا يَذَّكَّرُ إِلَّآ أُوْلُواْ ٱلۡأَلۡبَٰبِ","aya_text_emlaey":"يؤتي الحكمة من يشاء ومن يؤت الحكمة فقد أوتي خيرا كثيرا وما يذكر إلا أولو الألباب","aya_tafseer":"[269] يؤتي الله الإصابة في القول والفعل مَن يشاء من عباده، ومَن أنعم الله عليه بذلك فقد أعطاه خيراً كثيراً. وما يتذكر هذا وينتفع به إلا أصحاب العقول المستنيرة بنور الله وهدايته."},{"id":"277","jozz":"3","page":"46","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"1","line_end":"2","aya_no":"270","aya_text":"وَمَآ أَنفَقۡتُم مِّن نَّفَقَةٍ أَوۡ نَذَرۡتُم مِّن نَّذۡرٖ فَإِنَّ ٱللَّهَ يَعۡلَمُهُۥۗ وَمَا لِلظَّٰلِمِينَ مِنۡ أَنصَارٍ","aya_text_emlaey":"وما أنفقتم من نفقة أو نذرتم من نذر فإن الله يعلمه وما للظالمين من أنصار","aya_tafseer":"[270] وما أعطيتم من مال أو غيره قليل أو كثير تتصدقون به ابتغاء مرضات الله، أو أوجبتم على أنفسكم شيئاً من مال أو غيره، فإن الله يعلمه، وهو المُطَّلِع على نياتكم، وسوف يثيبكم على ذلك. ومَن منع حق الله فهو ظالم، والظالمون ليس لهم أنصار يمنعونهم من عذاب الله."},{"id":"278","jozz":"3","page":"46","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"2","line_end":"5","aya_no":"271","aya_text":"إِن تُبۡدُواْ ٱلصَّدَقَٰتِ فَنِعِمَّا هِيَۖ وَإِن تُخۡفُوهَا وَتُؤۡتُوهَا ٱلۡفُقَرَآءَ فَهُوَ خَيۡرٞ لَّكُمۡۚ وَيُكَفِّرُ عَنكُم مِّن سَيِّـَٔاتِكُمۡۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرٞ","aya_text_emlaey":"إن تبدوا الصدقات فنعما هي وإن تخفوها وتؤتوها الفقراء فهو خير لكم ويكفر عنكم من سيئاتكم والله بما تعملون خبير","aya_tafseer":"[271] إن تظهروا ما تتصدقون به لله فنِعْمَ ما تصدقتم به، وإن تسرُّوا بها، وتعطوها الفقراء فهذا أفضل لكم؛ لأنه أبعد عن الرياء، وفي الصدقة -مع الإخلاص- محو لذنوبكم. والله الذي يعلم دقائق الأمور، لا يخفى عليه شيء من أحوالكم، وسيجازي كُلّاً بعمله."},{"id":"279","jozz":"3","page":"46","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"5","line_end":"9","aya_no":"272","aya_text":"۞ لَّيۡسَ عَلَيۡكَ هُدَىٰهُمۡ وَلَٰكِنَّ ٱللَّهَ يَهۡدِي مَن يَشَآءُۗ وَمَا تُنفِقُواْ مِنۡ خَيۡرٖ فَلِأَنفُسِكُمۡۚ وَمَا تُنفِقُونَ إِلَّا ٱبۡتِغَآءَ وَجۡهِ ٱللَّهِۚ وَمَا تُنفِقُواْ مِنۡ خَيۡرٖ يُوَفَّ إِلَيۡكُمۡ وَأَنتُمۡ لَا تُظۡلَمُونَ","aya_text_emlaey":"ليس عليك هداهم ولكن الله يهدي من يشاء وما تنفقوا من خير فلأنفسكم وما تنفقون إلا ابتغاء وجه الله وما تنفقوا من خير يوف إليكم وأنتم لا تظلمون","aya_tafseer":"[272] لست -أيها الرسول- مسؤولاً عن توفيق الكافرين للهداية، ولكن الله يشرح صدور مَن يشاء لدينه، ويوفقهم له. وما تبذلوا من مال يَعُدْ عليكم نَفْعُه من الله، والمؤمنون لا ينفقون إلا طلباً لمرضاة الله. وما تنفقوا من مال -مخلصين لله- تُوفَّوا ثوابه، ولا تُنْقَصُوا شيئاً من ذلك. وفي الآية إثبات صفة الوجه لله تعالى على ما يليق به سبحانه."},{"id":"280","jozz":"3","page":"46","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"9","line_end":"13","aya_no":"273","aya_text":"لِلۡفُقَرَآءِ ٱلَّذِينَ أُحۡصِرُواْ فِي سَبِيلِ ٱللَّهِ لَا يَسۡتَطِيعُونَ ضَرۡبٗا فِي ٱلۡأَرۡضِ يَحۡسَبُهُمُ ٱلۡجَاهِلُ أَغۡنِيَآءَ مِنَ ٱلتَّعَفُّفِ تَعۡرِفُهُم بِسِيمَٰهُمۡ لَا يَسۡـَٔلُونَ ٱلنَّاسَ إِلۡحَافٗاۗ وَمَا تُنفِقُواْ مِنۡ خَيۡرٖ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٌ","aya_text_emlaey":"للفقراء الذين أحصروا في سبيل الله لا يستطيعون ضربا في الأرض يحسبهم الجاهل أغنياء من التعفف تعرفهم بسيماهم لا يسألون الناس إلحافا وما تنفقوا من خير فإن الله به عليم","aya_tafseer":"[273] اجعلوا صدقاتكم لفقراء المسلمين الذين لا يستطيعون السفر؛ طلباً للرزق لاشتغالهم بالجهاد في سبيل الله، يظنهم مَن لا يعرفهم غير محتاجين إلى الصدقة؛ لتعففهم عن السؤال، تعرفهم بعلاماتهم وآثار الحاجة فيهم، لا يسألون الناس بالكُليَّة، وإن سألوا اضطراراً لم يُلِحُّوا في السؤال. وما تنفقوا مِن مالٍ في سبيل الله فلا يخفى على الله شيء منه، وسيجزي عليه أوفر الجزاء وأتمَّه يوم القيامة."},{"id":"281","jozz":"3","page":"46","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"13","line_end":"15","aya_no":"274","aya_text":"ٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُم بِٱلَّيۡلِ وَٱلنَّهَارِ سِرّٗا وَعَلَانِيَةٗ فَلَهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ","aya_text_emlaey":"الذين ينفقون أموالهم بالليل والنهار سرا وعلانية فلهم أجرهم عند ربهم ولا خوف عليهم ولا هم يحزنون","aya_tafseer":"[274] الذين يُخْرجون أموالهم مرضاة لله ليلاً ونهاراً مسرِّين ومعلنين، فلهم أجرهم عند ربهم، ولا خوف عليهم فيما يستقبلونه من أمر الآخرة، ولا هم يحزنون على ما فاتهم من حظوظ الدنيا. ذلك التشريع الإلهي الحكيم هو منهاج الإسلام في الإنفاق لما فيه مِن سدِّ حاجة الفقراء في كرامة وعزة، وتطهيرِ مال الأغنياء، وتحقيقِ التعاون على البر والتقوى؛ ابتغاء وجه الله دون قهر أو إكراه."},{"id":"282","jozz":"3","page":"47","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"1","line_end":"5","aya_no":"275","aya_text":"ٱلَّذِينَ يَأۡكُلُونَ ٱلرِّبَوٰاْ لَا يَقُومُونَ إِلَّا كَمَا يَقُومُ ٱلَّذِي يَتَخَبَّطُهُ ٱلشَّيۡطَٰنُ مِنَ ٱلۡمَسِّۚ ذَٰلِكَ بِأَنَّهُمۡ قَالُوٓاْ إِنَّمَا ٱلۡبَيۡعُ مِثۡلُ ٱلرِّبَوٰاْۗ وَأَحَلَّ ٱللَّهُ ٱلۡبَيۡعَ وَحَرَّمَ ٱلرِّبَوٰاْۚ فَمَن جَآءَهُۥ مَوۡعِظَةٞ مِّن رَّبِّهِۦ فَٱنتَهَىٰ فَلَهُۥ مَا سَلَفَ وَأَمۡرُهُۥٓ إِلَى ٱللَّهِۖ وَمَنۡ عَادَ فَأُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ","aya_text_emlaey":"الذين يأكلون الربا لا يقومون إلا كما يقوم الذي يتخبطه الشيطان من المس ذلك بأنهم قالوا إنما البيع مثل الربا وأحل الله البيع وحرم الربا فمن جاءه موعظة من ربه فانتهى فله ما سلف وأمره إلى الله ومن عاد فأولئك أصحاب النار هم فيها خالدون","aya_tafseer":"[275] الذين يتعاملون بالربا -وهو الزيادة على رأس المال- لا يقومون في الآخرة من قبورهم إلا كما يقوم الذي يتخبطه الشيطان من الجنون؛ ذلك لأنهم قالوا: إنما البيع مثل الربا، في أن كُلّاً منهما حلال، ويؤدي إلى زيادة المال، فأكذبهم الله، وبيَّن أنه أحل البيع وحرَّم الربا؛ لما في البيع والشراء مِن نفع للأفراد والجماعات، ولما في الربا من استغلال وضياع وهلاك. فمن بلغه نهي الله عن الربا فارتدع، فله ما مضى قبل أن يبلغه التحريم لا إثم عليه فيه، وأمره إلى الله فيما يستقبل من زمانه، فإن استمرَّ على توبته فالله لا يضيع أجر المحسنين، ومن عاد إلى الربا ففعله بعد بلوغه نهي الله عنه، فقد استوجب العقوبة، وقامت عليه الحجة، ولهذا قال سبحانه: فَأُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ ."},{"id":"283","jozz":"3","page":"47","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"5","line_end":"6","aya_no":"276","aya_text":"يَمۡحَقُ ٱللَّهُ ٱلرِّبَوٰاْ وَيُرۡبِي ٱلصَّدَقَٰتِۗ وَٱللَّهُ لَا يُحِبُّ كُلَّ كَفَّارٍ أَثِيمٍ","aya_text_emlaey":"يمحق الله الربا ويربي الصدقات والله لا يحب كل كفار أثيم","aya_tafseer":"[276] يُذهب الله الربا كلَّه، أو يَحْرِم صاحبه بركة ماله فلا ينتفع به، ويُنمِّي الصدقات ويكثرها، ويضاعف الأجر للمتصدقين، ويبارك لهم في أموالهم. والله لا يحب كُلَّ مُصِرٍّ على كفره، مُستحِلٍّ أكل الربا، متمادٍ في الإثم والحرام ومعاصي الله."},{"id":"284","jozz":"3","page":"47","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"7","line_end":"9","aya_no":"277","aya_text":"إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ وَأَقَامُواْ ٱلصَّلَوٰةَ وَءَاتَوُاْ ٱلزَّكَوٰةَ لَهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ","aya_text_emlaey":"إن الذين آمنوا وعملوا الصالحات وأقاموا الصلاة وآتوا الزكاة لهم أجرهم عند ربهم ولا خوف عليهم ولا هم يحزنون","aya_tafseer":"[277] إن الذين صدَّقوا الله ورسوله، وعملوا الأعمال الطيبة، وأدَّوا الصلاة كما أمر الله ورسوله، وأخرجوا زكاة أموالهم، لهم ثواب عظيم خاص بهم عند ربهم ورازقهم، ولا يلحقهم خوف في آخرتهم، ولا حزن على ما فاتهم من حظوظ دنياهم."},{"id":"285","jozz":"3","page":"47","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"9","line_end":"10","aya_no":"278","aya_text":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَذَرُواْ مَا بَقِيَ مِنَ ٱلرِّبَوٰٓاْ إِن كُنتُم مُّؤۡمِنِينَ","aya_text_emlaey":"ياأيها الذين آمنوا اتقوا الله وذروا ما بقي من الربا إن كنتم مؤمنين","aya_tafseer":"[278] يامن آمنتم بالله واتبعتم رسوله خافوا الله، واتركوا طلب ما بقي لكم من زيادة على رؤوس أموالكم التي كانت لكم قبل تحريم الربا، إن كنتم محققين إيمانكم قولاً وعملاً."},{"id":"286","jozz":"3","page":"47","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"10","line_end":"12","aya_no":"279","aya_text":"فَإِن لَّمۡ تَفۡعَلُواْ فَأۡذَنُواْ بِحَرۡبٖ مِّنَ ٱللَّهِ وَرَسُولِهِۦۖ وَإِن تُبۡتُمۡ فَلَكُمۡ رُءُوسُ أَمۡوَٰلِكُمۡ لَا تَظۡلِمُونَ وَلَا تُظۡلَمُونَ","aya_text_emlaey":"فإن لم تفعلوا فأذنوا بحرب من الله ورسوله وإن تبتم فلكم رءوس أموالكم لا تظلمون ولا تظلمون","aya_tafseer":"[279] فإن لم ترتدعوا عمَّا نهاكم الله عنه فاستيقنوا بحرب من الله ورسوله، وإن رجعتم إلى ربكم وتركتم أَكْلَ الربا فلكم أَخْذُ ما لكم من ديون، دون زيادة، لا تَظْلمون أحداً بأخذ ما زاد على رؤوس أموالكم، ولا يظلمكم أحد بنقص ما أقرضتم."},{"id":"287","jozz":"3","page":"47","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"12","line_end":"14","aya_no":"280","aya_text":"وَإِن كَانَ ذُو عُسۡرَةٖ فَنَظِرَةٌ إِلَىٰ مَيۡسَرَةٖۚ وَأَن تَصَدَّقُواْ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ","aya_text_emlaey":"وإن كان ذو عسرة فنظرة إلى ميسرة وأن تصدقوا خير لكم إن كنتم تعلمون","aya_tafseer":"[280] وإن كان المدين غير قادر على السداد فأمهلوه إلى أن ييسِّر الله له رزقاً فيدفع إليكم مالكم، وإن تتركوا رأس المال كلَّه أو بعضه وتضعوه عن المدين فهو أفضل لكم، إن كنتم تعلمون فَضْلَ ذلك، وأنَّه خير لكم في الدنيا والآخرة."},{"id":"288","jozz":"3","page":"47","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"14","line_end":"15","aya_no":"281","aya_text":"وَٱتَّقُواْ يَوۡمٗا تُرۡجَعُونَ فِيهِ إِلَى ٱللَّهِۖ ثُمَّ تُوَفَّىٰ كُلُّ نَفۡسٖ مَّا كَسَبَتۡ وَهُمۡ لَا يُظۡلَمُونَ","aya_text_emlaey":"واتقوا يوما ترجعون فيه إلى الله ثم توفى كل نفس ما كسبت وهم لا يظلمون","aya_tafseer":"[281] واحذروا -أيها الناس- يوماً ترجعون فيه إلى الله، وهو يوم القيامة، حيث تعرضون على الله ليحاسبكم، فيجازي كل واحد منكم بما عمل من خير أو شر دون أن يناله ظلم. وفي الآية إشارة إلى أن اجتناب ما حرم الله من المكاسب الربوية، تكميل للإيمان وحقوقه من إقام الصلاة وإيتاء الزكاة وعمل الصالحات."},{"id":"289","jozz":"3","page":"48","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"1","line_end":"15","aya_no":"282","aya_text":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا تَدَايَنتُم بِدَيۡنٍ إِلَىٰٓ أَجَلٖ مُّسَمّٗى فَٱكۡتُبُوهُۚ وَلۡيَكۡتُب بَّيۡنَكُمۡ كَاتِبُۢ بِٱلۡعَدۡلِۚ وَلَا يَأۡبَ كَاتِبٌ أَن يَكۡتُبَ كَمَا عَلَّمَهُ ٱللَّهُۚ فَلۡيَكۡتُبۡ وَلۡيُمۡلِلِ ٱلَّذِي عَلَيۡهِ ٱلۡحَقُّ وَلۡيَتَّقِ ٱللَّهَ رَبَّهُۥ وَلَا يَبۡخَسۡ مِنۡهُ شَيۡـٔٗاۚ فَإِن كَانَ ٱلَّذِي عَلَيۡهِ ٱلۡحَقُّ سَفِيهًا أَوۡ ضَعِيفًا أَوۡ لَا يَسۡتَطِيعُ أَن يُمِلَّ هُوَ فَلۡيُمۡلِلۡ وَلِيُّهُۥ بِٱلۡعَدۡلِۚ وَٱسۡتَشۡهِدُواْ شَهِيدَيۡنِ مِن رِّجَالِكُمۡۖ فَإِن لَّمۡ يَكُونَا رَجُلَيۡنِ فَرَجُلٞ وَٱمۡرَأَتَانِ مِمَّن تَرۡضَوۡنَ مِنَ ٱلشُّهَدَآءِ أَن تَضِلَّ إِحۡدَىٰهُمَا فَتُذَكِّرَ إِحۡدَىٰهُمَا ٱلۡأُخۡرَىٰۚ وَلَا يَأۡبَ ٱلشُّهَدَآءُ إِذَا مَا دُعُواْۚ وَلَا تَسۡـَٔمُوٓاْ أَن تَكۡتُبُوهُ صَغِيرًا أَوۡ كَبِيرًا إِلَىٰٓ أَجَلِهِۦۚ ذَٰلِكُمۡ أَقۡسَطُ عِندَ ٱللَّهِ وَأَقۡوَمُ لِلشَّهَٰدَةِ وَأَدۡنَىٰٓ أَلَّا تَرۡتَابُوٓاْ إِلَّآ أَن تَكُونَ تِجَٰرَةً حَاضِرَةٗ تُدِيرُونَهَا بَيۡنَكُمۡ فَلَيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَلَّا تَكۡتُبُوهَاۗ وَأَشۡهِدُوٓاْ إِذَا تَبَايَعۡتُمۡۚ وَلَا يُضَآرَّ كَاتِبٞ وَلَا شَهِيدٞۚ وَإِن تَفۡعَلُواْ فَإِنَّهُۥ فُسُوقُۢ بِكُمۡۗ وَٱتَّقُواْ ٱللَّهَۖ وَيُعَلِّمُكُمُ ٱللَّهُۗ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمٞ","aya_text_emlaey":"ياأيها الذين آمنوا إذا تداينتم بدين إلى أجل مسمى فاكتبوه وليكتب بينكم كاتب بالعدل ولا يأب كاتب أن يكتب كما علمه الله فليكتب وليملل الذي عليه الحق وليتق الله ربه ولا يبخس منه شيئا فإن كان الذي عليه الحق سفيها أو ضعيفا أو لا يستطيع أن يمل هو فليملل وليه بالعدل واستشهدوا شهيدين من رجالكم فإن لم يكونا رجلين فرجل وامرأتان ممن ترضون من الشهداء أن تضل إحداهما فتذكر إحداهما الأخرى ولا يأب الشهداء إذا ما دعوا ولا تسأموا أن تكتبوه صغيرا أو كبيرا إلى أجله ذلكم أقسط عند الله وأقوم للشهادة وأدنى ألا ترتابوا إلا أن تكون تجارة حاضرة تديرونها بينكم فليس عليكم جناح ألا تكتبوها وأشهدوا إذا تبايعتم ولا يضار كاتب ولا شهيد وإن تفعلوا فإنه فسوق بكم واتقوا الله ويعلمكم الله والله بكل شيء عليم","aya_tafseer":"[282] يامن آمنتم بالله واتبعتم رسوله محمداً -صلى الله عليه وسلم- إذا تعاملتم بدَيْن إلى وقت معلوم فاكتبوه؛ حفظاً للمال ودفعاً للنزاع. ولْيقُم بالكتابة رجل أمين ضابط، ولا يمتنع مَن علَّمه الله الكتابة عن ذلك، ولْيقم المدين بإملاء ما عليه من الدَّين، وليراقب ربه، ولا يَنقص مِن دَينه شيئاً. فإن كان المدين لا يحسن التصرف في ماله، أو كان صغيراً أو مجنوناً، أو لا يستطيع النطق لخرسٍ به أو عدم قدرة كاملة على الكلام، فليتولَّ الإملاء عن المدين القائمُ بأمره، واطلبوا شهادة رجلين مسلمَيْن بالِغَيْن عاقلَيْن من أهل العدالة، فإن لم يوجد رجلان، فاطلبوا شهادة رجل وامرأتين تَرضَون شهادتهم؛ حتى إذا نَسِيَتْ إحداهما ذكَّرتها الأخرى، وعلى الشهداء أن يجيبوا مَن دعاهم إلى الشهادة، وعليهم أداؤها إذا ما دُعُوا إليها، ولا تَمَلُّوا من كتابة الدَّين قليلاً أو كثيراً إلى وقته المعلوم. ذلكم أعدل في شرع الله وهديه، وأعظم عوناً على إقامة الشهادة وأدائها، وأقرب إلى نفي الشك في جنس الدَّين وقَدْره وأجله، لكن إن كانت المسألة مسألة بيع وشراء، بأخذ سلعة ودفع ثمنها في الحال، فلا حاجة إلى الكتابة، ويستحب الإشهاد على ذلك منعاً للنزاع والشقاق، ومن الواجب على الشاهد والكاتب أداء الشهادة على وجهها والكتابة كما أمر الله، ولا يجوز لصاحب الحق ومَن عليه الحق الإضرار بالكُتَّاب والشهود، وكذلك لا يجوز للكُتَّاب والشهود أن يضارُّوا بمن احتاج إلى كتابتهم أو شهادتهم، وإن تفعلوا ما نُهِيتم عنه فإنه خروج عن طاعة الله، وعاقبة ذلك حالَّة بكم. وخافوا الله في جميع ما أمركم به، ونهاكم عنه، ويعلمكم الله جميع ما يصلح دنياكم وأخراكم. والله بكل شيء عليم، فلا يخفى عليه شيء من أموركم، وسيجازيكم على ذلك."},{"id":"290","jozz":"3","page":"49","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"1","line_end":"4","aya_no":"283","aya_text":"۞ وَإِن كُنتُمۡ عَلَىٰ سَفَرٖ وَلَمۡ تَجِدُواْ كَاتِبٗا فَرِهَٰنٞ مَّقۡبُوضَةٞۖ فَإِنۡ أَمِنَ بَعۡضُكُم بَعۡضٗا فَلۡيُؤَدِّ ٱلَّذِي ٱؤۡتُمِنَ أَمَٰنَتَهُۥ وَلۡيَتَّقِ ٱللَّهَ رَبَّهُۥۗ وَلَا تَكۡتُمُواْ ٱلشَّهَٰدَةَۚ وَمَن يَكۡتُمۡهَا فَإِنَّهُۥٓ ءَاثِمٞ قَلۡبُهُۥۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ عَلِيمٞ","aya_text_emlaey":"وإن كنتم على سفر ولم تجدوا كاتبا فرهان مقبوضة فإن أمن بعضكم بعضا فليؤد الذي اؤتمن أمانته وليتق الله ربه ولا تكتموا الشهادة ومن يكتمها فإنه آثم قلبه والله بما تعملون عليم","aya_tafseer":"[283] وإن كنتم مسافرين ولم تجدوا مَن يكتب لكم فادفعوا إلى صاحب الحق شيئاً يكون عنده ضماناً لحقِّه إلى أن يردَّ المدينُ ما عليه مِن دين، فإن وثق بعضكم ببعض فلا حرج في ترك الكتابة والإشهاد والرهن، ويبقى الدَّين أمانة في ذمَّة المدين، عليه أداؤه، وعليه أن يراقب الله فلا يخون صاحبه. فإن أنكر المدين ما عليه من دين، وكان هناك مَن حضر وشهد، فعليه أن يظهر شهادته، ومَن أخفى هذه الشهادة فهو صاحب قلب غادر فاجر. والله المُطَّلِع على السرائر، المحيط علمه بكل أموركم، وسيحاسبكم على ذلك."},{"id":"291","jozz":"3","page":"49","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"4","line_end":"7","aya_no":"284","aya_text":"لِّلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ وَإِن تُبۡدُواْ مَا فِيٓ أَنفُسِكُمۡ أَوۡ تُخۡفُوهُ يُحَاسِبۡكُم بِهِ ٱللَّهُۖ فَيَغۡفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ","aya_text_emlaey":"لله ما في السموات وما في الأرض وإن تبدوا ما في أنفسكم أو تخفوه يحاسبكم به الله فيغفر لمن يشاء ويعذب من يشاء والله على كل شيء قدير","aya_tafseer":"[284] لله ملك السموات والأرض وما فيهما ملكاً وتدبيراً وإحاطة، لا يخفى عليه شيء. وما تظهروه مما في أنفسكم أو تخفوه فإن الله يعلمه، وسيحاسبكم به، فيعفو عمن يشاء، ويؤاخذ من يشاء. والله قادر على كل شيء.وقد أكرم الله المسلمين بعد ذلك فعفا عن حديث النفس وخطرات القلب، ما لم يَتْبعها كلام أو عمل، كما ثبت ذلك عن رسول الله -صلى الله عليه وسلم-."},{"id":"292","jozz":"3","page":"49","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"7","line_end":"10","aya_no":"285","aya_text":"ءَامَنَ ٱلرَّسُولُ بِمَآ أُنزِلَ إِلَيۡهِ مِن رَّبِّهِۦ وَٱلۡمُؤۡمِنُونَۚ كُلٌّ ءَامَنَ بِٱللَّهِ وَمَلَٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ لَا نُفَرِّقُ بَيۡنَ أَحَدٖ مِّن رُّسُلِهِۦۚ وَقَالُواْ سَمِعۡنَا وَأَطَعۡنَاۖ غُفۡرَانَكَ رَبَّنَا وَإِلَيۡكَ ٱلۡمَصِيرُ","aya_text_emlaey":"آمن الرسول بما أنـزل إليه من ربه والمؤمنون كل آمن بالله وملائكته وكتبه ورسله لا نفرق بين أحد من رسله وقالوا سمعنا وأطعنا غفرانك ربنا وإليك المصير","aya_tafseer":"[285] صدَّق وأيقن رسول الله محمد -صلى الله عليه وسلم- بما أُوحِي إليه من ربه، وحُقَّ له أن يُوقن، والمؤمنون كذلك صدَّقوا وعملوا بالقرآن العظيم، كلٌّ منهم صدَّق بالله ربّاً وإلهاً متصفاً بصفات الجلال والكمال، وأن لله ملائكة كراماً، وأنه أنزل كتباً، وأرسل إلى خلقه رسلاً، لا نؤمن -نحن المؤمنين- ببعضهم وننكر بعضهم، بل نؤمن بهم جميعاً. وقال الرسول والمؤمنون: سمعنا يا ربنا ما أوحيت به، وأطعنا في كل ذلك، نرجو أن تغفر -بفضلك- ذنوبنا، فأنت الذي ربَّيتنا بما أنعمت به علينا، وإليك -وحدك- مرجعنا ومصيرنا."},{"id":"293","jozz":"3","page":"49","sura_no":"2","sura_name_en":"Al-Baqarah","sura_name_ar":"البَقَرَة ","line_start":"10","line_end":"15","aya_no":"286","aya_text":"لَا يُكَلِّفُ ٱللَّهُ نَفۡسًا إِلَّا وُسۡعَهَاۚ لَهَا مَا كَسَبَتۡ وَعَلَيۡهَا مَا ٱكۡتَسَبَتۡۗ رَبَّنَا لَا تُؤَاخِذۡنَآ إِن نَّسِينَآ أَوۡ أَخۡطَأۡنَاۚ رَبَّنَا وَلَا تَحۡمِلۡ عَلَيۡنَآ إِصۡرٗا كَمَا حَمَلۡتَهُۥ عَلَى ٱلَّذِينَ مِن قَبۡلِنَاۚ رَبَّنَا وَلَا تُحَمِّلۡنَا مَا لَا طَاقَةَ لَنَا بِهِۦۖ وَٱعۡفُ عَنَّا وَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَآۚ أَنتَ مَوۡلَىٰنَا فَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ","aya_text_emlaey":"لا يكلف الله نفسا إلا وسعها لها ما كسبت وعليها ما اكتسبت ربنا لا تؤاخذنا إن نسينا أو أخطأنا ربنا ولا تحمل علينا إصرا كما حملته على الذين من قبلنا ربنا ولا تحملنا ما لا طاقة لنا به واعف عنا واغفر لنا وارحمنا أنت مولانا فانصرنا على القوم الكافرين","aya_tafseer":"[286] دين الله يسر لا مشقة فيه، فلا يطلب الله مِن عباده ما لا يطيقونه، فمن فعل خيراً نال خيراً، ومن فعل شرّاً نال شرّاً. ربنا لا تعاقبنا إن نسينا شيئاً مما افترضته علينا، أو أخطأنا في فِعْل شيء نهيتنا عن فعله، ربَّنا ولا تكلِّفنا من الأعمال الشاقة ما كلَّفته مَن قبلنا من العصاة عقوبة لهم، ربنا ولا تُحمِّلْنا ما لا نستطيعه من التكاليف والمصائب، وامح ذنوبنا، واستر عيوبنا، وأحسن إلينا، أنت مالك أمرنا ومدبره، فانصرنا على مَن جحدوا دينك وأنكروا وحدانيتك، وكذَّبوا نبيَّك محمداً -صلى الله عليه وسلم-، واجعل العاقبة لنا عليهم في الدنيا والآخرة."}]
